using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;
using TMPro;

public class PauseUI : MonoBehaviour
{
    [SerializeField]
    Button _pauseButton;
    [SerializeField]
    Button _resumeButton;
    [SerializeField]
    TextMeshProUGUI _pauseText;
    [SerializeField]
    const string PAUSE_TEXT = "PAUSED";
    [SerializeField]
    const string PLAYING_TEXT = "PLAYING";

    public bool generateUI = true;

    private void Start()
    {
        if(generateUI)
        {
            GenerateUI();
        }
    }
    /// <summary>
    /// This function generates the UI
    /// </summary>
    private void GenerateUI()
    {
        // Adds a Vertical Layout Component to the main game object
        var verticalLayout = gameObject.AddComponent<VerticalLayoutGroup>();
        verticalLayout.spacing = 3;
        // Controls child height and width
        verticalLayout.childControlHeight = true;
        verticalLayout.childControlWidth = true;

        //Expand the children to match container size
        verticalLayout.childForceExpandHeight = true;
        verticalLayout.childForceExpandWidth = true;

        // The empty gameobject to hold the text element
        var textGO = new GameObject("PauseUI Text");
        textGO.transform.SetParent(transform, false);
        _pauseText = textGO.AddComponent<TextMeshProUGUI>();
        _pauseText.text = PLAYING_TEXT;
        _pauseText.enableAutoSizing = true;
        _pauseText.color = Color.black;

        // CREATE BUTTONS
        _pauseButton = CreateButton("PauseButton");
        _pauseButton.onClick.AddListener(OnPauseButtonPress);

        _resumeButton = CreateButton("ResumeButton");
        _resumeButton.onClick.AddListener(OnResumeButtonPress);
    }

    //This function creates the buttons
    private Button CreateButton(string buttonName)
    {
        //Safe way to create UI objects in script
        var buttonGO = new GameObject(buttonName);
        buttonGO.transform.SetParent(transform, false);
        buttonGO.AddComponent<RectTransform>();
        var btn = buttonGO.AddComponent<Button>();

        //Creates the image and sets the button target
        var buttonImage = buttonGO.AddComponent<Image>();
        btn.targetGraphic = buttonImage;

        //Safe way to create UI objects in script
        var textGO = new GameObject(buttonName + "Text");
        textGO.transform.SetParent(buttonGO.transform, false);

        //Create the text component with the given name, adjust size and sets the text color
        var buttonText = textGO.AddComponent<TextMeshProUGUI>();
        buttonText.text = buttonName;
        buttonText.enableAutoSizing = true;
        buttonText.color = Color.black;

        return btn;
    }

    private void OnEnable()
    {
        // Add listeners to buttons
        if(_pauseButton != null)
        {
            _pauseButton.onClick.AddListener(OnPauseButtonPress);
        }
        if(_resumeButton != null)
        {
            _resumeButton.onClick.AddListener(OnResumeButtonPress);
        }

        //Set the default text
        if(_pauseText != null)
        {
            _pauseText.text = PLAYING_TEXT;
        }
    }

    private void OnDisable()
    {
        //Remove listeners from the buttons
        if(_pauseButton != null)
        {
            _pauseButton.onClick.RemoveAllListeners();
        }
        if(_resumeButton != null)
        {
            _resumeButton.onClick.RemoveAllListeners();
        }
    }

    //Listener function for the Pause Button
    private void OnPauseButtonPress()
    {
        Time.timeScale = 0f;
        _pauseText.text = PAUSE_TEXT;
    }


    //Listener function for the Resume Button
    private void OnResumeButtonPress()
    {
        Time.timeScale = 1f;
        _pauseText.text = PLAYING_TEXT;
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;
using UnityEngine.Video;
using TMPro;

public class VideoPlayerUI : MonoBehaviour
{
    [Header("Video Player")]
    [SerializeField]
    private VideoPlayer _videoPlayer;
    [SerializeField]
    private int _playerWidth = 1280;
    [SerializeField]
    private int _playerHeight = 720;

    [Header("Generated Video Player Properties")]
    private GameObject _videoPlayerPanel;
    private Material _videoMat;
    private RenderTexture _videoPlayerTarget;
    [SerializeField]
    private VideoClip _clip;

    [Header("Play/Pause Button")]
    [SerializeField]
    private Button _playPauseButton;
    [SerializeField]
    private string _playText = "Play";
    [SerializeField]
    private string _pauseText = "Pause";
    [SerializeField]
    private bool _paused = false;

    [Header("Mute/Unmute Button")]
    [SerializeField]
    private Button _muteUnmuteButton;
    [SerializeField]
    private string _muteText = "Mute";
    [SerializeField]
    private string _unmuteText = "Unmute";
    [SerializeField]
    private bool _muted = false;

    [SerializeField]
    private bool _generateUI = true;



    private void Start()
    {
        if(_generateUI)
        {
            GenerateUI();
        }
    }

    //Function to generate the UI
    private void GenerateUI()
    {
        if(_clip == null)
        {
            Debug.LogWarning("No clip to play!");
        }

        var verticalLayout = gameObject.AddComponent<VerticalLayoutGroup>();
        verticalLayout.spacing = 3;
        verticalLayout.childControlHeight = true;
        verticalLayout.childControlWidth = true;
        verticalLayout.childForceExpandHeight = true;
        verticalLayout.childForceExpandWidth = true;


        //Video player
        _videoPlayerTarget = new RenderTexture(_playerWidth, _playerWidth, 16);
        _videoMat = new Material(Shader.Find("Unlit/Texture"));
        _videoMat.name = "VideoPlayerMat";
        _videoMat.mainTexture = _videoPlayerTarget;

        //Create and setup the video player to play to a render target
        _videoPlayer = gameObject.AddComponent<VideoPlayer>();
        _videoPlayer.clip = _clip;
        _videoPlayer.targetTexture = _videoPlayerTarget;
        _videoPlayer.Play();
        //Player screen
        _videoPlayerPanel = new GameObject("Video Player Panel");
        _videoPlayerPanel.transform.SetParent(transform);
        var panelRect = _videoPlayerPanel.AddComponent<RectTransform>();
        //UI anchor settings to expand the whole element to its container
        panelRect.anchorMax = new Vector2(1, 1);
        panelRect.anchorMin = new Vector2(0, 0);
        panelRect.anchoredPosition = new Vector2(0, 0);
        panelRect.sizeDelta = new Vector2(0, 0);
        var panelImage = _videoPlayerPanel.AddComponent<Image>();
        panelImage.material = _videoMat;

        // Setup the customized layout properties for the player
        var layoutElement = _videoPlayerPanel.AddComponent<LayoutElement>();
        layoutElement.preferredWidth = _playerWidth * 0.7f;
        layoutElement.preferredHeight = _playerHeight * 0.7f;
        layoutElement.minWidth = _playerWidth / 2.0f;
        layoutElement.minHeight = _playerHeight / 2.0f;

        //Create the buttons set the the button text
        _playPauseButton = CreateButton("Play/Pause Button");
        SetButtonText(_playPauseButton, _pauseText);
        _playPauseButton.onClick.AddListener(PlayPauseToggle);
        _muteUnmuteButton = CreateButton("Mute/Unmute Button");
        SetButtonText(_muteUnmuteButton, _muteText);
        _muteUnmuteButton.onClick.AddListener(MuteToggle);

    }

    //Function to create buttons for the UI
    private Button CreateButton(string buttonName)
    {
        //Parent gameobject for the button element
        var buttonGO = new GameObject(buttonName);
        buttonGO.transform.SetParent(transform, false);
        buttonGO.AddComponent<RectTransform>();
        var btn = buttonGO.AddComponent<Button>();

        // Button image and target graphic
        var buttonImage = buttonGO.AddComponent<Image>();
        btn.targetGraphic = buttonImage;

        // Button text 
        var textGO = new GameObject(buttonName + "Text");
        textGO.transform.SetParent(buttonGO.transform, false);
        var buttonText = textGO.AddComponent<TextMeshProUGUI>();
        buttonText.text = buttonName;
        buttonText.enableAutoSizing = true;
        buttonText.color = Color.black;

        return btn;
    }

    //Method to change the text of a particular button
    private void SetButtonText(Button btn, string text)
    {
        var buttonText = btn.GetComponentInChildren<TextMeshProUGUI>();
        if(buttonText != null)
        {
            buttonText.text = text;
        }
    }

    //Method to toggle the play/pause of the video player
    // When toggling play/pause the video player, update the button text, and set the boolean
    private void PlayPauseToggle()
    {
        if(_paused)
        {
            _videoPlayer.Play();
            SetButtonText(_playPauseButton, _pauseText);
            _paused = false;
        }
        else
        {
            _videoPlayer.Pause();
            SetButtonText(_playPauseButton, _playText);
            _paused = true;
        }
    }

    //Method to toggle the mute/unmute of the video player
    // When toggling mute/unmute the video player, update the button text, and set the boolean
    private void MuteToggle()
    {
        if(_muted)
        {
            _videoPlayer.SetDirectAudioMute(0, false);
            SetButtonText(_muteUnmuteButton, _muteText);
            _muted = false;
        }
        else
        {
            _videoPlayer.SetDirectAudioMute(0, true);
            SetButtonText(_muteUnmuteButton, _unmuteText);
            _muted = true;
        }
    }


}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using TMPro;
using System;

public class ClockUI : MonoBehaviour
{
    public bool generateUI = true;

    public TextMeshProUGUI clockText;

    private int currentTime = 0;

    private void Start()
    {
        if(generateUI)
        {
            GenerateUI();
        }

        if(clockText == null)
        {
            Debug.LogError("No Clock text");
            this.enabled = false;
            return;
        }

        //Starts the timer coroutine
        StartCoroutine(TimerCoroutine());
    }

    // Method to generate the UI
    private void GenerateUI()
    {
        //Create the text for the clock, set the color and alignment of the text to display
        var clockTextGO = new GameObject("Video Player Panel");
        clockTextGO.transform.SetParent(transform);
        var clockRect = clockTextGO.AddComponent<RectTransform>();
        clockText = clockTextGO.AddComponent<TextMeshProUGUI>();
        clockText.enableAutoSizing = true;
        clockText.color = Color.black;
        clockText.verticalAlignment = VerticalAlignmentOptions.Middle;
        clockText.horizontalAlignment = HorizontalAlignmentOptions.Center;


        // UI element anchor settings to expand to its container
        clockRect.anchorMax = new Vector2(1, 1);
        clockRect.anchorMin = new Vector2(0, 0);
        clockRect.anchoredPosition = new Vector2(0, 0);
        clockRect.sizeDelta = new Vector2(0, 0);


        //Starting clock text
        clockText.text = "00:00:00";
    }


    IEnumerator TimerCoroutine()
    {
        //Run indefinitely
        while (true)
        {
            var now = DateTime.Now;
            // Wait 1 second
            yield return new WaitForSeconds(1f);
            // After waiting update the timer then loop
            clockText.text = string.Format("{00:00}", now.Hour) + ":"
                + string.Format("{00:00}", now.Minute) + ":"
                + string.Format("{00:00}", now.Second);
        }
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;
using TMPro;
using System;

public class CounterUI : MonoBehaviour
{
    public bool generateUI = true;

    public TextMeshProUGUI counterText;
    private int counter = 0;

    public Button incrementButton;
    public Button decrementButton;

    private void Start()
    {
        if(generateUI)
        {
            GenerateUI();
        }
    }

    //Method to generate UI
    private void GenerateUI()
    {
        //Set the main object layout to contain elements horizontally and center them in the middle
        var parentLayoutGroup = gameObject.AddComponent<HorizontalLayoutGroup>();
        parentLayoutGroup.childAlignment = TextAnchor.MiddleCenter;

        // Create the decrements button at the left and add the listener
        decrementButton = CreateButton("-");
        decrementButton.onClick.AddListener(CounterDecrement);

        // Create the counter text at the middle, set the string, auto-size, color and alignment
        var counterTextGO = new GameObject("Video Player Panel");
        counterTextGO.transform.SetParent(transform);
        var counterRect = counterTextGO.AddComponent<RectTransform>();
        counterText = counterTextGO.AddComponent<TextMeshProUGUI>();
        counterText.text = counter.ToString();
        counterText.enableAutoSizing = true;
        counterText.color = Color.black;
        counterText.verticalAlignment = VerticalAlignmentOptions.Middle;
        counterText.horizontalAlignment = HorizontalAlignmentOptions.Center;

        // Create the increment button at the right and add the listener
        incrementButton = CreateButton("+");
        incrementButton.onClick.AddListener(CounterIncrement);
    }

    //Method to create button
    private Button CreateButton(string buttonName)
    {
        // Parent gameobject for the button
        var buttonGO = new GameObject(buttonName);
        buttonGO.transform.SetParent(transform, false);
        buttonGO.AddComponent<RectTransform>();
        var btn = buttonGO.AddComponent<Button>();

        //Button target image
        var buttonImage = buttonGO.AddComponent<Image>();
        btn.targetGraphic = buttonImage;

        // Create the text at the middle, set the string, auto-size, color and alignment
        var textGO = new GameObject(buttonName + "Text");
        textGO.transform.SetParent(buttonGO.transform, false);
        var buttonText = textGO.AddComponent<TextMeshProUGUI>();
        buttonText.text = buttonName;
        buttonText.enableAutoSizing = true;
        buttonText.verticalAlignment = VerticalAlignmentOptions.Middle;
        buttonText.horizontalAlignment = HorizontalAlignmentOptions.Center;

        buttonText.color = Color.black;

        return btn;
    }

    //Listener for the increment button
    private void CounterIncrement()
    {
        counter += 1;
        UpdateCounterText();
    }

    //Listener for the decrement button
    private void CounterDecrement()
    {
        counter -= 1;
        UpdateCounterText();
    }

    //Updater method for the counter text
    private void UpdateCounterText()
    {
        counterText.text = counter.ToString();
    }
}

using System;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;

public class PanelTween : MonoBehaviour
{
    public bool generateImage = true;
    public bool tweenOnStart = true;

    // Start and end size that can be edited in the inspector
    public Vector2 startSize = new Vector2(0.5f, 0.5f);
    public Vector2 endSize = new Vector2(1f, 1f);

    private RectTransform ownRect;
    // Tweening parameters
    [SerializeField]
    private bool tween = false;
    public float tweenInterval = 0.1f;
    public float tweenSpeed = 0.01f;

    private void Start()
    {
        // Get the own rect component for UI element
        ownRect = GetComponent<RectTransform>();
        if(generateImage)
        {
            GenerateImage();
        }

        if(tweenOnStart)
        {
            StartCoroutine(TweenSize());
        }
    }

    //Method to generate the image, can be modified to contain anything
    private void GenerateImage()
    {
        gameObject.AddComponent<Image>();
    }
    
    

    // Tweening coroutine
    IEnumerator TweenSize()
    {
        // Setup the tweening parametersm original width and height
        float t = 0f;
        float origw = ownRect.rect.width;
        float origh = ownRect.rect.height;
        float startw = startSize.x * origw;
        float starth = startSize.y * origh;

        ownRect.SetSizeWithCurrentAnchors(RectTransform.Axis.Horizontal, startw);
        ownRect.SetSizeWithCurrentAnchors(RectTransform.Axis.Vertical, starth);

        var waitDelegate = new WaitForSeconds(tweenInterval);
        tween = true;
        while(tween)
        {
            // Increment t
            t += tweenSpeed;
            var currentSize = Vector2.Lerp(startSize, endSize, t);
            float currentw = origw * currentSize.x;
            float currenth = origh * currentSize.y;
            ownRect.SetSizeWithCurrentAnchors(RectTransform.Axis.Horizontal, currentw);
            ownRect.SetSizeWithCurrentAnchors(RectTransform.Axis.Vertical, currenth);

            // Check if tween is over
            if(t >= 1f)
            {
                tween = false;
                break;
            }

            yield return waitDelegate;
        }
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;
using UnityEngine.SceneManagement;

public class SceneLoadingBar : MonoBehaviour
{
    public bool generateUI = true;
    // This needs to properly set in the inspector
    public string sceneToLoad = "NewScene";
    public bool loadSceneOnStart = true;

    public Slider loadingBar;
    private void Start()
    {
        if(generateUI)
        {
            GenerateUI();
        }

        // Check if has to load scene on start
        if(loadSceneOnStart)
        {
            StartCoroutine(LoadSceneCoroutine());
        }
    }

    // Method to generate the loading UI
    private void GenerateUI()
    {
        // This creates the background for the slider
        var backgroundImageGO = new GameObject("Background");
        backgroundImageGO.transform.SetParent(transform, false);
        var bgRect = backgroundImageGO.AddComponent<RectTransform>();
        // Background takes up the whole container with a grey color and is centered
        bgRect.anchorMin = new Vector2(0, 0);
        bgRect.anchorMax = new Vector2(1, 1);
        bgRect.sizeDelta = new Vector2(0, 0);
        bgRect.anchoredPosition = new Vector2(0, 0);
        var bgImage = backgroundImageGO.AddComponent<Image>();
        bgImage.color = Color.grey;

        // Fill area is the same size and shape as the background
        var fillAreaGO = new GameObject("FillArea");
        fillAreaGO.transform.SetParent(transform, false);
        var fillAreaRect = fillAreaGO.AddComponent<RectTransform>();
        fillAreaRect.anchorMin = new Vector2(0, 0);
        fillAreaRect.anchorMax = new Vector2(1, 1);
        fillAreaRect.sizeDelta = new Vector2(0, 0);
        fillAreaRect.anchoredPosition = new Vector2(0, 0);

        // Fill is setup to fill the fill area and fills it from left to right
        // Left to right fill requires anchors to be setup to scale from left to right
        var fillGO = new GameObject("Fill");
        fillGO.transform.SetParent(fillAreaGO.transform, false);
        var fillRect = fillGO.AddComponent<RectTransform>();
        fillRect.anchorMin = new Vector2(0, 0);
        fillRect.anchorMax = new Vector2(0, 1);
        fillRect.sizeDelta = new Vector2(0, 0);
        fillRect.anchoredPosition = new Vector2(0, 0);

        // Fill color will be green
        var fillImage = fillGO.AddComponent<Image>();
        fillImage.color = Color.green;

        // Add the main slider component and disable interaction from the user
        loadingBar = gameObject.AddComponent<Slider>();
        loadingBar.transition = Selectable.Transition.None;
        loadingBar.interactable = false;

        // Only need to set the fill rect
        loadingBar.fillRect = fillRect;
    }
    // Coroutine to load the scene
    IEnumerator LoadSceneCoroutine()
    {
        AsyncOperation operation = SceneManager.LoadSceneAsync(sceneToLoad);
        // Updates progress while the scene is loading
        while (!operation.isDone)
        {
            float progress = operation.progress;
            UpdateLoadingBar(progress);
            yield return null;
        }
    }

    // Method to update the loading bar progress (0-1) with whatever values there might be in the loading bar
    private void UpdateLoadingBar(float progress)
    {
        float p = loadingBar.maxValue * progress; // Convert to loading bar range
        loadingBar.value = p;
    }

}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;
using UnityEngine.SceneManagement;
using TMPro;

public class SceneLoadingBarWithHint : MonoBehaviour
{
    public bool generateUI = true;
    public string sceneToLoad = "NewScene";
    // A list of random hint texts, needs to be set in the inspector
    public List<string> hintsList = new List<string>();
    public TextMeshProUGUI hintText;
    public bool loadSceneOnStart = true;

    public Slider loadingBar;
    private void Start()
    {
        // Check if need to generate UI
        if(generateUI)
        {
            GenerateUI();
        }

        // Check if scene should be loaded on start
        if(loadSceneOnStart)
        {
            StartCoroutine(LoadSceneCoroutine());
        }

        if(hintsList.Count == 0)
        {
            Debug.LogError("No hint texts provided");
        }
    }

    //Method to create the UI
    private void GenerateUI()
    {
        // Creates a container for the loading bar and the hint text
        var layoutGO = new GameObject("Container");
        layoutGO.transform.SetParent(transform, false);
        var layoutRect = layoutGO.AddComponent<RectTransform>();
        layoutRect.anchorMin = new Vector2(0, 0);
        layoutRect.anchorMax = new Vector2(1, 1);
        layoutRect.sizeDelta = new Vector2(0, 0);
        layoutRect.anchoredPosition = new Vector2(0, 0);

        //Creates the layout as a vertical layout and controls the children sizes
        var verticalLayout = layoutGO.AddComponent<VerticalLayoutGroup>();
        verticalLayout.spacing = 3;
        verticalLayout.childControlHeight = true;
        verticalLayout.childControlWidth = true;
        verticalLayout.childForceExpandHeight = true;
        verticalLayout.childForceExpandWidth = true;

        // This creates the background for the slider
        var backgroundImageGO = new GameObject("Background");
        backgroundImageGO.transform.SetParent(layoutGO.transform, false);
        // Background takes up the whole container with a grey color and is centered
        var bgRect = backgroundImageGO.AddComponent<RectTransform>();
        bgRect.anchorMin = new Vector2(0, 0);
        bgRect.anchorMax = new Vector2(1, 1);
        bgRect.sizeDelta = new Vector2(0, 0);
        bgRect.anchoredPosition = new Vector2(0, 0);
        var bgImage = backgroundImageGO.AddComponent<Image>();
        bgImage.color = Color.grey;


        // Create the fillarea same as the background
        var fillAreaGO = new GameObject("FillArea");
        fillAreaGO.transform.SetParent(backgroundImageGO.transform, false);
        var fillAreaRect = fillAreaGO.AddComponent<RectTransform>();
        fillAreaRect.anchorMin = new Vector2(0, 0);
        fillAreaRect.anchorMax = new Vector2(1, 1);
        fillAreaRect.sizeDelta = new Vector2(0, 0);
        fillAreaRect.anchoredPosition = new Vector2(0, 0);

        // Fill is setup to fill the fill area and fills it from left to right
        // Left to right fill requires anchors to be setup to scale from left to right
        var fillGO = new GameObject("Fill");
        fillGO.transform.SetParent(fillAreaGO.transform, false);
        var fillRect = fillGO.AddComponent<RectTransform>();
        fillRect.anchorMin = new Vector2(0, 0);
        fillRect.anchorMax = new Vector2(0, 1);
        fillRect.sizeDelta = new Vector2(0, 0);
        fillRect.anchoredPosition = new Vector2(0, 0);

        // Fill color will be green
        var fillImage = fillGO.AddComponent<Image>();
        fillImage.color = Color.green;

        // Create a slider to control the bar, disable interaction
        loadingBar = gameObject.AddComponent<Slider>();
        loadingBar.transition = Selectable.Transition.None;
        loadingBar.interactable = false;

        // As it is not interactable we only need to set fill rect
        loadingBar.fillRect = fillRect;

        //HINTS TEXT creation, alignment
        var textGO = new GameObject("PauseUI Text");
        textGO.transform.SetParent(layoutGO.transform, false);
        hintText = textGO.AddComponent<TextMeshProUGUI>();
        hintText.text = "HINT";
        hintText.enableAutoSizing = true;
        hintText.color = Color.black;
        hintText.verticalAlignment = VerticalAlignmentOptions.Middle;
        hintText.horizontalAlignment = HorizontalAlignmentOptions.Center;

    }

    // Coroutine to load the scene
    IEnumerator LoadSceneCoroutine()
    {
        //Display the random hint
        DisplayRandomHint();
        AsyncOperation operation = SceneManager.LoadSceneAsync(sceneToLoad);
        // While scene is loading update the progress
        while (!operation.isDone)
        {
            float progress = operation.progress;
            UpdateLoadingBar(progress);
            yield return null;
        }
    }

    // Method to update the loading bar value
    private void UpdateLoadingBar(float progress)
    {
        float p = loadingBar.maxValue * progress; // Convert to loading bar range
        loadingBar.value = p;
    }

    // Method to display a random hint from the list
    private void DisplayRandomHint()
    {
        if (hintsList.Count == 0) return;
        hintText.text = hintsList[Random.Range(0, hintsList.Count)];
    }

}

using System;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;
using TMPro;

public class ObjectDestroyButtons : MonoBehaviour
{
    public List<GameObject> objectList = new List<GameObject>();
    private void Start()
    {
        if(objectList.Count == 0)
        {
            Debug.LogError("Please add objects to the list!");
            return;
        }

        GenerateUI();

    }

    //Method to generate the UI
    private void GenerateUI()
    {
        //Container for the buttons
        var layoutGO = new GameObject("Container");
        layoutGO.transform.SetParent(transform, false);
        var layoutRect = layoutGO.AddComponent<RectTransform>();
        //Container expands whole parent
        layoutRect.anchorMin = new Vector2(0, 0);
        layoutRect.anchorMax = new Vector2(1, 1);
        layoutRect.sizeDelta = new Vector2(0, 0);
        layoutRect.anchoredPosition = new Vector2(0, 0);

        // Buttons will be in a vertical layout
        var verticalLayout = layoutGO.AddComponent<VerticalLayoutGroup>();
        verticalLayout.spacing = 3;
        verticalLayout.childControlHeight = true;
        verticalLayout.childControlWidth = true;
        verticalLayout.childForceExpandHeight = true;
        verticalLayout.childForceExpandWidth = true;


        // For each object in the list create a button
        foreach(var obj in objectList)
        {
            // Create the button
            var button = CreateButton(obj.name + "Button", layoutGO.transform);
            // Add a listener to each button containing the closure for removing the object from the list, destroying the object and destroying the associated button
            button.onClick.AddListener(() =>
            {
                objectList.Remove(obj);
                Destroy(obj);
                Destroy(button.gameObject);
            });
        }
    }

    // Method to create button with a given name and a parent transform
    private Button CreateButton(string buttonName, Transform parent)
    {
        // Create the parent object for button elements
        var buttonGO = new GameObject(buttonName);
        buttonGO.transform.SetParent(parent, false);
        buttonGO.AddComponent<RectTransform>();
        var btn = buttonGO.AddComponent<Button>();

        // Create the button image
        var buttonImage = buttonGO.AddComponent<Image>();
