public class PanelCloseTween : MonoBehaviour
{
    public bool generateUI = true;
    // Close button, the rect of the panel and the starting size
    public Button closeButton;
    public RectTransform panelRect;
    private Vector2 startRect;

    public float animSpeed = 0.01f;

    private void Start()
    {
        // Check if it needs to generate the UI
        if (generateUI)
        {
            GenerateUI();
        }

        // Get the main rect
        panelRect = GetComponent<RectTransform>();
    }

    private void GenerateUI()
    {
        // Create panel image
        var imageComponent = gameObject.AddComponent<Image>();
        var bgColor = Color.white;
        bgColor.a = 0.5f;
        imageComponent.color = bgColor;

        // Set the rect to span the whole container
        var mainRect = GetComponent<RectTransform>();
        mainRect.anchorMin = new Vector2(0, 0);
        mainRect.anchorMax = new Vector2(1, 1);
        mainRect.sizeDelta = new Vector2(0, 0);
        mainRect.pivot = new Vector2(0.5f, 0.5f);

        // Create the close button which will be placed in a corner
        closeButton = CreateButton("X", transform);
        var buttonRect = closeButton.gameObject.GetComponent<RectTransform>();
        buttonRect.anchorMin = new Vector2(0, 1);
        buttonRect.anchorMax = new Vector2(0, 1);
        //buttonRect.sizeDelta = new Vector2(0, 0);
        buttonRect.pivot = new Vector2(0, 1);

        // Add the listener to the close button
        closeButton.onClick.AddListener(CloseButtonPressed);
    }
    // Method to create button with a given name and parent
    private Button CreateButton(string buttonName, Transform parent)
    {
        // Create container for the button
        var buttonGO = new GameObject(buttonName);
        buttonGO.transform.SetParent(parent, false);
        buttonGO.AddComponent<RectTransform>();
        var btn = buttonGO.AddComponent<Button>();

        // Create button image
        var buttonImage = buttonGO.AddComponent<Image>();
        btn.targetGraphic = buttonImage;

        // Create button text and set alignment and color
        var textGO = new GameObject(buttonName + "Text");
        textGO.transform.SetParent(buttonGO.transform, false);
        var buttonText = textGO.AddComponent<TextMeshProUGUI>();
        buttonText.text = buttonName;
        buttonText.enableAutoSizing = true;
        buttonText.verticalAlignment = VerticalAlignmentOptions.Middle;
        buttonText.horizontalAlignment = HorizontalAlignmentOptions.Center;

        buttonText.color = Color.black;

        return btn;
    }

    // Listener for the close button
    public void CloseButtonPressed()
    {
        // Start the shrinking coroutine
        StartCoroutine(ShrinkCloseCoroutine());
    }


    IEnumerator ShrinkCloseCoroutine()
    {
        // Initialize size
        float t = 0f;
        startRect = new Vector2(panelRect.rect.width, panelRect.rect.height);

        // While tweening continue
        while(true)
        {
            t += animSpeed;
            // Set the panel width and height according to current lerp value
            var lerp = Vector2.Lerp(startRect, Vector2.zero, t);
            panelRect.SetSizeWithCurrentAnchors(RectTransform.Axis.Horizontal, lerp.x);
            panelRect.SetSizeWithCurrentAnchors(RectTransform.Axis.Vertical, lerp.y);
            // Check if lerp is finished
            if(t >= 1f)
            {
                t = 0f;
                break;
            }

            // Skip frame
            yield return null;
        }

        // Set the panel to default size for opening next time
        panelRect.SetSizeWithCurrentAnchors(RectTransform.Axis.Horizontal, startRect.x);
        panelRect.SetSizeWithCurrentAnchors(RectTransform.Axis.Vertical, startRect.y);
        // Hide the panel by deactivation
        gameObject.SetActive(false);
    }
}

using System;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;

public class OrbitElementUI : MonoBehaviour
{
    public bool generateUI = true;

    // The radius of the circular orbit
    public float radius = 200;
    // The speed of the rotation around orbit
    public float speed = 2f;
    // The rect transform of the center point to orbit around
    public RectTransform centerPoint;
    // The rect transform of the 
    public RectTransform uiElementRect;

    // The current angle of rotation around the orbit
    private float angle = 0f;

    private void Start()
    {
        // If generateui is true then generate UI or else depend on the user to initialize fields
        if (generateUI)
        {
            GenerateUI();
        }

    }

    private void GenerateUI()
    {
        // The center of the orbit, just an empty rect transform that has this gameobject as parent
        var centerGO = new GameObject("Center");
        centerGO.transform.SetParent(transform, false);

        // Setup the center gameobject and modify anchors to center it in the container
        var centerRect = centerGO.AddComponent<RectTransform>();
        centerRect.anchorMin = new Vector2(0.5f, 0.5f);
        centerRect.anchorMax = new Vector2(0.5f, 0.5f);
        centerRect.pivot = new Vector2(0.5f, 0.5f);

        // Assign the center rect
        centerPoint = centerRect;

        // The element to orbit around the center point parented to this gameobject
        var elementGO = new GameObject("Element");
        elementGO.transform.SetParent(transform, false);

        // Setup the element and modify anchors to the center of the container so that both the center and element are in sync
        var elementRect = elementGO.AddComponent<RectTransform>();
        elementRect.anchorMin = new Vector2(0.5f, 0.5f);
        elementRect.anchorMax = new Vector2(0.5f, 0.5f);
        elementRect.pivot = new Vector2(0.5f, 0.5f);
        uiElementRect = elementRect;

        // Add a simple image to visualize the element
        elementGO.AddComponent<Image>(); // Can be removed and changed to anything you want
    }

    private void Update()
    {
        // The current angle based on the speed
        angle += speed * Time.deltaTime;
        // The radian value of the current angle
        float rad = angle * Mathf.Deg2Rad;
        // The x position is the sin of the angle times the radius
        float xpos = centerPoint.position.x + radius * Mathf.Sin(rad);
        // The y position is the cos of the angle times the radius
        float ypos = centerPoint.position.y + radius * Mathf.Cos(rad);

        // Set the calculated position to the actual ui element
        uiElementRect.position = new Vector2(xpos, ypos);
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;

public class OrbitElementListUI : MonoBehaviour
{
    public bool generateUI = true;

    // The radius of the circular orbit
    public float radius = 200;
    // The speed of the rotation around orbit
    public float speed = 2f;
    // The rect transform of the center point to orbit around
    public RectTransform centerPoint;
    // The list of rect transforms to orbit around the center
    public List<RectTransform> uiElementList;

    private float angle = 0f;

    private void Start()
    {
        // Check if need to generate the UI
        if (generateUI)
        {
            GenerateUI();
        }

    }

    private void GenerateUI()
    {
        // Make the center rect transform
        var centerGO = new GameObject("Center");
        centerGO.transform.SetParent(transform, false);
        var centerRect = centerGO.AddComponent<RectTransform>();
        centerRect.anchorMin = new Vector2(0.5f, 0.5f);
        centerRect.anchorMax = new Vector2(0.5f, 0.5f);
        centerRect.pivot = new Vector2(0.5f, 0.5f);
        centerPoint = centerRect;


        // Create 10 elements and anchor them to the container center, then add to a list
        for(int i = 0; i <= 10; i++)
        {
            var elementGO = new GameObject("Element");
            elementGO.transform.SetParent(transform, false);
            var elementRect = elementGO.AddComponent<RectTransform>();
            elementRect.anchorMin = new Vector2(0.5f, 0.5f);
            elementRect.anchorMax = new Vector2(0.5f, 0.5f);
            elementRect.pivot = new Vector2(0.5f, 0.5f);

            elementGO.AddComponent<Image>();
            uiElementList.Add(elementRect);
        }

    }

    private void Update()
    {
        // The current angle using the speed
        angle += speed * Time.deltaTime;
        // Divide up the initial angles to spread the elements equally around the center
        float angleInc = 360f / uiElementList.Count;
        for(int i = 0; i < uiElementList.Count;i++)
        {
            // starting angle = i * angleInc
            // add current angle and starting angle and convert to radian
            float rad = (angleInc * i + angle) * Mathf.Deg2Rad;
            // sin of angle times radius added with the center position is x position
            float xpos = centerPoint.position.x + radius * Mathf.Sin(rad);
            // cos of angle times radius added with the center position is y position
            float ypos = centerPoint.position.y + radius * Mathf.Cos(rad);

            // Change the position of the current ui element
            uiElementList[i].position = new Vector2(xpos, ypos);
        }
    }
}

