// Orbit element class to store orbit specific data for each element
[System.Serializable]
public class OrbitElement
{
    // The actual rect transform of the element
    public RectTransform rectTransform;
    // The starting angle or orbital position of the element
    public float startAngle = 0f;
    // THe distance from the center or the radius of orbit
    public float distance = 0f;

    // Constructor to initialize an orbit element
    public OrbitElement(RectTransform r, float a, float d)
    {
        rectTransform = r;
        startAngle = a;
        distance = d;
    }
}

public class OrbitUIElements_System : MonoBehaviour
{
    // Boolean to check if UI should be generated
    public bool generateUI = true;
    // Boolean to check if the starting angles should be randomized
    public bool randomizePeriods = true;
    // Boolean to check if the distances should be randomized
    public bool randomizeDistances = true;

    /// NOTE: Each orbital element will have the same speed only at a fixed distance, look up orbits!

    // The max radius for randomizing
    public float radiusMax = 600;
    // The min radius for randomizing
    public float radiusMin = 50;
    // The angular speed
    public float speed = 150f;
    // The center rect transform for all the elements
    public RectTransform systemCenter;

    // The list of UI elements to orbit
    public List<OrbitElement> orbitElements = new List<OrbitElement>();

    // The current angle for the time based rotation
    public float timeAngle = 0f;

    private void Start()
    {
        // Check if it needs to generate UI
        if (generateUI)
        {
            GenerateUI();
        }

    }

    private void GenerateUI()
    {
        // Create the center rect transform and parent it to this gameobject with the anchors in the center
        // Position also at the center of the container
        var centerGO = new GameObject("Center");
        centerGO.transform.SetParent(transform, false);
        var centerRect = centerGO.AddComponent<RectTransform>();
        centerRect.anchorMin = new Vector2(0.5f, 0.5f);
        centerRect.anchorMax = new Vector2(0.5f, 0.5f);
        centerRect.pivot = new Vector2(0.5f, 0.5f);
        systemCenter = centerRect;


        // The number of elements to generate
        int number = 10;
        for(int i = 0; i < number; i++)
        {
            // Create an element transform and parent it to gameobject
            // Position it at the center of the container with anchors also at the center
            var elementGO = new GameObject("Element");
            elementGO.transform.SetParent(transform, false);
            var elementRect = elementGO.AddComponent<RectTransform>();
            elementRect.anchorMin = new Vector2(0.5f, 0.5f);
            elementRect.anchorMax = new Vector2(0.5f, 0.5f);
            elementRect.pivot = new Vector2(0.5f, 0.5f);
            elementGO.AddComponent<Image>();

            // Starting angle
            float a = 0f;
            // The distance to orbit
            float d = 0f;
            // If randomize periods is true, then randomize the starting angle
            if(randomizePeriods)
            {
                a = Random.Range(0f, 360f);
            }
            else // Place each element equidistant angularly
            {
                a = i * (360f / number);
            }

            if(randomizeDistances) // Randomize the distance from center for each element
            {
                d = Random.Range(radiusMin, radiusMax);
            }
            else // Or place them equidistant from each other by dividing up the space between min distance and max distance
            {
                d = radiusMin + i *  (radiusMax - radiusMin) / number;
            }

            // Create the orbit element
            OrbitElement oe = new OrbitElement(elementRect, a, d);
            // Add the element to a list
            orbitElements.Add(oe);
        }

    }

    private void Update()
    {
        // The current time based angle
        timeAngle += speed * Time.deltaTime;
        float angleInc = 360f / orbitElements.Count;
        foreach(OrbitElement oe in orbitElements)
        {
            // The starting angle + timeAngle to radians
            float rad = (oe.startAngle + timeAngle) * Mathf.Deg2Rad;
            // Center + radius * sin of angle
            float xpos = systemCenter.position.x + oe.distance * Mathf.Sin(rad);
            // Center + radius * cos of angle
            float ypos = systemCenter.position.y + oe.distance * Mathf.Cos(rad);

            //Apply the calculated positions
            oe.rectTransform.position = new Vector2(xpos, ypos);
        }
    }
}

