// The button that flees from the mouse
public class FleeingButton : Button
{
    // The bounds inside which the button may teleport
    public Rect bounds;

    protected override void Start()
    {
        // Get the parent rect by default if no bounds is assigned
        if(bounds == null)
        {
            bounds = transform.parent.GetComponent<RectTransform>().rect;
        }
    }

    // On Mouse pointer enter the rect
    public override void OnPointerEnter(PointerEventData eventData)
    {
        // Create a random position inside the bound rect
        var randomPos = Vector2.zero;
        randomPos.x += Random.Range(-1f, 1f) * (bounds.xMax - bounds.xMin) / 2.0f;
        randomPos.y += Random.Range(-1f, 1f) * (bounds.yMin - bounds.yMax) / 2.0f;

        GetComponent<RectTransform>().anchoredPosition = randomPos;
    }

}

