public class ExpandingPanelLeft : MonoBehaviour
{
    // Boolean to control the generation of the image panel
    public bool generateImage = true;
    // Check if the animation should be done on script
    public bool animateInScript = true;
    // Check if the animation should be started on gameobject creation
    public bool animateOnStart = true;

    // The rect transform of the parent
    private RectTransform parentRect;
    // The rect transform of the panel
    private RectTransform panelRect;

    // The boolean for tweening state
    [SerializeField]
    private bool tween = false;
    // The speed at which the tween happens
    public float tweenSpeed = 0.01f;

    // The scale of the width that is animatable
    [SerializeField]
    [Range(0f, 1f)]
    public float widthControl = 0f;


    private void Start()
    {
        // Get the parent rect transform
        parentRect = GetComponent<RectTransform>();
        // Check if it has to generate the image for the panel
        if(generateImage)
        {
            GenerateImage();
        }

        // Check if the animation should play on start
        if(animateOnStart)
        {
            tween = true;
        }
    }

    // Method to generate the image for the panel
    private void GenerateImage()
    {
        // Make a new gameobject that expands the container and add an image to it
        var panelGO = new GameObject("Panel");
        panelGO.transform.SetParent(transform, false);
        panelGO.AddComponent<Image>();
        panelRect = panelGO.GetComponent<RectTransform>();
        panelRect.anchorMin = new Vector2(0, 0);
        panelRect.anchorMax = new Vector2(0, 1);
        panelRect.pivot = new Vector2(0f, 0.5f);
        panelRect.sizeDelta = new Vector2(widthControl * parentRect.rect.width, 0);
    }

    
    private void Update()
    {
        // Check if the script should animate within the script or width control is animated elsewhere
        if (!animateInScript) return;
        if(tween)
        {
