using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using TMPro;
using System.Text;
using System;

public class AnimatedText : MonoBehaviour
{
    // Boolean to control if the text should be generated
    public bool generateUI = true;
    // Boolean to control if the text should play on start
    public bool playOnStart = true;
    // Boolean to control if the text is playing
    public bool playing = false;
    // Float to control the playing speed 
    public float playSpeed = 0.1f;
    // The text component
    [SerializeField]
    private TextMeshProUGUI _textComponent; 
    [SerializeField]
    // The string to display as the text
    [TextArea]
    public string textString = "Example text string(Can use richtext formatting)";
    // The progress of the text
    [Range(0f, 1f)]
    public float progress = 0f;
    // Boolean to control if the cursor should be shown
    public bool showCursor = true;
    // Boolean to control if a virtual cursor should be blinking
    public bool blinkCursor = true;

    // String builder to efficiently modify the string
    private StringBuilder sb = new StringBuilder();


    private void Start()
    {
        // Check if UI should be generated 
        if(generateUI)
        {
            GenerateUI();
        }
        // Check if the animation should play
        if(playOnStart)
        {
            playing = true;
        }
    }


    // Method to generate the UI
    private void GenerateUI()
    {
        // Create a gameobject to hold the text
        var textGO = new GameObject("Text");
        textGO.transform.SetParent(transform, false);
        var textRect = textGO.AddComponent<RectTransform>();
        _textComponent = textGO.AddComponent<TextMeshProUGUI>();
        _textComponent.text = textString;
        _textComponent.verticalAlignment = VerticalAlignmentOptions.Middle;


        // Set the text to expand the whole container
        textRect.anchorMin = new Vector2(0, 0);
        textRect.anchorMax = new Vector2(1, 1);
        textRect.pivot = new Vector2(0.5f, 0.5f);
        textRect.anchoredPosition = new Vector2(0, 0);
        textRect.sizeDelta = new Vector2(0, 0);

    }
    
    public void Update()
    {
        // Check if animation is playing
        if(playing)
        {
            //Update the progress
            progress += playSpeed * Time.deltaTime;

            // If progress has reached one, finish
            if(progress >= 1f)
            {
                progress = 1f;
                playing = false;
            }
        }

        // Characters to display and count these
        int charactersToDisplay = Mathf.FloorToInt(progress * textString.Length);
        charactersToDisplay = Mathf.Clamp(charactersToDisplay, 0, textString.Length - 1);
        sb.Clear(); // Clear the previous string
        // Add the new substring
        sb.Append(textString.Substring(0, charactersToDisplay));

        // Add the cursor when not blinking
        if(showCursor && !blinkCursor)
        {
            sb.Append("|");
        }
        // OR if blinking then add the cursor on even characters
        else if(showCursor && blinkCursor && charactersToDisplay % 2 == 0)
        {
            sb.Append("|");
        }

        // Set the text from the string builder
        _textComponent.SetText(sb.ToString().ToCharArray());
    }
}

