        var btn = buttonGO.AddComponent<Button>();

        // Add background image for button
        var buttonImage = buttonGO.AddComponent<Image>();
        btn.targetGraphic = buttonImage;

        // Add text to the button, auto size text and center
        var textGO = new GameObject(buttonName + "Text");
        textGO.transform.SetParent(buttonGO.transform, false);
        var buttonText = textGO.AddComponent<TextMeshProUGUI>();
        buttonText.text = buttonName;
        buttonText.enableAutoSizing = true;
        buttonText.verticalAlignment = VerticalAlignmentOptions.Middle;
        buttonText.horizontalAlignment = HorizontalAlignmentOptions.Center;

        // Text color to black
        buttonText.color = Color.black;

        // Return the button component
        return btn;
    }

    // On button press listener, toggles the movement state
    private void ToggleMoving()
    {
        moving = !moving;
    }


    private void Update()
    {
        if (moving)
        {
            // Reverse directions on reaching the start and end points
            if(t >= 1f || t <= 0f)
            {
                dir = !dir;
            }

            // if direction is positive move left to right
            if(dir)
            {
                t += moveSpeed * Time.deltaTime;
            }
            /// if direction is negative move right to left
            else
            {
                t -= moveSpeed * Time.deltaTime;
            }
            // Clamp the linear interpolation value between 0 and 1
            t = Mathf.Clamp01(t);

            // Get the new interpolated position from the start and end points
            var newPos = Vector2.Lerp(startPointTransform.position, endPointTransform.position, t);
            // Set the tranform position for the button
            movingButtonTransform.position = newPos;
        }
    }

}

