using System;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;
using TMPro;

/// <summary>
/// The enum for slider relations
/// </summary>
public enum SLIDER_RELATION {
    SAME,
    OPPOSITE,
    FUNCTION
}
/// <summary>
/// A script that creates two connected sliders where their values change based on a relation function
/// </summary>
public class ConnectedSliders : MonoBehaviour
{
    // The check for generation of UI
    public bool generateUI = true;

    // The first slider
    public Slider sliderA;
    // The second slider
    public Slider sliderB;

    // The type of the relation of the slider
    public SLIDER_RELATION relation;
    // The slider relation function
    public Func<float, float> sliderFunction;
    private void Start()
    {
        // Check if need to generate UI
        if(generateUI)
        {
            GenerateUI();
        }
    }

    private void GenerateUI()
    {
        var layoutGroup = gameObject.AddComponent<VerticalLayoutGroup>();
        layoutGroup.spacing = 20f;
        layoutGroup.childControlHeight = false;

        var sliderAGO = new GameObject("ZoomSliderContainer");
        sliderAGO.transform.SetParent(transform);
        sliderAGO.AddComponent<RectTransform>();

        sliderA = CreateSlider(sliderAGO.transform);
        var sliderBGO = new GameObject("ZoomSliderContainer");
        sliderBGO.transform.SetParent(transform);
        sliderBGO.AddComponent<RectTransform>();
        sliderB = CreateSlider(sliderBGO.transform);

        sliderA.onValueChanged.AddListener((val) => { RecalculateSliders(sliderA); });
        sliderB.onValueChanged.AddListener((val) => { RecalculateSliders(sliderB); });

    }

    /// <summary>
    /// This method creates a slider
    /// </summary>
    /// <param name="parent">The parent transform for the slider</param>
    /// <returns></returns>
    private Slider CreateSlider(Transform parent)
    {
        // The background image for the slider
        var backgroundImageGO = new GameObject("Background");
        backgroundImageGO.transform.SetParent(parent, false);
        var bgRect = backgroundImageGO.AddComponent<RectTransform>();
        // Expand the container
        bgRect.anchorMin = new Vector2(0, 0);
        bgRect.anchorMax = new Vector2(1, 1);
        bgRect.sizeDelta = new Vector2(0, 0);
        bgRect.anchoredPosition = new Vector2(0, 0);
        var bgImage = backgroundImageGO.AddComponent<Image>();
        bgImage.color = Color.grey;


        // The fill area for the slider
        var fillAreaGO = new GameObject("FillArea");
        fillAreaGO.transform.SetParent(parent, false);
        var fillAreaRect = fillAreaGO.AddComponent<RectTransform>();
        // Expands the container
        fillAreaRect.anchorMin = new Vector2(0, 0);
        fillAreaRect.anchorMax = new Vector2(1, 1);
        fillAreaRect.sizeDelta = new Vector2(0, 0);
        fillAreaRect.anchoredPosition = new Vector2(0, 0);

        // The fill rect of the slider
        var fillGO = new GameObject("Fill");
        fillGO.transform.SetParent(fillAreaGO.transform, false);
        var fillRect = fillGO.AddComponent<RectTransform>();
        // Fills from left
        fillRect.anchorMin = new Vector2(0, 0);
        fillRect.anchorMax = new Vector2(0, 1);
        fillRect.sizeDelta = new Vector2(0, 0);
        fillRect.anchoredPosition = new Vector2(0, 0);

        // The fill image and it is green in color
        var fillImage = fillGO.AddComponent<Image>();
        fillImage.color = Color.green;
        
        // The handle area to slide the handle
        var handleAreaGO = new GameObject("HandleArea");
        handleAreaGO.transform.SetParent(parent, false);
        var handleAreaRect = handleAreaGO.AddComponent<RectTransform>();

        // Expands the whole container
        handleAreaRect.anchorMin = new Vector2(0, 0);
        handleAreaRect.anchorMax = new Vector2(1, 1);
        handleAreaRect.sizeDelta = new Vector2(0, 0);
        handleAreaRect.anchoredPosition = new Vector2(0, 0);
        
        // The handle gameobject
        var handleGO = new GameObject("Handle");
        handleGO.transform.SetParent(handleAreaGO.transform, false);
        var handleRect = handleGO.AddComponent<RectTransform>();
        // The rect is anchored to the left side
        handleRect.anchorMin = new Vector2(0, 0);
        handleRect.anchorMax = new Vector2(0, 1);
        handleRect.sizeDelta = new Vector2(20, 10); // Width and height
        handleRect.anchoredPosition = new Vector2(0, 0);

        // Add the image to the handle
        var handleImage = handleGO.AddComponent<Image>();
        handleImage.color = Color.white;



        // Add the slider component
        var slider = parent.gameObject.AddComponent<Slider>();
        // Assign the filling rect
        slider.fillRect = fillRect;
        // Assign the handle rect
        slider.handleRect = handleRect;

        return slider;
    }



    /// <summary>
    /// This method recalculates the value of the slider
    /// This also acts as a value change listener
    /// </summary>
    /// <param name="slider">The slider in question </param>
    private void RecalculateSliders(Slider slider)
    {
        // Set the other slider according the their relation
        switch(relation)
        {
            case SLIDER_RELATION.SAME:
                UpdateSliderValue(slider, sliderA, (val) => { return val; });
                UpdateSliderValue(slider, sliderB, (val) => { return val; });
                break;
            case SLIDER_RELATION.OPPOSITE:
                UpdateSliderValue(slider, sliderA, (val) => { return 1.0f - val; });
                UpdateSliderValue(slider, sliderB, (val) => { return 1.0f - val; });
                break;

            case SLIDER_RELATION.FUNCTION:
                UpdateSliderValue(slider, sliderA, sliderFunction);
                UpdateSliderValue(slider, sliderB, sliderFunction);
                break;
        }
    }

    /// <summary>
    /// Method to update the slider values
    /// </summary>
    /// <param name="src">The source slider, the value that changed</param>
    /// <param name="dst">The slider that needs to be updated</param>
    /// <param name="srcToDst"> The function to update these sliders</param>
    private void UpdateSliderValue(Slider src, Slider dst, Func<float, float> srcToDst)
    {
        // If the same slider is both source and destination then return
        if (src == dst) return;
        // Check if the relation is provided
        if (srcToDst == null)
        {
            Debug.LogError("Relation function not provided!");
            return;
        }

        dst.value = srcToDst(src.value);
    }
  
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;


// This requires a canvas renderer as it is a maskable graphic class, that draws stuff in the UI
[RequireComponent(typeof(CanvasRenderer))]
public class FilledCircleDrawer : MaskableGraphic
{
    //The radius of the circle
    public float radius = 200f;
    // The x offset for the center of the circle from the origin
    public float offsetx = 0f;
    // The y offset for the center of the circle from the origin
    public float offsety = 0f;
    // The segments or triangles in a circle
    public int segments = 16;

    
    protected override void OnPopulateMesh(VertexHelper vh)
    {
        // Clear the previous data in the helper
        vh.Clear();
        // Add the circle mesh to circle
        AddCircle(radius, ref vh);
    }

    // Method to create the circle with a given radius
    private void AddCircle(float radius, ref VertexHelper vh)
    {
        // Require at least 4 segments (Diamond)
        if(segments < 4)
        {
            Debug.LogError("Not enough segments!");
            return;
        }

        // The position of the center
        // cx is the x position
        // cy is the y position
        float cx = offsetx;
        float cy = offsety;

        // A simple vertex to contain a UI vertex, provided by Unity
        UIVertex vertex = UIVertex.simpleVert;

        // Set the color of the vertex, this will draw this vertex in that color, with the default UI shader
        vertex.color = color;

        // The position of the center vertex
        vertex.position = new Vector3(cx, cy);
        // Add a new vertex which is the center to the helper
        vh.AddVert(vertex);

        // this represents the vertices added before the segments are added, the center vertex id
        int cid = vh.currentVertCount - 1;

        // The angular increment for each segment
        float inc = 360f / segments;
        for (int i = segments - 1; i >= 0; i--)
        {
            // Find the angle in radians
            float angle = i * inc * Mathf.Deg2Rad;
            // Find the x position along the arc
            float px = cx + radius * Mathf.Cos(angle);
            // Find the y position along the arc
            float py = cy + radius * Mathf.Sin(angle);
            // Edit the position of the UI vertex
            vertex.position = new Vector3(px, py);
            // Add this new vertex to the helper
            vh.AddVert(vertex);
        }

        // For each 2 segment vertices, add triangles from center, and two segment vertices at a time
        for (int i = cid; i + 2 < vh.currentVertCount; i++)
        {
            vh.AddTriangle(cid, i + 1, i + 2);
        }
        // Finally add the last triangle 
        vh.AddTriangle(cid, vh.currentVertCount - 1, cid + 1);
    }

}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;

// This executes in edit mode to view the line during edits
[ExecuteInEditMode]
// Requires a canvas renderer because it inherits the Graphic component
[RequireComponent(typeof(CanvasRenderer))]
public class UILineMaker : Graphic
{
    // The starting position of the line segment
    public Vector2 start;
    // The ending position of the line segment
    public Vector2 end;
    // The pixel width of the line segment
    public float width = 2f;
    protected override void OnPopulateMesh(VertexHelper vh)
    {
        // Clear the previous vertex data
        vh.Clear();
        // UI vertex placeholder 
        UIVertex vert = UIVertex.simpleVert;

        // The direction of the line
        Vector2 dir = (end - start).normalized;
        // The perpendicular direction to the line
        Vector2 perp = new Vector2(-dir.y, dir.x);

        // Set the first vertex to the starting position of the line
        vert.position = new Vector3(start.x, start.y);
        // Offset the first vertex towards the opposite perpendicular with half the width
        vert.position -= new Vector3(perp.x, perp.y) * width / 2f;
        // set the color of the vertex
        vert.color = Color.white;
        // Add the vertex
        vh.AddVert(vert);

        // Set the first vertex to the starting position of the line
        vert.position = new Vector3(start.x, start.y);
        // Offset the first vertex towards the perpendicular with half the width
        vert.position += new Vector3(perp.x, perp.y) * width / 2f;
        // set the color of the vertex
        vert.color = Color.white;
        // Add the vertex
        vh.AddVert(vert);

        // Set the first vertex to the ending position of the line
        vert.position = new Vector3(end.x, end.y);
        // Offset the end vertex towards the perpendicular with half the width
        vert.position += new Vector3(perp.x, perp.y) * width / 2f;
        // set the color of the vertex
        vert.color = Color.white;
        // Add the vertex
        vh.AddVert(vert);

        // Set the first vertex to the ending position of the line
        vert.position = new Vector3(end.x, end.y);
        // Offset the first vertex towards the opposite perpendicular with half the width
        vert.position -= new Vector3(perp.x, perp.y) * width / 2f;
        // set the color of the vertex
        vert.color = Color.white;
        // Add the vertex
        vh.AddVert(vert);


        // Add the first triangle
        vh.AddTriangle(0, 1, 2);
        // Add the second triangle
        vh.AddTriangle(2, 3, 0);
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;

// This executes in edit mode
[ExecuteInEditMode]
public enum BORDER_TYPE
{
    INSIDE, OUTSIDE, OUTLINE
}
// This executes in edit mode to see the changes
[ExecuteInEditMode]
// Requires a canvas renderer to draw the graphics as it inherits the Graphic class
[RequireComponent(typeof(CanvasRenderer))]
public class UIRectBorder : Graphic
{
    // The type of the border
    public BORDER_TYPE borderType;
    // The width of the border
    public float borderWidth = 2f;

    
    protected override void OnPopulateMesh(VertexHelper vh)
    {
        // The first corner of the rect
        Vector2 corner1 = Vector2.zero;
        // The second corner of the rect
        Vector2 corner2 = Vector2.zero;

        // The bottom left
        corner1.x = 0f;
        corner1.y = 0f;
        // The top right
        corner2.x = 1f;
        corner2.y = 1f;

        // offset to the pivots of the rect transform
        corner1.x -= rectTransform.pivot.x;
        corner1.y -= rectTransform.pivot.y;
        corner2.x -= rectTransform.pivot.x;
        corner2.y -= rectTransform.pivot.y;

        // Scale according to the rect transform
        corner1.x *= rectTransform.rect.width;
        corner1.y *= rectTransform.rect.height;
        corner2.x *= rectTransform.rect.width;
        corner2.y *= rectTransform.rect.height;

        // Require a center of the rect
        Vector2 center = new Vector2(0.5f, 0.5f);
        center.x -= rectTransform.pivot.x;
        center.y -= rectTransform.pivot.y;

        // Scale to the rect tranform
        center.x *= rectTransform.rect.width;
        center.y *= rectTransform.rect.height;

        // The 4 vertices of the rect
        Vector2 a = new Vector2(corner1.x, corner1.y);
        Vector2 b = new Vector2(corner1.x, corner2.y);
        Vector2 c = new Vector2(corner2.x, corner2.y);
        Vector2 d = new Vector2(corner2.x, corner1.y);


        // The direction vectors from the center of the rect
        Vector2 da = (a - center).normalized;
        Vector2 db = (b - center).normalized;
        Vector2 dc = (c - center).normalized;
        Vector2 dd = (d - center).normalized;


        // The external points initialized to the 4 points
        Vector2 ea = a;
        Vector2 eb = b;
        Vector2 ec = c;
        Vector2 ed = d;

        // The internal points initialized to the 4 points
        Vector2 ia = a;
        Vector2 ib = b;
        Vector2 ic = c;
        Vector2 id = d;



        // Check the border types
        switch(borderType)
        {
            // If border type is inside
            case BORDER_TYPE.INSIDE:
                // Then the external points are the rect points
                ea = a;
                eb = b;
                ec = c;
                ed = d;

                // The internal points are shifted towards the center
                ia = a - da * borderWidth;
                ib = b - db * borderWidth;
                ic = c - dc * borderWidth;
                id = d - dd * borderWidth;
                break;
            // If the border type is outside
            case BORDER_TYPE.OUTSIDE:
                // The external points are shifted opposite from the center
                ea = a + da * borderWidth;
                eb = b + db * borderWidth;
                ec = c + dc * borderWidth;
                ed = d + dd * borderWidth;

                // The internal points are the rect points 
                ia = a;
                ib = b;
                ic = c;
                id = d;

                break;

            // If the border type is outline
            case BORDER_TYPE.OUTLINE:
                // External points are shifted width/2 times in the opposite direction from the center
                ea = a + da * borderWidth / 2f;
                eb = b + db * borderWidth / 2f;
                ec = c + dc * borderWidth / 2f;
                ed = d + dd * borderWidth / 2f;
                // Internal points are shifted width/2 times in the direction of the center
                ia = a - da * borderWidth / 2f;
                ib = b - db * borderWidth / 2f;
                ic = c - dc * borderWidth / 2f;
                id = d - dd * borderWidth / 2f;
                break;
        }

        // Clear the previous data
        vh.Clear();

        // Helping vertex
        UIVertex vert = UIVertex.simpleVert;


        //External points 0, 1, 2, 3
        vert.position = ea; // 0
        vert.color = color;
        vh.AddVert(vert);

        vert.position = eb; // 1
        vert.color = color;
        vh.AddVert(vert);

        vert.position = ec; // 2
        vert.color = color;
        vh.AddVert(vert);

        vert.position = ed; // 3
        vert.color = color;
        vh.AddVert(vert);

        //Internal points
        vert.position = ia; // 4
        vert.color = color;
        vh.AddVert(vert);

        vert.position = ib; // 5
        vert.color = color;
        vh.AddVert(vert);

        vert.position = ic; // 6
        vert.color = color;
        vh.AddVert(vert);

        vert.position = id; // 7
        vert.color = color;
        vh.AddVert(vert);

        //LEFT
        vh.AddTriangle(0, 1, 5);
        vh.AddTriangle(5, 4, 0);
        //BOTTOM
        vh.AddTriangle(0, 4, 7);
        vh.AddTriangle(7, 3, 0);

        //TOP
        vh.AddTriangle(1, 6, 5);
        vh.AddTriangle(1, 2, 6);

        //RIGHT
        vh.AddTriangle(2, 3, 6);
        vh.AddTriangle(6, 3, 7);

    }


}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;

// Requires a canvas renderer to display the graphics
[RequireComponent(typeof(CanvasRenderer))]
public class UIArrow : Graphic
{
    // The percentage length of the tail of the arrow
    [Range(0f,1f)]
    public float tailLength = 0.8f;
    // The width of the tail in pixels
    public float tailWidth = 1f;
    protected override void OnPopulateMesh(VertexHelper vh)
    {
        // Clear previous data
        vh.Clear();

        // The left end of the tail
        Vector2 tailLeft = Vector2.zero;
        Vector2 tailRight = Vector2.zero;

        // The right end of the tail and left end of the arrow
        Vector2 arrowLeft = Vector2.zero;
        Vector2 arrowRight = Vector2.zero;

        // The left end is positioned horizontally to the left 
        tailLeft.x = 0f;
        // The left end is positioned vertically to the center
        tailLeft.y = 0.5f;

        // The right end is positioned horizontally to the right
        tailRight.x = tailLength;
        // The right end is positioned vertically to the center
        tailRight.y = 0.5f;

        // Same as tail right, that's where the arrow starts
        arrowLeft.x = tailLength;
        arrowLeft.y = 0.5f;

        // Finished at the very right
        arrowRight.x = 1f;
        arrowRight.y = 0.5f;

        // Reposition all points according to the pivots

        arrowLeft.x -= rectTransform.pivot.x;
        arrowLeft.y -= rectTransform.pivot.y;
        arrowRight.x -= rectTransform.pivot.x;
        arrowRight.y -= rectTransform.pivot.y;

        tailLeft.x -= rectTransform.pivot.x;
        tailLeft.y -= rectTransform.pivot.y;
        tailRight.x -= rectTransform.pivot.x;
        tailRight.y -= rectTransform.pivot.y;


        // Scale all points according to the width  and height of container
        tailLeft.x *= rectTransform.rect.width;
        tailLeft.y *= rectTransform.rect.height;
        tailRight.x *= rectTransform.rect.width;
        tailRight.y *= rectTransform.rect.height;
        arrowLeft.x *= rectTransform.rect.width;
        arrowLeft.y *= rectTransform.rect.height;
        arrowRight.x *= rectTransform.rect.width;
        arrowRight.y *= rectTransform.rect.height;


        // The vertex helper
        UIVertex vert = UIVertex.simpleVert;
        // Set the color for all the vertices
        vert.color = color;

        // Tail left bottom left
        vert.position = new Vector3(tailLeft.x, tailLeft.y - tailWidth / 2f);
        vh.AddVert(vert);

        // Tail left top left
        vert.position = new Vector3(tailLeft.x, tailLeft.y + tailWidth / 2f);
        vh.AddVert(vert);

        // Tail right top right
        vert.position = new Vector3(tailRight.x, tailRight.y + tailWidth / 2f);
        vh.AddVert(vert);

        // Tail right bottom right
        vert.position = new Vector3(tailRight.x, tailRight.y - tailWidth / 2f);
        vh.AddVert(vert);

        // Arrow left bottom 
        vert.position = new Vector3(arrowLeft.x, arrowLeft.y - rectTransform.rect.height / 2f);
        vh.AddVert(vert);

        // Arrow left top
        vert.position = new Vector3(arrowLeft.x, arrowLeft.y + rectTransform.rect.height / 2f);
        vh.AddVert(vert);

        // Arrow right center
        vert.position = new Vector3(arrowRight.x, arrowRight.y);
        vh.AddVert(vert);


        // add the triangles
        vh.AddTriangle(0, 1, 2);
        vh.AddTriangle(2, 3, 0);
        vh.AddTriangle(4, 5, 6);
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;


// Requires the canvas renderer to draw things to screen as it inherits the graphics class
[RequireComponent(typeof(CanvasRenderer))]
public class UIGrid : Graphic
{
    // The width of the grid
    public int width = 4;
    // The height of the grid
    public int height = 4;
    // The cellwidth of the grid cells
    public float cellWidth = 32;
    // The cell height of the grid cells
    public float cellHeight = 32;

    // The line width of the cells
    public float lineWidth = 2f;

    protected override void OnPopulateMesh(VertexHelper vh)
    {
        // Clear previous data
        vh.Clear();
        // The center positions for the cells
        List<Vector2> cellCenters = new List<Vector2>(width * height);

        // The cell tranformed to the rect proportions
        float cellw = rectTransform.rect.width / width;
        float cellh = rectTransform.rect.height / height;
        // For each cell along the height
        for(int i = 0; i < height; i++)
        {
            // For each cell along the row
            for(int j = 0; j < width; j++)
            {
                // Make a point
                Vector2 point = Vector2.zero;
                // Set the cell positions
                point.x -= -cellw / 2f + rectTransform.pivot.x * rectTransform.rect.width;
                point.y -= -cellh / 2f + rectTransform.pivot.y * rectTransform.rect.height;
                point.x += cellw * j;
                point.y += cellh * i;

                // Add the cell center
                cellCenters.Add(point);
            }
        }

        // For each cell center position
        foreach(var p in cellCenters)
        {
            // Draw the boundary of the cell
            DrawCell(ref vh, p, cellw, cellh);
        }

    }

    // This method is for visualization and is not used
    // It can visualize any point by drawing a red rectangle on that place
    private void DrawSquare(ref VertexHelper vh, Vector2 p)
    {
        UIVertex vert = UIVertex.simpleVert;
        float squareSide = 5f;
        vert.color = Color.red;
        int startIdx = vh.currentVertCount;

        vert.position = new Vector3(p.x - squareSide, p.y - squareSide, 0f);
        vh.AddVert(vert);

        vert.position = new Vector3(p.x - squareSide, p.y + squareSide, 0f);
        vh.AddVert(vert);

        vert.position = new Vector3(p.x + squareSide, p.y + squareSide, 0f);
        vh.AddVert(vert);

        vert.position = new Vector3(p.x + squareSide, p.y - squareSide, 0f);
        vh.AddVert(vert);

        vh.AddTriangle(startIdx, startIdx + 1, startIdx + 2);
        vh.AddTriangle(startIdx + 2, startIdx + 3, startIdx);
    }

    /// <summary>
    /// This method draws the boundary of the cell according to the center point
    /// </summary>
    /// <param name="vh"> The vertex helper reference </param>
    /// <param name="p"> The center point </param>
    /// <param name="cellw">The width of the cell </param>
    /// <param name="cellh">The height of the cell</param>
    private void DrawCell(ref VertexHelper vh, Vector2 p, float cellw, float cellh)
    {
        // Vertex to edit
        UIVertex vert = UIVertex.simpleVert;
        // The starting index in the vertex buffer
        int startIdx = vh.currentVertCount;
        // The center of the cells
        float cx = cellw / 2f;
        float cy = cellh / 2f;

        // The bottom left
        vert.position = new Vector3(p.x - cx, p.y - cy, 0f);
        vh.AddVert(vert);
        // The top left
        vert.position = new Vector3(p.x - cx, p.y + cy, 0f);
        vh.AddVert(vert);
        // The top right
        vert.position = new Vector3(p.x + cx, p.y + cy, 0f);
        vh.AddVert(vert);
        // The bottom right
        vert.position = new Vector3(p.x + cx, p.y - cy, 0f);
        vh.AddVert(vert);

        // Reduce the center offset by the line width / 4
        cx -= lineWidth / 4f;
        cy -= lineWidth / 4f;

        // Inside top left
        vert.position = new Vector3(p.x - cx, p.y - cy, 0f);
        vh.AddVert(vert);
        // Inside bottom left
        vert.position = new Vector3(p.x - cx, p.y + cy, 0f);
        vh.AddVert(vert);
        // Inside top right
        vert.position = new Vector3(p.x + cx, p.y + cy, 0f);
        vh.AddVert(vert);
        // Inside bottom right
        vert.position = new Vector3(p.x + cx, p.y - cy, 0f);
        vh.AddVert(vert);


        //LEFT Border
        vh.AddTriangle(startIdx, startIdx + 1, startIdx + 4);
        vh.AddTriangle(startIdx + 1, startIdx + 5, startIdx + 4);

        //BOTTOM Border
        vh.AddTriangle(startIdx, startIdx + 4,startIdx + 7);
        vh.AddTriangle(startIdx + 7, startIdx + 3, startIdx);

        //TOP Border
        vh.AddTriangle(startIdx + 1, startIdx + 6, startIdx + 5);
        vh.AddTriangle(startIdx + 1, startIdx + 2, startIdx + 6);

        //RIGHT Border
        vh.AddTriangle(startIdx + 2, startIdx + 3, startIdx + 6);
        vh.AddTriangle(startIdx + 6, startIdx + 3, startIdx + 7);

    }

}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;

public class UiCameraViewer : MonoBehaviour
{
    // Boolean to control if the UI is generated
    public bool generateUI = true;

    // The viewport image
    public Image viewportImage;
    // The main camera
    private Camera mainCamera;

    // The render texture
    private RenderTexture _renderTexture;
    private void Start()
    {
        // Get the main camera
        mainCamera = Camera.main;

       
        // Abort if no camera is found
        if(mainCamera == null)
        {
            this.enabled = false;
            return;
        }



        // Create the render texture
        _renderTexture = new RenderTexture((int)mainCamera.pixelRect.width, (int) mainCamera.pixelRect.height, 16);
        _renderTexture.autoGenerateMips = true;

        // If generate UI is checked then create a surface that expands the container
        if(generateUI)
        {
            var imageGo = new GameObject();
            imageGo.transform.SetParent(transform);
            var imageRect = imageGo.AddComponent<RectTransform>();
            imageRect.anchorMin = new Vector2(0, 0);
            imageRect.anchorMax = new Vector2(1, 1);
            imageRect.sizeDelta = new Vector2(0, 0);
            imageRect.pivot = new Vector2(0.5f, 0.5f);
            imageRect.anchoredPosition = new Vector2(0f, 0f);

            // Add the image to this surface and set the render texture to this material
            viewportImage = imageGo.AddComponent<Image>();
            var shader = Shader.Find("Unlit/Texture");
            viewportImage.material = new Material(shader);
            viewportImage.material.SetTexture("_MainTex", _renderTexture);
        }
        else
        {
            // Edit the shader for the viewport image
            var shader = Shader.Find("Unlit/Texture");
            viewportImage.material = new Material(shader);
            // Assign the render texture to this material
            viewportImage.material.SetTexture("_MainTex", _renderTexture);
        }
    }

    private void LateUpdate()
    {
        // Update the camera after every frame
        UpdateCamera();
    }


    private void UpdateCamera()
    {
        //Get a current frame from the camera by manually capturing it
        mainCamera.targetTexture = _renderTexture;
        // Manually render the camera
        mainCamera.Render();
        // Reassign the camera to screen
        mainCamera.targetTexture = null;
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using TMPro;

public class ObjectSelectorWithLabel : MonoBehaviour
{
    // Boolean to check if UI needs to be generated
    public bool generateUI = true;
    // The selectable layers that you can select with mouse, needs to be set
    /// MUST SET THIS PROPERTY IN THE INSPECTOR
    public LayerMask selectableLayerMask;
    // The main camera
    private Camera mainCamera;

    // The label text
    public TextMeshProUGUI labelText;

    private void Start()
    {
        // Get the camera
        mainCamera = Camera.main;
        
        // Check if the UI needs to be generated
        if(generateUI)
        {
            // If so, generate the UI
            GenerateUI();
        }
        // Check if the label is null, if null, then abort
        else if(labelText == null)
        {
            Debug.LogError("Select a suitable text component to update first!");
            this.enabled = false;
            return;
        }

    }

    private void Update()
    {
        // Get the mouse button
        if(Input.GetMouseButtonDown(0))
        {
            // Call the method to select the object
            RaycastSelectObject(Input.mousePosition);
        }

    }

    // Method to generate the UI
    private void GenerateUI()
    {
        var labelTextGO = new GameObject("Label Text");
        labelTextGO.transform.SetParent(transform);
        var labelRect = labelTextGO.AddComponent<RectTransform>();
        labelRect.anchorMin = new Vector2(0, 0);
        labelRect.anchorMax = new Vector2(1, 1);
        labelRect.pivot = new Vector2(0.5f, 0.5f);
        labelRect.sizeDelta = new Vector2(0, 0);
        labelRect.anchoredPosition = new Vector2(0, 0);

        labelText= labelTextGO.AddComponent<TextMeshProUGUI>();
        labelText.text = "None";
        labelText.enableAutoSizing = true;
        labelText.color = Color.black;
        labelText.verticalAlignment = VerticalAlignmentOptions.Middle;
        labelText.horizontalAlignment = HorizontalAlignmentOptions.Left;

    }
    /// <summary>
    /// Selects the object by casting a ray from the screen position
    /// </summary>
    /// <param name="screenPos"> The screen point to cast the ray from</param>
    private void RaycastSelectObject(Vector2 screenPos)
    {
        // Get the ray from the main camera
        var ray = mainCamera.ScreenPointToRay(screenPos);
        // Check if the ray hits anything, by using a raycast
        if(Physics.Raycast(ray, out RaycastHit hit, 1000f, selectableLayerMask))
        {
            // If the hit is not null
            if(hit.collider != null)
            {
                // Update the UI with this method
                UpdateUI("Selected Object: " + hit.collider.gameObject.name);
            }
        }
        else
        {
            // Update UI that nothing is selected
            UpdateUI("No object selected!");
        }

    }

    /// <summary>
    /// Method to update the UI
    /// </summary>
    /// <param name="label"> Text for the label </param>
    private void UpdateUI(string label)
    {
        labelText.text = label;
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;

/// <summary>
/// This class creates an UI element that can be dragged with the mouse, and it snaps to the mouse whenever it is clicked
/// </summary>
public class UIDraggable : MonoBehaviour
{
    // Boolean to signal if the current object is being dragged
    private bool dragging = false;

    // Boolean to check if UI needs to generated
    public bool generateUI = true;

    private void Start()
    {
        // If generate UI is true then generate the UI
        if(generateUI)
        {
            gameObject.AddComponent<Image>();
        }
    }

    private void Update()
    {
        // If not dragging and mouse is pressed then drag the component
        if(!dragging && Input.GetMouseButtonDown(0))
        {
            dragging = true;
        }
        // If dragging and mouse is released then stop dragging
        else if(dragging && Input.GetMouseButtonUp(0))
        {
            dragging = false;
        }


        // If dragging the element
        if(dragging)
        {
            // Get the mouse position
            var mousePos = Input.mousePosition;

            // Get the rect transform and change the position to the mouseposition
            gameObject.GetComponent<RectTransform>().position = mousePos;
        }
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;
using TMPro;

/// <summary>
/// An object selector with a scale slider, you can select anything by clicking on the screen and it will allow you to scale it
/// </summary>
public class ObjectSelectorWithScaleSlider : MonoBehaviour
{
    // Boolean to check if needs to generate UI
    public bool generateUI = true;
    // The selectable gameobject layer, NEEDS TO BE SET IN INSPECTOR
    public LayerMask selectableLayerMask;
    // The main camera
    private Camera mainCamera;

    // The label text for the object
    public TextMeshProUGUI labelText;
    // The slider for the scale
    public Slider scaleSlider;

    // Boolean for if the item is selected
    private bool selected = false;
    // The maximum scale of the object
    public float maxScale = 10f;
    // The minimum scale of the object
    public float minScale = 0.1f;

    private void Start()
    {
        // get the main camera
        mainCamera = Camera.main;

        // If generateUI is true then generate the UI
        if (generateUI)
        {
            GenerateUI();
        }
        // IF there is no label text then abort
        else if (labelText == null)
        {
            Debug.LogError("Select a suitable text component to update first!");
            this.enabled = false;
            return;
        }

    }


    // Method to generate the UI
    private void GenerateUI()
    {
        // The layout for the container
        var layout = gameObject.AddComponent<VerticalLayoutGroup>();

        // The label text that expands the component
        var labelTextGO = new GameObject("ObjectSelector");
        labelTextGO.transform.SetParent(transform);
        var labelRect = labelTextGO.AddComponent<RectTransform>();
        labelRect.anchorMin = new Vector2(0, 0);
        labelRect.anchorMax = new Vector2(1, 1);
        labelRect.pivot = new Vector2(0.5f, 0.5f);
        labelRect.sizeDelta = new Vector2(0, 0);
        labelRect.anchoredPosition = new Vector2(0, 0);

        //Add the text component to the label text
        labelText = labelTextGO.AddComponent<TextMeshProUGUI>();
        labelText.text = "None";
        labelText.enableAutoSizing = true;
        // Set the color to black
        labelText.color = Color.black;
        labelText.verticalAlignment = VerticalAlignmentOptions.Middle;
        labelText.horizontalAlignment = HorizontalAlignmentOptions.Left;

        // The scale slider gameobject
        var scaleSliderGO = new GameObject("ScaleSlider");
        scaleSliderGO.transform.SetParent(transform);
        var scaleSliderRect = scaleSliderGO.AddComponent<RectTransform>();
        // Expand the container
        scaleSliderRect.anchorMin = new Vector2(0, 0);
        scaleSliderRect.anchorMax = new Vector2(1, 1);
        scaleSliderRect.pivot = new Vector2(0.5f, 0.5f);
        scaleSliderRect.sizeDelta = new Vector2(0, 0);
        scaleSliderRect.anchoredPosition = new Vector2(0, 0);


        // Create the slider
        scaleSlider = CreateSlider(scaleSliderGO.transform);
    }

    private Slider CreateSlider(Transform parent)
    {
        // The background image for the slider
        var backgroundImageGO = new GameObject("Background");
        backgroundImageGO.transform.SetParent(parent, false);
        var bgRect = backgroundImageGO.AddComponent<RectTransform>();
        // Expand the container
        bgRect.anchorMin = new Vector2(0, 0);
        bgRect.anchorMax = new Vector2(1, 1);
        bgRect.sizeDelta = new Vector2(0, 0);
        bgRect.anchoredPosition = new Vector2(0, 0);
        var bgImage = backgroundImageGO.AddComponent<Image>();
        bgImage.color = Color.grey;


        // The fill area for the slider
        var fillAreaGO = new GameObject("FillArea");
        fillAreaGO.transform.SetParent(parent, false);
        var fillAreaRect = fillAreaGO.AddComponent<RectTransform>();
        // Expands the container
        fillAreaRect.anchorMin = new Vector2(0, 0);
        fillAreaRect.anchorMax = new Vector2(1, 1);
        fillAreaRect.sizeDelta = new Vector2(0, 0);
        fillAreaRect.anchoredPosition = new Vector2(0, 0);

        // The fill rect of the slider
        var fillGO = new GameObject("Fill");
        fillGO.transform.SetParent(fillAreaGO.transform, false);
        var fillRect = fillGO.AddComponent<RectTransform>();
        // Fills from left
        fillRect.anchorMin = new Vector2(0, 0);
        fillRect.anchorMax = new Vector2(0, 1);
        fillRect.sizeDelta = new Vector2(0, 0);
        fillRect.anchoredPosition = new Vector2(0, 0);

        // The fill image and it is green in color
        var fillImage = fillGO.AddComponent<Image>();
        fillImage.color = Color.green;
        
        // The handle area to slide the handle
        var handleAreaGO = new GameObject("HandleArea");
        handleAreaGO.transform.SetParent(parent, false);
        var handleAreaRect = handleAreaGO.AddComponent<RectTransform>();

        // Expands the whole container
        handleAreaRect.anchorMin = new Vector2(0, 0);
        handleAreaRect.anchorMax = new Vector2(1, 1);
        handleAreaRect.sizeDelta = new Vector2(0, 0);
        handleAreaRect.anchoredPosition = new Vector2(0, 0);
        
        // The handle gameobject
        var handleGO = new GameObject("Handle");
        handleGO.transform.SetParent(handleAreaGO.transform, false);
        var handleRect = handleGO.AddComponent<RectTransform>();
        // The rect is anchored to the left side
        handleRect.anchorMin = new Vector2(0, 0);
        handleRect.anchorMax = new Vector2(0, 1);
        handleRect.sizeDelta = new Vector2(20, 10); // Width and height
        handleRect.anchoredPosition = new Vector2(0, 0);

        // Add the image to the handle
        var handleImage = handleGO.AddComponent<Image>();
        handleImage.color = Color.white;



        // Add the slider component
        var slider = parent.gameObject.AddComponent<Slider>();
        // Assign the filling rect
        slider.fillRect = fillRect;
        // Assign the handle rect
        slider.handleRect = handleRect;

        return slider;
    }

    private void Update()
    {
        // If the mouse is pressed
        if (Input.GetMouseButtonDown(0))
        {
            // Select the object according to mouse position
            RaycastSelectObject(Input.mousePosition);
        }
        // If any object is selected right click unselects the object
        else if(selected && Input.GetMouseButtonDown(1))
        {
            selected = false;
        }
        // If nothing is selected update the UI
        else if(!selected)
        {
            UpdateUI(null, "Nothing selected!");
        }

    }

    /// <summary>
    /// Selects an object by raycasting from a screen point
    /// </summary>
    /// <param name="screenPos"> The screen point to select from</param>
    private void RaycastSelectObject(Vector2 screenPos)
    {
        // Get the ray from the camera
        var ray = mainCamera.ScreenPointToRay(screenPos);
        // Check if ray has hit anything
        if (Physics.Raycast(ray, out RaycastHit hit, 1000f, selectableLayerMask))
        {
            if (hit.collider != null)
            {
                // If ray has hit and there is a collider select and update the UI
                selected = true;
                UpdateUI(hit.collider.gameObject, "Selected Object: " + hit.collider.gameObject.name);
            }
        }

    }
    /// <summary>
    /// This method updates the UI
    /// </summary>
    /// <param name="selectedObject"> The object to select </param>
    /// <param name="label"> The label for the UI </param>
    private void UpdateUI(GameObject selectedObject,string label)
    {
        // Reset the scale slider
        scaleSlider.onValueChanged.RemoveAllListeners();
        // Set the label text
        labelText.text = label;
        // Check if nothing is selected
        if(selectedObject == null)
        {
            // Then set the slider not interactable and return
            scaleSlider.interactable = false;
            return;
        }
        else
        {
            // Set the slider interactable
            scaleSlider.interactable = true;

            // Set the max value
            scaleSlider.maxValue = maxScale;
            // Set the min value
            scaleSlider.minValue = minScale;

            // Add a functor listener that scales the currently selected gameobject
            scaleSlider.onValueChanged.AddListener((value) =>
            {
                float s = Mathf.Exp(value);
                selectedObject.gameObject.transform.localScale = new Vector3(s, s, s);
            });
        }
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;

public class BarVisualizer : MonoBehaviour
{
    // The color of the bars
    public Color barColor;

    // The list of all the bars
    private List<RectTransform> _allBars = new List<RectTransform>();

    // The audio source for visualization
    public AudioSource audioSource;

    // The samples array
    private float[] _samples = new float[512];
    // The bar values array
    private float[] _barValues = new float[8];

    // The height multiplier for the bars
    public float heightMultiplier = 100f;
    private void Start()
    {
        // Generate the UI
        GenerateUI();
    }

    /// <summary>
    /// This method generates the UI
    /// </summary>
    private void GenerateUI()
    {
        // Set a horizontal layout component for the bars
        var layout = gameObject.AddComponent<HorizontalLayoutGroup>();
        layout.spacing = 20f;
        // Anchor the bars to the bottom center
        layout.childAlignment = TextAnchor.LowerCenter;
        // Free the height of the bars from the container
        layout.childControlHeight = false;


        // Add 8 bars
        for(int i = 0; i < 8; i++)
        {
            _allBars.Add(MakeBar());
        }
    }

    /// <summary>
    /// This method makes a bar for visualization and returns
    /// </summary>
    /// <returns>The rect transform of the bar</returns>
    private RectTransform MakeBar()
    {
        // Creates a gameobject for the bar
        var barGO = new GameObject("Bar" + _allBars.Count + 1);
        barGO.transform.SetParent(transform);
        var barRect = barGO.AddComponent<RectTransform>();
        // adds the image for the bar
        barGO.AddComponent<Image>().color = barColor;

        return barRect;
    }

    private void Update()
    {
        // If the audio source is playing then update the bar values and then the visuals
        if(audioSource.isPlaying)
        {
            UpdateBarValues();
            UpdateBarVisuals();
        }
    }

    /// <summary>
    /// This method updates the value of the bars
    /// It uses a Fast Fourier Transform of the audio track and samples it in 512 bins
    /// </summary>
    private void UpdateBarValues()
    {
        // This function generates the spectrum data
        audioSource.GetSpectrumData(_samples, 0, FFTWindow.Hamming);

        // The count of the samples used in each iteration
        int count = 0;
        for (int i = 0; i < 8; i++)
        {
            // The average of the sample values
            float average = 0f;
            // How many samples to take during each iteration
            int sampleCount = (int)Mathf.Pow(2, i + 1);
            // If the last bar is reached, then take the 2 more samples
            if (i == 7)
            {
                sampleCount += 2;
            }

            // Calculate the sum of the samples
            for (int j = 0; j < sampleCount; j++)
            {
                average += _samples[count] * (count + 1);
                count++;
            }

            // Average the samples by dividing with the current count, count is total samples gotten so far
            average /= count;

            // Assign this average
            _barValues[i] = average;
        }
    }

    /// <summary>
    /// This method updates the bar visuals
    /// </summary>
    private void UpdateBarVisuals()
    {
        // Scale the height of all the bars according to the bar values and height multiplier
        for(int i = 0; i < 8;i++)
        {
            _allBars[i].sizeDelta = new Vector2(_allBars[i].sizeDelta.x, _barValues[i] * heightMultiplier);

        }
    }
}

using System.Collections;
