/// <summary>
/// This class provides a way to spawn UI elements at runtime
/// Using the mouse clicks on the screen
/// </summary>
public class UIElementSpawnOnClick : MonoBehaviour
{
    // The ui element prefab to spawn on clicking, can be set in the inspector
    public GameObject elementPrefab;


    private void Start()
    {
        // IF the element prefab is null, create a placeholder
        if(elementPrefab == null)
        {
            // This is the placeholder gameobject to instantiate
            elementPrefab = new GameObject("Element Prefab");
            elementPrefab.transform.SetParent(transform);
            var rect = elementPrefab.AddComponent<RectTransform>();
            // Center the anchors to container center
            rect.anchorMin = new Vector2(0.5f, 0.5f);
            rect.anchorMax = new Vector2(0.5f, 0.5f);
            rect.pivot = new Vector2(0.5f, 0.5f);
            // Give it a decent size
            rect.sizeDelta = new Vector2(100, 100);
            // add an image for visualization
            elementPrefab.AddComponent<Image>();
            // Set inactive, because it will only be used for instantiation
            elementPrefab.SetActive(false);
        }
    }

