using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;

/// <summary>
/// This class allows to visualize and audio source using
/// the scale of an UI element
/// </summary>
public class UIElementScaleAudioVisualizer : MonoBehaviour
{
    // The audio source to visualize, NEED TO SET IT IN THE INSPECTOR
    public AudioSource audioSource;

    // The sample bins
    private float[] _samples = new float[512];
    // The average value
    private float avg = 0f;

    // The multiplier for the scale
    public float scaleMultiplier = 100f;

    // The rect tranform of the target UI element
    public RectTransform _rectTransform;

    private void Start()
    {
        // Get the rect transform
        _rectTransform = GetComponent<RectTransform>();

        // Check if the audio source is not there
        if(audioSource == null)
        {
            Debug.LogError("Please provide audio source!");
            this.enabled = false;
            return;
        }
    }



    private void Update()
    {
        // If the audio source is playing then update the values then the visuals
        if(audioSource.isPlaying)
        {
            UpdateAudioValues();
            UpdateScaleVisuals();
        }
    }

    /// <summary>
    /// This method gets the audio values and averages them.
    /// It uses a fast fourier transform of the audio data to get the samples
    /// </summary>
    private void UpdateAudioValues()
    {
        // This function populates the sample bins
        audioSource.GetSpectrumData(_samples, 0, FFTWindow.Hamming);


        // Calculate the sum of the sample values
        avg = 0f;
        for(int i = 0; i < _samples.Length; i++)
        {
            avg += _samples[i];
        }

        // Get the average by dividing by all the samples
        avg /= _samples.Length;
    }

    /// <summary>
    /// This method updates the UI element scale
    /// </summary>
    private void UpdateScaleVisuals()
    {
        // Set the scale of the UI element with the average value and the multiplier
        _rectTransform.localScale = new Vector3(avg, avg, avg) * scaleMultiplier;
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;

/// <summary>
/// This class allows to use to mouse to control the rotation of an UI element
/// </summary>
// This requires an UI element, therefore a rect transform with the game object
[RequireComponent(typeof(RectTransform))]
public class UIElementRotator : MonoBehaviour
{
    // Boolean to check if UI needs to generated
    public bool generateUI = true;

    // Boolean to check if it is rotating
    private bool rotating = false;
    // The rect transform of element
    private RectTransform _rect;

    // The last position of the mouse
    private Vector3 lastPos;
    // The rotation speed
    public float rotationSpeed = 10f;
    private void Start()
    {
        // If generateUI is checked then add an image to visualize the element
        if(generateUI)
        {
            gameObject.AddComponent<Image>();
        }

        // Get the rect transform
        _rect = GetComponent<RectTransform>();
    }

    private void Update()
    {
        // If the mouse left is pressed then set the last mouse position and start rotation
        if(Input.GetMouseButtonDown(0))
        {
            lastPos = Input.mousePosition;
            rotating = true;
        }
        // IF the mouse is released then stop rotation
        else if(Input.GetMouseButtonUp(0))
        {
            rotating = false;
        }

        // If rotating
        if(rotating)
        {
            // Get the mouse delta value
            var delta = (Input.mousePosition - lastPos);
            // Get the target rotation according to the mouse delta
            var targetRot = Quaternion.AngleAxis(delta.x, Vector3.forward);
            // Set the rotation with the rotation speed
            _rect.rotation = Quaternion.RotateTowards(_rect.rotation, targetRot, rotationSpeed);
        }
    }
}

using System;
