using UnityEngine.Audio;

/// <summary>
/// This script allows you to have a slider that can control the'
/// volume of any audio mixer that you give it
/// </summary>
public class UIVolumeControl : MonoBehaviour
{
    // Check if UI needs to generated
    public bool generateUI = true;
    // The slider for the volume
    public Slider volumeSlider;

    /// <summary>
    /// This must be set in the inspector
    /// </summary>
    public AudioMixer audioMixer;
    /// <summary>
    /// This property name must be exposed in the selected mixer as the master volume
    /// </summary>
    public string volumePropertyName;


    
    private void Start()
    {
        // Set the init volume
        float initialVolume = 0f;
        // If the audio mixer is not there abort
        if(audioMixer == null)
        {
            Debug.LogError("Please provide audio mixer group!");
            this.enabled = false;
            return;
        }
        else
        {
            // If the property is not found then abort
            if(!audioMixer.GetFloat(volumePropertyName, out initialVolume))
            {
                Debug.LogError("Invalid mixer property name, please check if the property is exposed and the name is correct");
                this.enabled = false;
                return;
            }
            
        }

        // If generate ui is checked then generate the UI for the slider
        if(generateUI)
        {
            // Create a container for the slider
            var sliderAGO = new GameObject("VolumeSlider");
            sliderAGO.transform.SetParent(transform);
            var sliderRect = sliderAGO.AddComponent<RectTransform>();
            // Expand the slider to fill the parent
            sliderRect.anchorMin = new Vector2(0, 0);
            sliderRect.anchorMax = new Vector2(1, 1);
            sliderRect.sizeDelta = new Vector2(0, 0);
            sliderRect.anchoredPosition = new Vector2(0, 0);

            // Create the slider and set the min max values
            volumeSlider = CreateSlider(sliderAGO.transform);
            volumeSlider.minValue = -80;
            volumeSlider.maxValue = 12;
            // Set the initial volume for the slider
            volumeSlider.value = initialVolume;
            // add the listener function
            volumeSlider.onValueChanged.AddListener(ChangeVolume);
        }

    }

    /// <summary>
    /// The listener function for the slider
    /// </summary>
    /// <param name="val">The value to set the volume</param>
    private void ChangeVolume(float val)
    {
        // Set the floating point parameter in the audio mixer
        audioMixer.SetFloat(volumePropertyName, val);
    }

    /// <summary>
    /// This method creates a slider with the given parent
    /// </summary>
    /// <param name="parent"> The parent for the slider</param>
    /// <returns></returns>
    private Slider CreateSlider(Transform parent)
    {
        // The slider background image
        var backgroundImageGO = new GameObject("Background");
        backgroundImageGO.transform.SetParent(parent, false);
        var bgRect = backgroundImageGO.AddComponent<RectTransform>();
        // Expands to fill the whole container
        bgRect.anchorMin = new Vector2(0, 0);
        bgRect.anchorMax = new Vector2(1, 1);
        bgRect.sizeDelta = new Vector2(0, 0);
        bgRect.anchoredPosition = new Vector2(0, 0);
        // The background image component with a gray color
        var bgImage = backgroundImageGO.AddComponent<Image>();
        bgImage.color = Color.grey;


        // The fill area for the background
        var fillAreaGO = new GameObject("FillArea");
        fillAreaGO.transform.SetParent(parent, false);
        var fillAreaRect = fillAreaGO.AddComponent<RectTransform>();
        // Expands to fill the container
        fillAreaRect.anchorMin = new Vector2(0, 0);
        fillAreaRect.anchorMax = new Vector2(1, 1);
        fillAreaRect.sizeDelta = new Vector2(0, 0);
        fillAreaRect.anchoredPosition = new Vector2(0, 0);


        // The fill gameobject
        var fillGO = new GameObject("Fill");
        fillGO.transform.SetParent(fillAreaGO.transform, false);
        var fillRect = fillGO.AddComponent<RectTransform>();
        // Expands from left
        fillRect.anchorMin = new Vector2(0, 0);
        fillRect.anchorMax = new Vector2(0, 1);
        fillRect.sizeDelta = new Vector2(0, 0);
        fillRect.anchoredPosition = new Vector2(0, 0);

        // the fill image and color set to green
        var fillImage = fillGO.AddComponent<Image>();
        fillImage.color = Color.green;
        
        // The area the handle slides on
        var handleAreaGO = new GameObject("HandleArea");
        handleAreaGO.transform.SetParent(parent, false);
        var handleAreaRect = handleAreaGO.AddComponent<RectTransform>();
        // Expands from the left of the container
        handleAreaRect.anchorMin = new Vector2(0, 0);
        handleAreaRect.anchorMax = new Vector2(1, 1);
        handleAreaRect.sizeDelta = new Vector2(0, 0);
        handleAreaRect.anchoredPosition = new Vector2(0, 0);

        // The handle to slide
        var handleGO = new GameObject("Handle");
        handleGO.transform.SetParent(handleAreaGO.transform, false);
        var handleRect = handleGO.AddComponent<RectTransform>();
        // Anchored to the left
        handleRect.anchorMin = new Vector2(0, 0);
        handleRect.anchorMax = new Vector2(0, 1);
        handleRect.sizeDelta = new Vector2(20, 10);
        handleRect.anchoredPosition = new Vector2(0, 0);

        // The handle image and color
        var handleImage = handleGO.AddComponent<Image>();
        handleImage.color = Color.white;



        // The slider component
        var slider = parent.gameObject.AddComponent<Slider>();
        // Fill rect for the slider
        slider.fillRect = fillRect;
        // The handle for the slider
        slider.handleRect = handleRect;

        return slider;
    }



}

