using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using TMPro;
using UnityEngine.UI;
using UnityEngine.EventSystems;

/// <summary>
/// This script creates a play mode position editor for gameobjects
/// </summary>
public class UITransformEditor : MonoBehaviour
{
    // Check if ui needs to generated
    public bool generateUI = true;
    // The selectable object layers, NEEDS TO BE SET IN THE INSPECTOR
    public LayerMask selectableLayerMask;
    // The main camera
    private Camera mainCamera;

    // The label text
    public TextMeshProUGUI labelText;

    // The position x field
    public TMP_InputField posXField;
    // The position y field
    public TMP_InputField posYField;
    // The position z field
    public TMP_InputField posZField;
    // The apply button
    public Button applyButton;

    // The selected object
    private GameObject selectedObject;

    private void Start()
    {
        // get the main camera
        mainCamera = Camera.main;

        // Check if ui needs generating
        if (generateUI)
        {
            GenerateUI();
        }
        // Chekc if the label text is there, if not, abort
        else if (labelText == null)
        {
            Debug.LogError("Select a suitable text component to update first!");
            this.enabled = false;
            return;
        }

        // Check if any of the fields are not there, if not abort
        if (posXField == null || posYField == null || posZField == null || applyButton == null)
        {
            Debug.LogError("No input fields given!");
            return;
        }

        // Set all the fields not interactable
        posXField.interactable = false;
        posYField.interactable = false;
        posZField.interactable = false;
        applyButton.interactable = false;

    }

    private void Update()
    {
        // Get the mouse down and check if it over an UI element, if not then try to select an object
        if(Input.GetMouseButtonDown(0) && !IsPointerOverUIObject())
        {
            // Select an object with a raycast from mouse position
            RaycastSelectObject(Input.mousePosition);
        }
        // On a right click deselect everything and Update the UI
        else if(Input.GetMouseButtonDown(1))
        {
            selectedObject = null;
            UpdateUI("Nothing selected!");
        }

    }

    /// <summary>
    /// This method generates the UI
    /// </summary>
    private void GenerateUI()
    {
        var parentLayout = gameObject.AddComponent<VerticalLayoutGroup>();

        gameObject.AddComponent<CanvasGroup>().blocksRaycasts = true;

        var labelTextGO = new GameObject("Label Text");
        labelTextGO.transform.SetParent(transform);
        var labelRect = labelTextGO.AddComponent<RectTransform>();
        labelRect.anchorMin = new Vector2(0, 0);
        labelRect.anchorMax = new Vector2(1, 1);
        labelRect.pivot = new Vector2(0.5f, 0.5f);
        labelRect.sizeDelta = new Vector2(0, 0);
        labelRect.anchoredPosition = new Vector2(0, 0);

        labelText= labelTextGO.AddComponent<TextMeshProUGUI>();
        labelText.text = "None";
        labelText.enableAutoSizing = true;
        labelText.color = Color.black;
        labelText.verticalAlignment = VerticalAlignmentOptions.Middle;
        labelText.horizontalAlignment = HorizontalAlignmentOptions.Left;

        var optionsGO = new GameObject("Options");
        optionsGO.transform.SetParent(transform);
        optionsGO.AddComponent<RectTransform>();
        var optionsLayout = optionsGO.AddComponent<HorizontalLayoutGroup>();

        posXField = CreateField("X", optionsGO.transform, TMP_InputField.ContentType.DecimalNumber);
        posYField = CreateField("Y", optionsGO.transform, TMP_InputField.ContentType.DecimalNumber);
        posZField = CreateField("Z", optionsGO.transform, TMP_InputField.ContentType.DecimalNumber);

        applyButton = CreateButton("Apply Button");
        // Add the listener
        applyButton.onClick.AddListener(UpdateSelectedTransform);
    }

    /// <summary>
    /// This methods creates a field that is editable
    /// </summary>
    /// <param name="name">The name of the field</param>
    /// <param name="parent">The parent transform for the field</param>
    /// <param name="type">The content type of the field</param>
    /// <returns></returns>
    private TMP_InputField CreateField(string name, Transform parent, TMP_InputField.ContentType type)
    {
        // Create the field gameobjecr
        var fieldGO = new GameObject(name);
        fieldGO.transform.SetParent(parent);
        fieldGO.AddComponent<RectTransform>();
        fieldGO.AddComponent<Image>();

        // The Text area for the field
        var textAreaGO = new GameObject(name);
        textAreaGO.transform.SetParent(fieldGO.transform);
        var textRect = textAreaGO.AddComponent<RectTransform>();
        // Expands to the whole container
        textRect.anchorMin = new Vector2(0, 0);
        textRect.anchorMax = new Vector2(1, 1);
        textRect.anchoredPosition = new Vector2(0, 0);
        textRect.sizeDelta = new Vector2(0, 0);

        // The input field component
        var inputField = fieldGO.AddComponent<TMP_InputField>();
        // Creat the field text
        var fieldText = CreateText(name+"Text", fieldGO.transform, "");
        // Create the text placholder
        var fieldPlaceholder = CreateText(name+"Text Placeholder", fieldGO.transform, name);
        // Set the field text and placeholder
        inputField.textComponent = fieldText;
        inputField.placeholder = fieldPlaceholder;
        // Set the content type
        inputField.contentType = type;
        inputField.textViewport = fieldGO.GetComponent<RectTransform>();
        // Set a custom caret color
        inputField.customCaretColor = true;
        inputField.caretColor = Color.black;
        return inputField;
    }

    /// <summary>
    /// This method creates text elements
    /// </summary>
    /// <param name="name">The name of the gameobjects</param>
    /// <param name="parent"> The parent transform</param>
    /// <param name="defaultText">The default text in the text element</param>
    /// <returns></returns>
    private TextMeshProUGUI CreateText(string name, Transform parent, string defaultText)
    {
        // Create the text gameobject
        var textGO = new GameObject(name);
        textGO.transform.SetParent(parent);
        var textRect = textGO.AddComponent<RectTransform>();
        // Expands to the whole container
        textRect.anchorMin = new Vector2(0, 0);
        textRect.anchorMax = new Vector2(1, 1);
        textRect.anchoredPosition = new Vector2(0, 0);
        textRect.sizeDelta = new Vector2(0, 0);

        // Add the text component
        var textComp = textGO.AddComponent<TextMeshProUGUI>();
        // Set the default text
        textComp.text = defaultText;
        // Auto sizing
        textComp.enableAutoSizing = true;
        // The text color
        textComp.color = Color.black;
        // The vertical alignment
        textComp.verticalAlignment = VerticalAlignmentOptions.Middle;
        // The horizontal alignement
        textComp.horizontalAlignment = HorizontalAlignmentOptions.Center;
        return textComp;
    }

    /// <summary>
    /// This method creates a button with a given name
    /// </summary>
    /// <param name="buttonName">The name of the button</param>
    /// <returns></returns>
    private Button CreateButton(string buttonName)
    {
        // Create the button gameobject
        var buttonGO = new GameObject(buttonName);
        buttonGO.transform.SetParent(transform, false);
        buttonGO.AddComponent<RectTransform>();
        var btn = buttonGO.AddComponent<Button>();

        // Create the image for the button
        var buttonImage = buttonGO.AddComponent<Image>();
        // Set this image as the target for the button
        btn.targetGraphic = buttonImage;


        // Create the text for the button
        var textGO = new GameObject(buttonName + "Text");
        textGO.transform.SetParent(buttonGO.transform, false);
        var buttonText = textGO.AddComponent<TextMeshProUGUI>();
        // Set the text of the button to the name of the button
        buttonText.text = buttonName;
        buttonText.enableAutoSizing = true;
        buttonText.verticalAlignment = VerticalAlignmentOptions.Middle;
        buttonText.horizontalAlignment = HorizontalAlignmentOptions.Center;
        // Set the button text color
        buttonText.color = Color.black;

        return btn;
    }


    /// <summary>
    /// This method selects an object from the screen using a raycast from the camera
    /// </summary>
    /// <param name="screenPos"> The screen position to raycast from</param>
    private void RaycastSelectObject(Vector2 screenPos)
    {
        // Get the ray using the camera
        var ray = mainCamera.ScreenPointToRay(screenPos);
        // Check if ray hit something
        if(Physics.Raycast(ray, out RaycastHit hit, 1000f, selectableLayerMask))
        {
            if(hit.collider != null)
            {
                // If ray hits a selectable object and it has collider then select it
                selectedObject = hit.collider.gameObject;
                // Update the UI
                UpdateUI("Selected Object: " + hit.collider.gameObject.name);
            }
        }

    }

    /// <summary>
    /// This method updates the UI
    /// </summary>
    /// <param name="label">The text for the label</param>
    private void UpdateUI(string label)
    {
        labelText.text = label;

        // If object is selected then mark all the fields as interactable
        // Get the current values for the fields, using the selected object
        if(selectedObject != null)
        {
            var pos = selectedObject.transform.position;
            posXField.text = pos.x.ToString();
            posYField.text = pos.y.ToString();
            posZField.text = pos.z.ToString();
            posXField.interactable = true;
            posYField.interactable = true;
            posZField.interactable = true;

            applyButton.interactable = true;
        }
        // Otherwise, mark all the fields and buttons not interactable and
        // Set the values to empty for all the fields
        else
        {
            posXField.text = "";
            posYField.text = "";
            posZField.text = "";

            posXField.interactable = false;
            posYField.interactable = false;
            posZField.interactable = false;

            applyButton.interactable = false;
        }
    }

    /// <summary>
    /// Method to update the tranform of the selected component, this is used as the button listener
    /// </summary>
    private void UpdateSelectedTransform()
    {
        // If no selected object then return
        if (selectedObject == null) return;
        // Set the position of the selected object according to the field values
        var pos = new Vector3(float.Parse(posXField.text), float.Parse(posYField.text), float.Parse(posZField.text));
        selectedObject.transform.position = pos;
    }

    /// <summary>
    /// This method checks if the pointer is on an UI element or not
    /// </summary>
    /// <returns> If the pointer is over an UI element</returns>
    private bool IsPointerOverUIObject()
    {
        PointerEventData eventDataCurrentPosition = new PointerEventData(EventSystem.current);
        eventDataCurrentPosition.position = new Vector2(Input.mousePosition.x, Input.mousePosition.y);

        List<RaycastResult> results = new List<RaycastResult>();
        EventSystem.current.RaycastAll(eventDataCurrentPosition, results);
        return results.Count > 0;
    }
}

using System;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;
using TMPro;

/// <summary>
/// This script creates UI elements that track the number of clicks and the average clicks per second
/// </summary>
public class MouseClickTracker : MonoBehaviour
{
    // Check if you need to generate UI
    public bool generateUI = true;

    // The total clicks text
    public TextMeshProUGUI totalClicks;
    // The average clicks per second text
    public TextMeshProUGUI averageClicksPerSecond;

    // The count of clicks
    private int clicks = 0;
    // The current time
    private float time = 0f;
    // If the tracking is started
    private bool started = false;
    // Time of the last update
    private float lastUpdate = 0f;

    private void Start()
    {
        // If this is checked then generate the UI
        if(generateUI)
        {
            GenerateUI();
        }
    }

    private void Update()
    {
        // On the first mouse press start the tracking
        if(Input.GetMouseButtonDown(0))
        {
            if(!started)
                started = true;
            
        }

        // If it is started measure speed
        if(started)
        {
            time += Time.deltaTime;

            // If the mouse is clicked then count
            if(Input.GetMouseButtonDown(0))
            {
                clicks += 1;
                totalClicks.text = clicks.ToString();

            }

            // if the interval since the last update is enough
            if(time > 0.1f && time - lastUpdate > 1f)
            {
                lastUpdate = time;
                // Calculate the average since the start
                float averageClicks = clicks / time;
                // Update the average text
                averageClicksPerSecond.text = averageClicks.ToString();
            }
        }
    }

    /// <summary>
    /// This method generates the UI
    /// </summary>
    private void GenerateUI()
    {
        // The layout is a vertical layout group with 2 text elements
        var layout = gameObject.AddComponent<VerticalLayoutGroup>();
        // The text for mouse clicks
        totalClicks = CreateText("Mouse Clicks", gameObject.transform, "0");
        // The text for average clicks
        averageClicksPerSecond = CreateText("Average Clicks", gameObject.transform, "0");
    }


    /// <summary>
