using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;


/// <summary>
/// This script creates a spinner as a crosshair that spins faster the
/// longer the mouse is held
/// </summary>
public class MouseHoldSpinnerCrosshair : MonoBehaviour
{
    // Check to generate crosshair
    public bool generateCrosshair = true;

    // The rect transform of the crosshair
    public RectTransform crosshair;

    // The acceleration of the angular speed
    public float acceleration = 10f;
    // The braking force
    public float decelaration = 10f;
    // The maximum angular velocity
    public float maxSpinSpeed = 30f;
    // The current speed
    private float currentSpinSpeed = 0f;
    // The current angle
    private float currentAngle = 0f;

    private void Start()
    {
        // If checked then create the crosshair
        if(generateCrosshair)
        {
            // Set the parent to expand the whole screen
            var rectTransform = GetComponent<RectTransform>();
            rectTransform.anchorMin = new Vector2(0, 0);
            rectTransform.anchorMax = new Vector2(1, 1);
            rectTransform.sizeDelta = new Vector2(0, 0);
            rectTransform.anchoredPosition = new Vector2(0, 0);

            // Create the cross hair
            var crosshairGO = new GameObject("Crosshair");
            crosshairGO.transform.SetParent(transform);
            // Center the cross hair in the middle
            crosshair = crosshairGO.AddComponent<RectTransform>();
            crosshair.anchoredPosition = new Vector2(0, 0);
            crosshairGO.AddComponent<Image>();
        }
    }

    private void Update()
    {
        // Update the current angle
        currentAngle += currentSpinSpeed * Time.deltaTime;

        // Set the current angle
        crosshair.rotation = Quaternion.AngleAxis(currentAngle, -Vector3.forward);

        // If the mouse is pressed increase speed,
        // Otherwise decrease speed
        if (Input.GetMouseButton(0))
        {
            currentSpinSpeed += acceleration * Time.deltaTime;
        }
        else
        {
            currentSpinSpeed -= decelaration * Time.deltaTime;
        }

        // Clamp the speed to 0 to max
        currentSpinSpeed = Mathf.Clamp(currentSpinSpeed, 0f, maxSpinSpeed);

        // Rotations above 360f turn around
        if (currentAngle >= 360f)
        {
            currentAngle -= 360f;
        }
        // Rotations below -360f turn around
        else if(currentAngle <= -360f)
        {
            currentAngle += 360f;
        }

    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;

/// <summary>
/// This script creates a slider that controls the intesity of a light
/// </summary>
public class UILightSlider : MonoBehaviour
{
    // Check if UI needs to generated
    public bool generateUI = true;
    // Check if the light needs to be created
    public bool createLight = true;
    // Start the position
    public Vector3 startPosition = new Vector3(0, 0, 0);
    // The starting rotation of the light
    public Vector3 startRotation = new Vector3(50, -30, 0);

    // The slider to control the intensity
    public Slider intensitySlider;
    // The max intensity
    public float maxIntensity = 2f;
    // The minimum intensity
    public float minIntensity = 0f;

    // The light object
    public Light lightObject;

    private void Start()
    {
        // If checked then creat the slider for the light
        if(generateUI)
        {
            intensitySlider = CreateSlider(transform);
        }

        // If checked then create the light at a designated place
        // With the start rotation
        // And the starting position
        // And set to a directional light
        if(createLight)
        {
            var lightGO = new GameObject("Light");
            lightGO.transform.position = startPosition;
            lightGO.transform.rotation = Quaternion.Euler(startRotation);
            lightObject = lightGO.AddComponent<Light>();
            lightObject.type = LightType.Directional;
        }
        // If no light is provided or not created then abort
        if(lightObject == null)
        {
            Debug.LogError("No light provided!");
            this.enabled = false;
            return;
        }

        // Add the listener to the slider, and setup slider values
        intensitySlider.onValueChanged.AddListener(UpdateLightIntensity);
        intensitySlider.maxValue = maxIntensity;
        intensitySlider.minValue = minIntensity;
        intensitySlider.value = lightObject.intensity;
    }

    /// <summary>
    /// This method creates a slider
    /// </summary>
    /// <param name="parent">The parent transform for the slider</param>
    /// <returns></returns>
    private Slider CreateSlider(Transform parent)
    {
        // The background image for the slider
        var backgroundImageGO = new GameObject("Background");
        backgroundImageGO.transform.SetParent(parent, false);
        var bgRect = backgroundImageGO.AddComponent<RectTransform>();
        // Expand the container
        bgRect.anchorMin = new Vector2(0, 0);
        bgRect.anchorMax = new Vector2(1, 1);
        bgRect.sizeDelta = new Vector2(0, 0);
        bgRect.anchoredPosition = new Vector2(0, 0);
        var bgImage = backgroundImageGO.AddComponent<Image>();
        bgImage.color = Color.grey;


        // The fill area for the slider
        var fillAreaGO = new GameObject("FillArea");
        fillAreaGO.transform.SetParent(parent, false);
        var fillAreaRect = fillAreaGO.AddComponent<RectTransform>();
        // Expands the container
        fillAreaRect.anchorMin = new Vector2(0, 0);
        fillAreaRect.anchorMax = new Vector2(1, 1);
        fillAreaRect.sizeDelta = new Vector2(0, 0);
        fillAreaRect.anchoredPosition = new Vector2(0, 0);

        // The fill rect of the slider
        var fillGO = new GameObject("Fill");
        fillGO.transform.SetParent(fillAreaGO.transform, false);
        var fillRect = fillGO.AddComponent<RectTransform>();
        // Fills from left
        fillRect.anchorMin = new Vector2(0, 0);
        fillRect.anchorMax = new Vector2(0, 1);
        fillRect.sizeDelta = new Vector2(0, 0);
        fillRect.anchoredPosition = new Vector2(0, 0);

        // The fill image and it is green in color
        var fillImage = fillGO.AddComponent<Image>();
        fillImage.color = Color.green;
        
        // The handle area to slide the handle
        var handleAreaGO = new GameObject("HandleArea");
        handleAreaGO.transform.SetParent(parent, false);
        var handleAreaRect = handleAreaGO.AddComponent<RectTransform>();

        // Expands the whole container
        handleAreaRect.anchorMin = new Vector2(0, 0);
        handleAreaRect.anchorMax = new Vector2(1, 1);
        handleAreaRect.sizeDelta = new Vector2(0, 0);
        handleAreaRect.anchoredPosition = new Vector2(0, 0);
        
        // The handle gameobject
        var handleGO = new GameObject("Handle");
        handleGO.transform.SetParent(handleAreaGO.transform, false);
        var handleRect = handleGO.AddComponent<RectTransform>();
        // The rect is anchored to the left side
        handleRect.anchorMin = new Vector2(0, 0);
        handleRect.anchorMax = new Vector2(0, 1);
        handleRect.sizeDelta = new Vector2(20, 10); // Width and height
        handleRect.anchoredPosition = new Vector2(0, 0);

        // Add the image to the handle
        var handleImage = handleGO.AddComponent<Image>();
        handleImage.color = Color.white;



        // Add the slider component
        var slider = parent.gameObject.AddComponent<Slider>();
        // Assign the filling rect
        slider.fillRect = fillRect;
        // Assign the handle rect
        slider.handleRect = handleRect;

        return slider;
    }

    /// <summary>
    /// The listener function for the slider values to change the light intensity
    /// </summary>
    /// <param name="val">The value of the slider</param>
    private void UpdateLightIntensity(float val)
    {
        lightObject.intensity = val;
    }

}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Events;

/// <summary>
/// A box trigger script to count items falling in and out.
/// DOES NOT GENERATE THE BOX!
/// YOU HAVE TO CREATE THE BOX YOURSELF!
/// </summary>
public class BoxTrigger : MonoBehaviour
{
    // The trigger id for the box
    public int triggerID = 0;
    // The layermask for objects to track, NEED TO SET IN INSPECTOR
    public LayerMask objectsLayer;
    // The list of items in the box
    public List<GameObject> items;
    // The action fired when items fall in and out
    public static UnityAction<int, int> OnBoxTriggerItemCountChange = delegate { };

    private void Start()
    {
        // Initialize items list
        items = new List<GameObject>();
    }
    private void OnTriggerEnter(Collider other)
    {
        // Check layermask of the items that enter this trigger
        if( ( (1 << other.gameObject.layer) & objectsLayer) > 0)
        {
            // If the item is not already in the box, add it to the list
            if(!items.Contains(other.gameObject))
            {
                items.Add(other.gameObject);

                // Fire the action
                OnBoxTriggerItemCountChange?.Invoke(triggerID, items.Count);
            }
        }
    }

    
    private void OnTriggerExit(Collider other)
    {
        // If the item is in the list, remove the item
        if(items.Contains(other.gameObject))
        {
            items.Remove(other.gameObject);

            // Fire the action
            OnBoxTriggerItemCountChange?.Invoke(triggerID, items.Count);
        }
    }
}
