using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;
using TMPro;

/// <summary>
/// This scripts allows you pick a color from the whole screen
/// </summary>
public class ScreenColorPicker : MonoBehaviour
{
    // Check if UI needs to be generated
    public bool generateUI = true;

    // The image for representing the selected color
    public Image colorImage;
    // The pick color button for the script
    public Button pickColorButton;

    // The flag to signify if the color is being picked
    public bool pickingColor = false;
    // The picked color
    public Color pickedColor = new Color(1.0f, 1.0f, 1.0f);

    // The color texture, to pick the color, copy of the current frame
    private Texture2D _colorTex;
    // The main camera
    private Camera _mainCamera;

    private void Start()
    {
        // If this is checked then generate the UI
        if(generateUI)
        {
            GenerateUI();
        }
        // Get the main camera
        _mainCamera = Camera.main;
        // If no main camera then abort
        if(_mainCamera == null)
        {
            Debug.LogError("No camera found!");
            this.enabled = false;
            return;
        }

        // Add the listener to the pick color button
        pickColorButton.onClick.AddListener(StartPickColor);

    }

    private void GenerateUI()
    {
        // A horizontal layout for the color image and the button
        var layout = gameObject.AddComponent<HorizontalLayoutGroup>();

        // The image for the color
        var imageGO = new GameObject("Color Image");
        imageGO.transform.SetParent(transform);
        imageGO.AddComponent<RectTransform>();
        colorImage = imageGO.AddComponent<Image>();

        // The button to start picking the color
        pickColorButton = CreateButton("Pick Color");
    }

    /// <summary>
    /// This method creates a button with a given name
    /// </summary>
    /// <param name="buttonName">The name of the button</param>
    /// <returns></returns>
    private Button CreateButton(string buttonName)
    {
        // Create the button gameobject
        var buttonGO = new GameObject(buttonName);
        buttonGO.transform.SetParent(transform, false);
        buttonGO.AddComponent<RectTransform>();
        var btn = buttonGO.AddComponent<Button>();

        // Create the image for the button
        var buttonImage = buttonGO.AddComponent<Image>();
        // Set this image as the target for the button
        btn.targetGraphic = buttonImage;


        // Create the text for the button
        var textGO = new GameObject(buttonName + "Text");
        textGO.transform.SetParent(buttonGO.transform, false);
        var buttonText = textGO.AddComponent<TextMeshProUGUI>();
        // Set the text of the button to the name of the button
        buttonText.text = buttonName;
        buttonText.enableAutoSizing = true;
        buttonText.verticalAlignment = VerticalAlignmentOptions.Middle;
        buttonText.horizontalAlignment = HorizontalAlignmentOptions.Center;
        // Set the button text color
        buttonText.color = Color.black;

        return btn;
    }

    /// <summary>
    /// The listener method to toggle color picking
    /// </summary>
    private void StartPickColor()
    {
        if (pickingColor) return;
        pickingColor = true;
        StartCoroutine(GetScreenImage(Input.mousePosition));
    }

    
    private void Update()
    {
        // If color is being picked
        if(pickingColor)
        {
            // Check if the texture is there
            if(_colorTex != null)
            {
                var mousePos = Input.mousePosition;
                // Get the color from the texture using the mouse position
                pickedColor = _colorTex.GetPixel((int)mousePos.x, (int)mousePos.y);
                
            }

            // If the mouse is pressed stop picking the color
            if(Input.GetMouseButtonDown(0))
            {
                pickingColor = false;
            }

            // Update the color image with the picked color
            colorImage.color = pickedColor;
        }
    }

    /// <summary>
    /// Coroutine to get the screen image every frame
    /// </summary>
    /// <param name="pos"></param>
    /// <returns></returns>
    IEnumerator GetScreenImage(Vector2 pos)
    {
        // Wait until the end of the frame
        yield return new WaitForEndOfFrame();
        // Create a new texture 2D
        _colorTex = new Texture2D(_mainCamera.scaledPixelWidth, _mainCamera.scaledPixelHeight, TextureFormat.RGB24, true);
        // Read pixels from the framebuffer
        _colorTex.ReadPixels(new Rect(0,0, _mainCamera.scaledPixelWidth, _mainCamera.scaledPixelHeight), 0, 0);
        // Load the raw texture data to the texture
        _colorTex.LoadRawTextureData(_colorTex.GetRawTextureData());
        // Apply the texture
        _colorTex.Apply();

    }


}

