        labelText.horizontalAlignment = HorizontalAlignmentOptions.Left;



        // create the position fields
        posFields = new TMP_InputField[3];
        CreateTransformFields(ref posFields, "Position", new string[] { "X", "Y", "Z"});
        // creat the rotation fields
        rotFields = new TMP_InputField[3];
        CreateTransformFields(ref rotFields, "Rotation", new string[] { "RX", "RY", "RZ"});

        // Create the spawn button
        spawnButton = CreateButton("Spawn");
        // Add listener to the spawn button
        spawnButton.onClick.AddListener(UpdateSelectedTransform);

    }


    /// <summary>
    /// This method creates the 3 fields for each of the position and rotation transforms
    /// </summary>
    /// <param name="fields">The fields array</param>
    /// <param name="name">The name of the transform</param>
    /// <param name="labels">The labels of the fields</param>
    private void CreateTransformFields(ref TMP_InputField[] fields, string name, string[] labels)
    {
        // Create the layout gameobject
        var layoutGO = new GameObject(name);
        layoutGO.transform.SetParent(transform);
        layoutGO.AddComponent<RectTransform>();
        // Add a horizontal layout
        var layoutGroup = layoutGO.AddComponent<HorizontalLayoutGroup>();
        // Create the 3 fields with the labels and type of decimal numbers
        fields[0] = CreateField(labels[0], layoutGO.transform, TMP_InputField.ContentType.DecimalNumber);
        fields[1] = CreateField(labels[1], layoutGO.transform, TMP_InputField.ContentType.DecimalNumber);
        fields[2] = CreateField(labels[2], layoutGO.transform, TMP_InputField.ContentType.DecimalNumber);
    }

    /// <summary>
    /// This methods creates a field that is editable
    /// </summary>
    /// <param name="name">The name of the field</param>
    /// <param name="parent">The parent transform for the field</param>
    /// <param name="type">The content type of the field</param>
    /// <returns></returns>
    private TMP_InputField CreateField(string name, Transform parent, TMP_InputField.ContentType type)
    {
        // Create the field gameobjecr
        var fieldGO = new GameObject(name);
        fieldGO.transform.SetParent(parent);
        fieldGO.AddComponent<RectTransform>();
        fieldGO.AddComponent<Image>();

        // The Text area for the field
        var textAreaGO = new GameObject(name);
        textAreaGO.transform.SetParent(fieldGO.transform);
        var textRect = textAreaGO.AddComponent<RectTransform>();
        // Expands to the whole container
        textRect.anchorMin = new Vector2(0, 0);
        textRect.anchorMax = new Vector2(1, 1);
        textRect.anchoredPosition = new Vector2(0, 0);
        textRect.sizeDelta = new Vector2(0, 0);

        // The input field component
        var inputField = fieldGO.AddComponent<TMP_InputField>();
        // Creat the field text
        var fieldText = CreateText(name + "Text", fieldGO.transform, "");
        // Create the text placholder
        var fieldPlaceholder = CreateText(name + "Text Placeholder", fieldGO.transform, name);
        // Set the field text and placeholder
        inputField.textComponent = fieldText;
        inputField.placeholder = fieldPlaceholder;
        // Set the content type
        inputField.contentType = type;
        inputField.textViewport = fieldGO.GetComponent<RectTransform>();
        // Set a custom caret color
        inputField.customCaretColor = true;
        inputField.caretColor = Color.black;
        return inputField;
    }

    /// <summary>
    /// This method creates text elements
    /// </summary>
    /// <param name="name">The name of the gameobjects</param>
    /// <param name="parent"> The parent transform</param>
    /// <param name="defaultText">The default text in the text element</param>
    /// <returns></returns>
    private TextMeshProUGUI CreateText(string name, Transform parent, string defaultText)
    {
        // Create the text gameobject
        var textGO = new GameObject(name);
        textGO.transform.SetParent(parent);
        var textRect = textGO.AddComponent<RectTransform>();
        // Expands to the whole container
        textRect.anchorMin = new Vector2(0, 0);
        textRect.anchorMax = new Vector2(1, 1);
        textRect.anchoredPosition = new Vector2(0, 0);
        textRect.sizeDelta = new Vector2(0, 0);

        // Add the text component
        var textComp = textGO.AddComponent<TextMeshProUGUI>();
        // Set the default text
        textComp.text = defaultText;
        // Auto sizing
        textComp.enableAutoSizing = true;
        // The text color
        textComp.color = Color.black;
        // The vertical alignment
        textComp.verticalAlignment = VerticalAlignmentOptions.Middle;
        // The horizontal alignement
        textComp.horizontalAlignment = HorizontalAlignmentOptions.Center;
        return textComp;
    }

    /// <summary>
    /// This method creates a button with a given name
    /// </summary>
    /// <param name="buttonName">The name of the button</param>
    /// <returns></returns>
    private Button CreateButton(string buttonName)
    {
        // Create the button gameobject
        var buttonGO = new GameObject(buttonName);
        buttonGO.transform.SetParent(transform, false);
        buttonGO.AddComponent<RectTransform>();
        var btn = buttonGO.AddComponent<Button>();

        // Create the image for the button
        var buttonImage = buttonGO.AddComponent<Image>();
        // Set this image as the target for the button
        btn.targetGraphic = buttonImage;


        // Create the text for the button
        var textGO = new GameObject(buttonName + "Text");
        textGO.transform.SetParent(buttonGO.transform, false);
        var buttonText = textGO.AddComponent<TextMeshProUGUI>();
        // Set the text of the button to the name of the button
        buttonText.text = buttonName;
        buttonText.enableAutoSizing = true;
        buttonText.verticalAlignment = VerticalAlignmentOptions.Middle;
        buttonText.horizontalAlignment = HorizontalAlignmentOptions.Center;
        // Set the button text color
        buttonText.color = Color.black;

        return btn;
    }

    /// <summary>
    /// Method to raycast and select object from the camera
    /// </summary>
    /// <param name="screenPos">The screen position to spawn from</param>
    private void RaycastSelectObject(Vector2 screenPos)
    {
        // Get ray from camera
        var ray = mainCamera.ScreenPointToRay(screenPos);
        if(Physics.Raycast(ray, out RaycastHit hit, 1000f, selectableLayerMask))
        {
            if(hit.collider != null)
            {
                // If hit any object select it and update the UI
                selectedObject = hit.collider.gameObject;
                UpdateUI("Selected Object: " + hit.collider.gameObject.name);
            }
        }

    }

    /// <summary>
    /// This method updates the UI
    /// </summary>
    /// <param name="label"></param>
    private void UpdateUI(string label)
    {
        // Update the label
        labelText.text = label;

        // if there is a selected object, set the fields according to its tranforms
        // Also set the field to be editable
        if(selectedObject != null)
        {
            var pos = selectedObject.transform.position;
            var rot = selectedObject.transform.rotation.eulerAngles;
            posFields[0].text = pos.x.ToString();
            posFields[1].text = pos.y.ToString();
            posFields[2].text = pos.z.ToString();
            rotFields[0].text = rot.x.ToString();
            rotFields[1].text = rot.y.ToString();
            rotFields[2].text = rot.z.ToString();

            posFields[0].interactable = true;
            posFields[1].interactable = true;
            posFields[2].interactable = true;
            rotFields[0].interactable = true;
            rotFields[1].interactable = true;
            rotFields[2].interactable = true;

            spawnButton.interactable = true;
        }
        // Otherwise set the fields empty and inactive
        else
        {
            posFields[0].text = "";
            posFields[1].text = "";
            posFields[2].text = "";
            rotFields[0].text = "";
            rotFields[1].text = "";
            rotFields[2].text = "";

            posFields[0].interactable = false;
            posFields[1].interactable = false;
            posFields[2].interactable = false;
            rotFields[0].interactable = false;
            rotFields[1].interactable = false;
            rotFields[2].interactable = false;


            spawnButton.interactable = false;
        }
    }


    /// <summary>
    /// Method to modify the transforms and
    /// create a copy of the selected gameobject
    /// and place it in the designated transform
    /// which is derived from the field values
    /// </summary>
    private void UpdateSelectedTransform()
    {
        if (selectedObject == null) return;
        var pos = new Vector3(float.Parse(posFields[0].text), float.Parse(posFields[1].text), float.Parse(posFields[2].text));
        var rot = new Vector3(float.Parse(rotFields[0].text), float.Parse(rotFields[1].text), float.Parse(rotFields[2].text));
        var newObj = Instantiate(selectedObject);
        newObj.transform.position = pos;
        newObj.transform.rotation = Quaternion.Euler(rot);
    }

    /// <summary>
    /// This method checks if the pointer is on an UI element or not
    /// </summary>
    /// <returns> If the pointer is over an UI element</returns>
    private bool IsPointerOverUIObject()
    {
        PointerEventData eventDataCurrentPosition = new PointerEventData(EventSystem.current);
        eventDataCurrentPosition.position = new Vector2(Input.mousePosition.x, Input.mousePosition.y);

        List<RaycastResult> results = new List<RaycastResult>();
        EventSystem.current.RaycastAll(eventDataCurrentPosition, results);
        return results.Count > 0;
    }

    private void Update()
    {
        if(Input.GetMouseButtonDown(0) && !IsPointerOverUIObject())
        {
            RaycastSelectObject(Input.mousePosition);
        }
        else if(Input.GetMouseButtonDown(1))
        {
            selectedObject = null;
            UpdateUI("Nothing selected!");
        }

    }

}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;

/// <summary>
/// This is the initialization script for the inventory UI system
/// You need to attach ONLY this to a gameobject for everything to function
/// It also has the functionality to generate the UI
/// 
/// REQUIRES A Layer name "Pickup"
/// </summary>
public class InventoryUIInitScript : MonoBehaviour
{
    // The player gameobject
    public static GameObject player;
    // The list of all the pickups
    public static List<GameObject> allPickups = new List<GameObject>();
    // Check if UI needs generation
    public bool generateUI = true;

    // The random radius to spawn pickups
    public float randomRadius = 5f;
    // The number pickups to spawn in the radius
    public int pickupsToSpawn = 5;

    private void Start()
    {
        // If the layer is not found then abort
        if (LayerMask.NameToLayer("Pickup") == -1)
        {
            Debug.LogError("Create a layer named \"Pickup\"!");
            this.enabled = false;
            return;
        }

        // Spawns the player
        SpawnPlayer();

        // Spawns the pickups
        for(int i = 0; i < pickupsToSpawn; i++)
        {
            var randDir = Random.insideUnitSphere;
            randDir.y = 0;
            var spawnPos = player.transform.position + randDir.normalized * Random.Range(1f, randomRadius);
            // Just sets default item data for each pickup
            var itemData = new InventoryItem { name = "DefaultPickup" };
            SpawnPickup(itemData, spawnPos);
        }


        // Checks if has to generate the UI
        if(generateUI)
        {
            GenerateUI();
        }
    }

    /// <summary>
    /// Method to spawn the player
    /// </summary>
    private void SpawnPlayer()
    {

        var playerObject = GameObject.CreatePrimitive(PrimitiveType.Capsule);
        playerObject.name = "Player";
        // Add the player movement component
        playerObject.AddComponent<PlayerMove>();
        // Add the player pickup manager component
        var pickupMan = playerObject.AddComponent<PlayerPickupManager>();
        // Add the player inventory component
        var inventory = playerObject.AddComponent<PlayerInventory>();
        // The pickup manager has this inventory as the reference
        pickupMan.playerInventory = inventory;
        // Player is spawned at origin
        playerObject.transform.position = new Vector3(0,0,0);

        // Set the player reference
        player = playerObject;
    }

    /// <summary>
    /// Method to spawn the pickup
    /// </summary>
    /// <param name="item">The inventory item data</param>
    /// <param name="spawnPos">The position to spawn the pickup</param>
    public static void SpawnPickup(InventoryItem item, Vector3 spawnPos)
    {
        // Create the pickup object and set it to the layer
        var pickupObject = GameObject.CreatePrimitive(PrimitiveType.Cube);
        pickupObject.name = "Pickup" + allPickups.Count;
        pickupObject.layer = LayerMask.NameToLayer("Pickup");

        // Add the pickup component
        var pickupComp = pickupObject.AddComponent<Pickup>();
        pickupComp.itemData = item;

        // Set the position to spawn position
        pickupObject.transform.position = spawnPos;

        // Add to the list
        allPickups.Add(pickupObject);
    }


    private void GenerateUI()
    {
        // Add the background image of the UI
        var bg = gameObject.AddComponent<Image>();
        bg.color = new Color(1.0f, 1.0f, 1.0f, 0.3f);
        var mainLayout = gameObject.AddComponent<VerticalLayoutGroup>();
        // Add the inventory UI component
        var invComp = gameObject.AddComponent<InventoryUI>();
        
        // The layout for the inventory tiles
        var inventoryObj = new GameObject("Inventory Layout");
        inventoryObj.transform.SetParent(transform, false);
        var inventoryRect = inventoryObj.AddComponent<RectTransform>();
        inventoryRect.anchorMin = new Vector2(0, 0);
        inventoryRect.anchorMax = new Vector2(1, 1);
        inventoryRect.sizeDelta = new Vector2(0, 0);
        inventoryRect.anchoredPosition = new Vector2(0, 0);
        var layout = inventoryObj.AddComponent<GridLayoutGroup>();
        layout.cellSize = new Vector2(100, 100);
        layout.spacing = new Vector2(20, 20);

        inventoryObj.SetActive(false);

        // The screen for the inventory 
        invComp.inventoryScreen = inventoryObj;
        invComp.uiGroup = gameObject.AddComponent<CanvasGroup>();
        invComp.HideUI();

    }
}
