using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Events;

/// <summary>
/// The script for the player inventory that keeps track of the items picked up
/// </summary>
public class PlayerInventory : MonoBehaviour
{
    // The list of items
    public List<InventoryItem> inventoryItems = new List<InventoryItem>();

    // On item added to this inventory
    public static UnityAction<InventoryItem, PlayerInventory> OnItemAdd;
    // On item removed from this inventory
    public static UnityAction<InventoryItem, PlayerInventory> OnItemRemove;

    /// <summary>
    /// Method to process a certain kind of pickup
    /// This is just a placeholder, can be edited to make 
    /// new functionality
    /// </summary>
    /// <param name="pickup">The pickup</param>
    public void ProcessPickup(Pickup pickup)
    {
        if (pickup == null) return;
        //DO other logic if it's not required to store in inventory
        InventoryItem newItem = pickup.itemData.Clone() as InventoryItem;
        AddItem(newItem);
    }

    /// <summary>
    /// Method to add item to the inventory
    /// </summary>
    /// <param name="item">The item to add</param>
    public void AddItem(InventoryItem item)
    {
        if(!inventoryItems.Contains(item))
        {
            inventoryItems.Add(item);
            OnItemAdd?.Invoke(item, this);
        }
    }
    
    /// <summary>
    /// Method to drop item from the inventory
    /// </summary>
    /// <param name="drop">item to drop</param>
    public void DropItem(InventoryItem drop)
    {
        if(inventoryItems.Contains(drop))
        {
            inventoryItems.Remove(drop);
            OnItemRemove?.Invoke(drop, this);
        }
    }
}
using System.Collections;
using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// The manager class to manage the pickups in the game
/// </summary>
public class PlayerPickupManager : MonoBehaviour
{
    // The main camera
    private Camera _mainCamera;
    // The layer for the pickup
    public LayerMask pickupLayers;
    // The min distance pickups can be picked up
    public float maxPickupDistance = 2f;
    // The reference to the player inventory
    public PlayerInventory playerInventory;
    private void Start()
    {
        // Get the camera
        _mainCamera = Camera.main;
        // Get the pickup layers
        pickupLayers = (1 << LayerMask.NameToLayer("Pickup"));
    }

    private void Update()
    {
        // On mouse down
        if(Input.GetMouseButtonDown(0))
        {
            // cast the ray from screen
            var ray = _mainCamera.ScreenPointToRay(Input.mousePosition);

            // if nothing hit, return
            if (!Physics.Raycast(ray, out RaycastHit hitInfo, 100f, pickupLayers)) return;

            if(hitInfo.collider != null)
            {
                // Otherwise check the pickup distance and if it is indeed a pickup
                if(Vector3.Distance(hitInfo.collider.transform.position, transform.position) <= maxPickupDistance &&
                    hitInfo.collider.gameObject.TryGetComponent<Pickup>(out Pickup p))
                {
                    // If it is a pickup then send it to the player inventory for processing
                    playerInventory.ProcessPickup(p);
                    // Destroy the pickup object
                    Destroy(p.gameObject);
                }
            }
        }
    }
}
