/// <summary>
/// The class to do the inventory UI
/// </summary>
public class InventoryUI : MonoBehaviour
{
    // The inventory screen
    public GameObject inventoryScreen;
    // The canvasgroup for the inventory screen
    public CanvasGroup uiGroup;
    Dictionary<InventoryItem, Button> correspondingButtons = new Dictionary<InventoryItem, Button>();

    private void Start()
    {
    }
    private void Update()
    {
        // Toggle the inventory on pressing I on keyboard
        if(Input.GetKeyDown(KeyCode.I))
        {
            if (inventoryScreen.activeInHierarchy)
            {
                HideUI();
            }
            else {
                ShowUI();
            }
        }
    }

    /// <summary>
    /// Method to show the inventory
    /// </summary>
    public void ShowUI()
    {
        uiGroup.alpha = 1f;
        uiGroup.interactable = true;
        inventoryScreen.SetActive(true);
    }

    /// <summary>
    /// Method to hide the inventory
    /// </summary>
    public void HideUI()
    {
        uiGroup.alpha = 0f;
        uiGroup.interactable = false;
        inventoryScreen.SetActive(false);
    }

    /// <summary>
    /// Subscribe to player inventory actions
    /// </summary>
    private void OnEnable()
    {
        PlayerInventory.OnItemAdd += AddItemButton;
        PlayerInventory.OnItemRemove += RemoveItemButton;
    }

    /// <summary>
    /// Unsubscribe from player inventory actions
    /// </summary>
    private void OnDisable()
    {
        PlayerInventory.OnItemAdd -= AddItemButton;
        PlayerInventory.OnItemRemove -= RemoveItemButton;
    }

    /// <summary>
    /// Method to add item buttons
    /// </summary>
    /// <param name="item">The item data</param>
    /// <param name="inv">The inventory reference</param>
    private void AddItemButton(InventoryItem item, PlayerInventory inv)
    {
        var button = CreateButton(inventoryScreen.transform, item.name);
        if(!correspondingButtons.ContainsKey(item))
        {
            button.onClick.AddListener(() =>
            {
                inv.DropItem(item);
            });
            correspondingButtons.Add(item, button);
        }
    }

    /// <summary>
    /// Method to remove item from an inventory
    /// </summary>
    /// <param name="item">The item data</param>
    /// <param name="inv">The inventory reference</param>
    private void RemoveItemButton(InventoryItem item, PlayerInventory inv)
    {
        if(correspondingButtons.ContainsKey(item))
        {
            var button = correspondingButtons[item];
            Destroy(button.gameObject);
            correspondingButtons.Remove(item);
        }
    }

    /// <summary>
    /// Method to create inventory buttons
    /// </summary>
    /// <param name="parent">The parent transform, inventory grid</param>
    /// <param name="buttonName">The button name</param>
    /// <returns></returns>
    private Button CreateButton(Transform parent, string buttonName)
    {
        var buttonGO = new GameObject(buttonName);
        buttonGO.transform.SetParent(parent, false);
        buttonGO.AddComponent<RectTransform>();
        var btn = buttonGO.AddComponent<Button>();

        var buttonImage = buttonGO.AddComponent<Image>();
        btn.targetGraphic = buttonImage;

        var textGO = new GameObject(buttonName + "Text");
        textGO.transform.SetParent(buttonGO.transform, false);
        var textRect = textGO.AddComponent<RectTransform>();
        textRect.anchorMin = new Vector2(0, 0);
        textRect.anchorMax = new Vector2(1, 1);
        textRect.sizeDelta = new Vector2(0, 0);
        textRect.anchoredPosition = new Vector2(0, 0);
        var buttonText = textGO.AddComponent<TextMeshProUGUI>();
        buttonText.text = buttonName;
        buttonText.enableAutoSizing = true;
        buttonText.verticalAlignment = VerticalAlignmentOptions.Middle;
        buttonText.horizontalAlignment = HorizontalAlignmentOptions.Center;

        buttonText.color = Color.black;

        return btn;
    }

}

