/// <summary>
///  Class to keep track of remaining bullets
/// </summary>
public class BulletsUI : MonoBehaviour
{
    // Check if ui needs generation
    public bool generateUI = true;
    // Check if behaviour also needs to be generated
    public bool generateBehaviour = true;

    // the text for the remaining bullets
    public TextMeshProUGUI bulletsText;

    private void Start()
    {
        // if checked then generate UI
        if(generateUI)
        {
            GenerateUI();
        }

        // if checked then generate the behaviour
        if(generateBehaviour)
        {
            GenerateBehaviour();
        }
    }


    private void GenerateUI()
    {
        // Create the text for the bullets
        bulletsText = CreateText("Bullets", transform, "Bullets: 0");
    }

    private void OnEnable()
    {
        // Subscribe to player shoot events
        PlayerShoot.OnBulletsUpdate += UpdateBulletText;
    }

    private void OnDisable()
    {
        // Unsubscribe from player shoot events
        PlayerShoot.OnBulletsUpdate -= UpdateBulletText;
    }

    /// <summary>
    /// This method creates text elements
    /// </summary>
    /// <param name="name">The name of the text</param>
    /// <param name="parent">The parent transform</param>
    /// <param name="defaultText">The default text</param>
    /// <returns></returns>
    private TextMeshProUGUI CreateText(string name, Transform parent, string defaultText)
    {
        // The text gameobject
        var textGO = new GameObject(name);
        textGO.transform.SetParent(parent);
        var textRect = textGO.AddComponent<RectTransform>();
        // Expands to the whole container
        textRect.anchorMin = new Vector2(0, 0);
        textRect.anchorMax = new Vector2(1, 1);
        textRect.anchoredPosition = new Vector2(0, 0);
        textRect.sizeDelta = new Vector2(0, 0);

        // The text component
        var textComp = textGO.AddComponent<TextMeshProUGUI>();
        textComp.text = defaultText;
        textComp.enableAutoSizing = true;
        // Set the color to black
        textComp.color = Color.black;
        textComp.verticalAlignment = VerticalAlignmentOptions.Middle;
        textComp.horizontalAlignment = HorizontalAlignmentOptions.Center;
        return textComp;
    }


    private void GenerateBehaviour()
    {
        // Get the camera
        var camera = Camera.main;
        // Abort if no camera found
        if(camera == null)
        {
            Debug.LogError("No camera found!");
            this.enabled = false;
            return;
        }

        // Add shooting component to camera
        var shootScript = camera.gameObject.AddComponent<PlayerShoot>();
        // Create a placeholder prefab for the bullets
        var bulletPrefab = GameObject.CreatePrimitive(PrimitiveType.Sphere);
        bulletPrefab.transform.localScale *= 0.2f;
        bulletPrefab.AddComponent<Rigidbody>();
        bulletPrefab.SetActive(false);
        shootScript.bulletPrefab = bulletPrefab;
    }

    /// <summary>
    /// The listener function to update the bullet text
    /// </summary>
    /// <param name="bullets">The bullets from the shoot script</param>
    public void UpdateBulletText(int bullets)
    {
        bulletsText.text = "Bullets: " + bullets;
    }
}
