    public static UnityAction<int> OnBulletsUpdate;
    // The prefab for the bullets
    public GameObject bulletPrefab;

    private void Start()
    {
        // Get the camera
        cam = GetComponent<Camera>();
        OnBulletsUpdate?.Invoke(bullets);
    }

    private void Update()
    {
        // If mouse left is pressed then shoot
        if(Input.GetMouseButtonDown(0))
        {
            Shoot();
        }
    }

    private void Shoot()
    {
        // IF no bullets then return
        if (bullets <= 0) return;

        // Get the ray from the camera
        var ray = cam.ScreenPointToRay(Input.mousePosition);
        var bullet = Instantiate(bulletPrefab);
        bullet.transform.position = ray.origin;
        bullet.transform.forward = ray.direction;
        bullet.SetActive(true);
        // Shoot the bullet along the ray direction
        bullet.GetComponent<Rigidbody>().AddForce(bulletForce * ray.direction, ForceMode.Impulse);

        // Expend one bullet
        bullets -= 1;
        OnBulletsUpdate?.Invoke(bullets);

    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;

/// <summary>
/// This class creates a spinning cube at a location with a slider to control it
/// </summary>
public class SpinningCubeWithSlider : MonoBehaviour
{
    public bool generateUI = true;
    public Slider speedSlider;

    public Vector3 startLocation = new Vector3(0, 0, 0);
    public Vector3 spinAxis = new Vector3(0, 1, 0);
    public float maxRotationSpeed = 10f;
    public float minRotationSpeed = 0f;

    private Transform cubeTransform;
    private float _rotationSpeed = 0f;
    private float _currentAngle = 0f;

    private void Start()
    {
        // Check if UI needs to be generated
        if(generateUI)
        {
            GenerateUI();
        }

        // The new Cube
        var newCube = GameObject.CreatePrimitive(PrimitiveType.Cube);
        cubeTransform = newCube.transform;
        // Cube positioned at start position
        cubeTransform.position = startLocation;
        _currentAngle = 0f;
        // Set the rotation in the spin axis as 0
        cubeTransform.rotation = Quaternion.AngleAxis(_currentAngle, spinAxis.normalized);
    }

    /// <summary>
    /// Method to generate the UI
    /// </summary>
    private void GenerateUI()
    {
        // Create the speed slider
        speedSlider = CreateSlider(transform);
        // Add listener to the spin slider
        speedSlider.onValueChanged.AddListener(UpdateRotationSpeed);
        // Setup the max value for the slider
        speedSlider.maxValue = maxRotationSpeed;
        // Setup the min value for the slider
        speedSlider.minValue = minRotationSpeed;
    }
    /// <summary>
    /// This method creates a slider
    /// </summary>
    /// <param name="parent">The parent transform for the slider</param>
    /// <returns></returns>
    private Slider CreateSlider(Transform parent)
    {
        // The background image for the slider
        var backgroundImageGO = new GameObject("Background");
        backgroundImageGO.transform.SetParent(parent, false);
        var bgRect = backgroundImageGO.AddComponent<RectTransform>();
        // Expand the container
        bgRect.anchorMin = new Vector2(0, 0);
        bgRect.anchorMax = new Vector2(1, 1);
        bgRect.sizeDelta = new Vector2(0, 0);
        bgRect.anchoredPosition = new Vector2(0, 0);
        var bgImage = backgroundImageGO.AddComponent<Image>();
        bgImage.color = Color.grey;


        // The fill area for the slider
        var fillAreaGO = new GameObject("FillArea");
        fillAreaGO.transform.SetParent(parent, false);
        var fillAreaRect = fillAreaGO.AddComponent<RectTransform>();
        // Expands the container
        fillAreaRect.anchorMin = new Vector2(0, 0);
        fillAreaRect.anchorMax = new Vector2(1, 1);
        fillAreaRect.sizeDelta = new Vector2(0, 0);
        fillAreaRect.anchoredPosition = new Vector2(0, 0);

        // The fill rect of the slider
        var fillGO = new GameObject("Fill");
        fillGO.transform.SetParent(fillAreaGO.transform, false);
        var fillRect = fillGO.AddComponent<RectTransform>();
        // Fills from left
        fillRect.anchorMin = new Vector2(0, 0);
        fillRect.anchorMax = new Vector2(0, 1);
        fillRect.sizeDelta = new Vector2(0, 0);
        fillRect.anchoredPosition = new Vector2(0, 0);

        // The fill image and it is green in color
        var fillImage = fillGO.AddComponent<Image>();
        fillImage.color = Color.green;
        
        // The handle area to slide the handle
        var handleAreaGO = new GameObject("HandleArea");
        handleAreaGO.transform.SetParent(parent, false);
        var handleAreaRect = handleAreaGO.AddComponent<RectTransform>();

        // Expands the whole container
        handleAreaRect.anchorMin = new Vector2(0, 0);
        handleAreaRect.anchorMax = new Vector2(1, 1);
        handleAreaRect.sizeDelta = new Vector2(0, 0);
        handleAreaRect.anchoredPosition = new Vector2(0, 0);
        
        // The handle gameobject
        var handleGO = new GameObject("Handle");
        handleGO.transform.SetParent(handleAreaGO.transform, false);
        var handleRect = handleGO.AddComponent<RectTransform>();
        // The rect is anchored to the left side
        handleRect.anchorMin = new Vector2(0, 0);
        handleRect.anchorMax = new Vector2(0, 1);
        handleRect.sizeDelta = new Vector2(20, 10); // Width and height
        handleRect.anchoredPosition = new Vector2(0, 0);

        // Add the image to the handle
        var handleImage = handleGO.AddComponent<Image>();
        handleImage.color = Color.white;



        // Add the slider component
        var slider = parent.gameObject.AddComponent<Slider>();
        // Assign the filling rect
        slider.fillRect = fillRect;
        // Assign the handle rect
        slider.handleRect = handleRect;

        return slider;
    }

    /// <summary>
    /// Method to update the rotation speed
    /// </summary>
    /// <param name="value"> The new speed </param>
    private void UpdateRotationSpeed(float value)
    {
        _rotationSpeed = value;
    }

    private void Update()
    {
        // Update the current angle with the speed
        _currentAngle += _rotationSpeed * Time.deltaTime;
        // Set the rotation with the current angle
        cubeTransform.rotation = Quaternion.AngleAxis(_currentAngle, spinAxis.normalized);
    }

}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;
using TMPro;

/// <summary>
/// This class creates a system to view any gameobject close to camera
/// </summary>
public class ViewObjectUI : MonoBehaviour
{
    // Boolean to check if needs to generate UI
    public bool generateUI = true;

    // The button to stop viewing
    public Button closeButton;
    // The main camera
    private Camera _mainCamera;
    /// <summary>
    /// The layer mask, IMPORTANT TO SELECT IN INSPECTOR
    /// </summary>
    public LayerMask selectableLayers;
    // The offset from the camera
    public Vector3 offsetFromCamera = new Vector3(0, 0, 5);
    // The view rotation
    public Vector3 viewRotation;

    // Flag to toggle viewing
    private bool _viewing = false;
    // The current object to view
    private GameObject _currentObject;
    // The previous parent of the current object
    private Transform _previousParent;
    // The object's previous local position
    private Vector3 _objectPosition;
    // The object's previous local rotation
    private Quaternion _objectRotation;

    // The last mouse position
    private Vector3 lastMouse;
    // The rotation axis
    private Vector3 axis;

    private void Start()
    {
        // Get the camera
        _mainCamera = Camera.main;
        // If no camera then abort
        if(_mainCamera == null)
        {
            Debug.LogError("Camera not found!");
            this.enabled = false;
            return;
        }

        // Check if UI needs to be generated
        if(generateUI)
        {
            // Creat the close button
            closeButton = CreateButton(transform, "X");
        }

        // Deactivate the close button
        closeButton.gameObject.SetActive(false);
        // Add on click listener to the close button
        closeButton.onClick.AddListener(EndViewObject);
    }

    /// <summary>
    /// Method to create a button
    /// </summary>
    /// <param name="parent">The parent transform</param>
    /// <param name="buttonName">The name of the button/text</param>
    /// <returns></returns>
    private Button CreateButton(Transform parent, string buttonName)
    {
        // Create the button gameobject
        var buttonGO = new GameObject(buttonName);
        buttonGO.transform.SetParent(parent, false);
        buttonGO.AddComponent<RectTransform>();
        var btn = buttonGO.AddComponent<Button>();

        // Add the image for visualization
        var buttonImage = buttonGO.AddComponent<Image>();
        btn.targetGraphic = buttonImage;

        // Add the button text
        var textGO = new GameObject(buttonName + "Text");
        textGO.transform.SetParent(buttonGO.transform, false);
        var textRect = textGO.AddComponent<RectTransform>();
        // Set the text to expand the container
        textRect.anchorMin = new Vector2(0, 0);
        textRect.anchorMax = new Vector2(1, 1);
        textRect.sizeDelta = new Vector2(0, 0);
        textRect.anchoredPosition = new Vector2(0, 0);
        // Create the text component
        var buttonText = textGO.AddComponent<TextMeshProUGUI>();
        buttonText.text = buttonName;
        buttonText.enableAutoSizing = true;
        buttonText.verticalAlignment = VerticalAlignmentOptions.Middle;
        buttonText.horizontalAlignment = HorizontalAlignmentOptions.Center;

        // Set text color to black
        buttonText.color = Color.black;

        return btn;
    }

    private void Update()
    {
        // Check if object is not
        if(!_viewing)
        {
            // if not viewing raycast and try select object
            if(Input.GetMouseButtonDown(0))
            {
                var ray = _mainCamera.ScreenPointToRay(Input.mousePosition);
                if(Physics.Raycast(ray, out RaycastHit hit, 1000f, selectableLayers))
                {
                    if(hit.collider != null)
                    {
                        // if the ray hits a selectable object, select it, and startviewing
                        StartViewObject(hit.collider.gameObject);
                    }
                }
            }
        }
        // If object is being viewed
        else
        {
            // Get the first input for mouse
            if(Input.GetMouseButtonDown(0))
            {
                lastMouse = Input.mousePosition;
            }
            else if(Input.GetMouseButton(0))
            {
                // Get the mouse movement delat
                var mouseDelta = (Input.mousePosition - lastMouse).normalized;
                lastMouse = Input.mousePosition;

                // Get a rotation axis according to the mouse movement
                axis = Vector3.Cross(mouseDelta, _mainCamera.transform.forward).normalized;

                // Get a target rotation based on the mouse delta
                var targetRot = Quaternion.AngleAxis(120f * Time.deltaTime, axis);
                // Rotate the object
                _currentObject.transform.rotation *= targetRot;
            }
            else if(Input.GetMouseButtonUp(0))
            {
                // Do nothing again if mouse is up
            }
        }
    }

    /// <summary>
    /// Method to start viewing any object
    /// </summary>
    /// <param name="target">The target gameobject</param>
    private void StartViewObject(GameObject target)
    {
        // Save the previous parent, position and rotation for game object
        _previousParent = target.transform.parent;
        _objectPosition = target.transform.localPosition;
        _objectRotation = target.transform.localRotation;

        // Set the current object
        _currentObject = target;
        // Parent it to the camera
        _currentObject.transform.SetParent(_mainCamera.transform);
        // Set the position to the offset of the camera
        _currentObject.transform.localPosition = Vector3.zero + offsetFromCamera;
        // Set rotation to view rotation
        _currentObject.transform.localRotation = Quaternion.Euler(viewRotation);

        
        _viewing = true;
        // Show the close button
        closeButton.gameObject.SetActive(true);
    }

    /// <summary>
    /// Method to end viewing object
    /// </summary>
    private void EndViewObject()
    {
        // Restore the transform properties for the object
        _currentObject.transform.SetParent(_previousParent);
        _currentObject.transform.localPosition = Vector3.zero;
        _currentObject.transform.localRotation = Quaternion.identity;
        _currentObject.transform.localPosition = _objectPosition;
        _currentObject.transform.localRotation = _objectRotation;
        // Reset the current object
        _currentObject = null;

        // Hide the close button
        closeButton.gameObject.SetActive(false);
        // Set the flag 
        _viewing = false;
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;
using TMPro;

/// <summary>
/// This script creates an item viewer from the scene which
/// has a list of objects that can be viewed using the UI
/// </summary>
public class ViewObjectListUI : MonoBehaviour
{
    // boolean flag to check if UI needs to be generated
    public bool generateUI = true;

    // The button to cycle to next item
    public Button nextButton;
    // The button to cycke to previous item
    public Button previousButton;

    // the main camera
    private Camera _mainCamera;
    /// <summary>
    /// The selectable layers, NEEDS TO BE SET IN INSPECTOR
    /// </summary>
    public LayerMask selectableLayers;
    // The offset from the camera
    public Vector3 offsetFromCamera = new Vector3(0, 0, 5);
    // the viewing rotation
    public Vector3 viewRotation;

    // The flag if viewing
    private bool _viewing = false;
    // The current object
    private GameObject _currentObject;
    // The previous parent
    private Transform _previousParent;
    // The object position before viewing
    private Vector3 _objectPosition;
    // The object rotation before viewing
    private Quaternion _objectRotation;

    // The last mouse position
    private Vector3 lastMouse;
    // The axis of rotation
    private Vector3 axis;

    // The list of game objects to view and cycle through
    public List<GameObject> objectsToView = new List<GameObject>();
    // The current index of viewing
    private int currentIndex = -1;

    private void Start()
    {
        // Get the camera
        _mainCamera = Camera.main;
        // Abort if no camera
        if(_mainCamera == null)
        {
            Debug.LogError("Camera not found!");
            this.enabled = false;
            return;
        }

        // abort if the list of objects is empty
        if(objectsToView.Count == 0)
        {
            Debug.LogError("Provide a list of objects!");
            this.enabled = false;
            return;
        }

        // Check if UI needs generation
        if(generateUI)
        {
            // Create the button for previous item
            previousButton = CreateButton(transform, "<");
            var prevButtonRect = previousButton.gameObject.GetComponent<RectTransform>();
            // Place button to left and anchor to the left center
            prevButtonRect.anchorMin = new Vector2(0, 0.5f);
            prevButtonRect.anchorMax = new Vector2(0, 0.5f);
            prevButtonRect.pivot = new Vector2(0, 0.5f);
            prevButtonRect.sizeDelta = new Vector2(0, 0);
            prevButtonRect.sizeDelta = new Vector2(100, 400);
            prevButtonRect.anchoredPosition = new Vector2(200, 0);
            // Add the listener for previous item
            previousButton.onClick.AddListener(PreviousObject);

            // Create button for the next item
            nextButton = CreateButton(transform, ">");
            var nextButtonRect = nextButton.gameObject.GetComponent<RectTransform>();
            // Place button to the right and anchor to the right center
            nextButtonRect.anchorMin = new Vector2(1, 0.5f);
            nextButtonRect.anchorMax = new Vector2(1, 0.5f);
            nextButtonRect.pivot = new Vector2(1, 0.5f);
            nextButtonRect.sizeDelta = new Vector2(0, 0);
            nextButtonRect.sizeDelta = new Vector2(100, 400);
            nextButtonRect.anchoredPosition = new Vector2(-200, 0);
            // Add the listener for the next item
            nextButton.onClick.AddListener(NextObject);
        }

        // Start viewing from the start of the list
        NextObject();

    }

    /// <summary>
    /// Method to create a button
    /// </summary>
    /// <param name="parent">The parent transform</param>
    /// <param name="buttonName">The name of the button/text</param>
    /// <returns></returns>
    private Button CreateButton(Transform parent, string buttonName)
    {
        // Create the button gameobject
        var buttonGO = new GameObject(buttonName);
        buttonGO.transform.SetParent(parent, false);
        buttonGO.AddComponent<RectTransform>();
        var btn = buttonGO.AddComponent<Button>();

        // Add the image for visualization
        var buttonImage = buttonGO.AddComponent<Image>();
        btn.targetGraphic = buttonImage;

        // Add the button text
        var textGO = new GameObject(buttonName + "Text");
        textGO.transform.SetParent(buttonGO.transform, false);
        var textRect = textGO.AddComponent<RectTransform>();
        // Set the text to expand the container
        textRect.anchorMin = new Vector2(0, 0);
        textRect.anchorMax = new Vector2(1, 1);
        textRect.sizeDelta = new Vector2(0, 0);
        textRect.anchoredPosition = new Vector2(0, 0);
        // Create the text component
        var buttonText = textGO.AddComponent<TextMeshProUGUI>();
        buttonText.text = buttonName;
        buttonText.enableAutoSizing = true;
        buttonText.verticalAlignment = VerticalAlignmentOptions.Middle;
        buttonText.horizontalAlignment = HorizontalAlignmentOptions.Center;

        // Set text color to black
        buttonText.color = Color.black;

        return btn;
    }

    private void Update()
    {
        if(_viewing)
        {
            if(Input.GetMouseButtonDown(0))
            {
                lastMouse = Input.mousePosition;
            }
            else if(Input.GetMouseButton(0))
            {
                var mouseDelta = (Input.mousePosition - lastMouse).normalized;
                lastMouse = Input.mousePosition;

                axis = Vector3.Cross(mouseDelta, _mainCamera.transform.forward).normalized;

                var targetRot = Quaternion.AngleAxis(120f * Time.deltaTime, axis);
                _currentObject.transform.rotation *= targetRot;
            }
            else if(Input.GetMouseButtonUp(0))
            {

            }
        }
    }
    /// <summary>
    /// Method to start viewing any object
    /// </summary>
    /// <param name="target">The target gameobject</param>
    private void StartViewObject(GameObject target)
    {
        // Save the previous parent, position and rotation for game object
        _previousParent = target.transform.parent;
        _objectPosition = target.transform.localPosition;
        _objectRotation = target.transform.localRotation;

        // Set the current object
        _currentObject = target;
        // Parent it to the camera
        _currentObject.transform.SetParent(_mainCamera.transform);
        // Set the position to the offset of the camera
        _currentObject.transform.localPosition = Vector3.zero + offsetFromCamera;
        // Set rotation to view rotation
        _currentObject.transform.localRotation = Quaternion.Euler(viewRotation);


        _viewing = true;

        // Set the buttons visible
        nextButton.gameObject.SetActive(true);
        previousButton.gameObject.SetActive(true);

    }

    private void EndViewObject()
    {
        // If nothing is being viewed return
        if (_currentObject == null)
        {
            _viewing = false;
            return;
        }

        // Reset the object to the saved locations
        _currentObject.transform.SetParent(_previousParent);
        _currentObject.transform.localPosition = Vector3.zero;
        _currentObject.transform.localRotation = Quaternion.identity;
        _currentObject.transform.localPosition = _objectPosition;
        _currentObject.transform.localRotation = _objectRotation;
        // Reset current object
        _currentObject = null;

        // Set flag
        _viewing = false;
        // Hide the UI
        nextButton.gameObject.SetActive(false);
        previousButton.gameObject.SetActive(false);
    }


    /// <summary>
    /// Method to cycle to next object
    /// </summary>
    private void NextObject()
    {
        // End the viewing of the previous object
        EndViewObject();
        // Check if the list is empty
        if(objectsToView.Count == 0)
        {
            return;
        }

        // Increment the current index
        currentIndex += 1;
        // Wrap around the index
        if(currentIndex == objectsToView.Count)
        {
            currentIndex = 0;
        }
        // Wrap around in the other direction
        else if(currentIndex < 0)
        {
            currentIndex = objectsToView.Count - 1;
        }

        // Start viewing the next object
        StartViewObject(objectsToView[currentIndex]);
    }

    /// <summary>
    /// Method to cycle to the previous object
    /// </summary>
    private void PreviousObject()
    {
        // end viewing previous object
        EndViewObject();
        currentIndex -= 1;
        // Wrap around
        if(currentIndex == objectsToView.Count)
        {
            currentIndex = 0;
        }
        else if(currentIndex < 0)
        {
            currentIndex = objectsToView.Count - 1;
        }
        // Start viewing the next object
        StartViewObject(objectsToView[currentIndex]);
    }
}

