    /// <summary>
    /// Listener method for slider value change which changes the speed
    /// </summary>
    /// <param name="value">The new value</param>
    public void SpeedChange(float value)
    {
        // Get particle main reference
        var main = particles.main;
        // Edit the reference
        main.startSpeed = value;
    }

    /// <summary>
    /// Listener method for slider value change which changes the flow
    /// </summary>
    /// <param name="value">The new value</param>
    public void FlowChange(float value)
    {
        // Get the emission reference
        var em = particles.emission;
        // Edit the reference
        em.rateOverTime = value;
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;
using TMPro;
/// <summary>
/// A script to generate a placeholder options menu for selectable objects
/// in a scene. This option menu can be used to modify this object.
/// The delete object functionality is provided as an example here.
/// </summary>
public class ObjectInspector : MonoBehaviour
{
    // Check if UI should be generated
    public bool generateUI = true;
    // The options menu gameobject
    public GameObject optionsMenu;
    /// <summary>
    /// The selectable layers, NEED TO SELECT IN INSPECTOR
    /// </summary>
    public LayerMask selectableLayers;

    // The main camera
    private Camera _mainCamera;


    // The delete button
    public Button deleteButton;
    /// NOTE: ADD MORE BUTTONS ETC HERE
    // The selected object
    public GameObject selected;

    private void Start()
    {
        // Get the camera
        _mainCamera = Camera.main;
        // If no camera then abort
        if(_mainCamera == null)
        {
            Debug.LogError("Camera not found!");
            this.enabled = false;
            return;
        }

        // If checked then generate the UI
        if(generateUI)
        {
            // Create the options menu
            optionsMenu = new GameObject("Options");
            var rect = optionsMenu.AddComponent<RectTransform>();
            rect.transform.SetParent(transform);
            rect.anchorMin = new Vector2(0, 0);
            rect.anchorMax = new Vector2(1, 1);
            rect.sizeDelta = new Vector2(0, 0);
            rect.anchoredPosition = new Vector2(0, 0);

            // Add a layout group
            optionsMenu.AddComponent<VerticalLayoutGroup>();

            // Add the delete button
            deleteButton = CreateButton(optionsMenu.transform, "Delete");
            /// ADD MORE BUTTONS HERE
            
            // Disable the menu
            optionsMenu.gameObject.SetActive(false);

            // Add listeners to the buttons
            deleteButton.onClick.AddListener(DeleteObject);
        }

    }
    /// <summary>
    /// Method to create a button
    /// </summary>
    /// <param name="parent">The parent transform</param>
    /// <param name="buttonName">The name of the button/text</param>
    /// <returns></returns>
    private Button CreateButton(Transform parent, string buttonName)
    {
        // Create the button gameobject
        var buttonGO = new GameObject(buttonName);
        buttonGO.transform.SetParent(parent, false);
        buttonGO.AddComponent<RectTransform>();
        var btn = buttonGO.AddComponent<Button>();

        // Add the image for visualization
        var buttonImage = buttonGO.AddComponent<Image>();
        btn.targetGraphic = buttonImage;

        // Add the button text
        var textGO = new GameObject(buttonName + "Text");
        textGO.transform.SetParent(buttonGO.transform, false);
        var textRect = textGO.AddComponent<RectTransform>();
        // Set the text to expand the container
        textRect.anchorMin = new Vector2(0, 0);
        textRect.anchorMax = new Vector2(1, 1);
        textRect.sizeDelta = new Vector2(0, 0);
        textRect.anchoredPosition = new Vector2(0, 0);
        // Create the text component
        var buttonText = textGO.AddComponent<TextMeshProUGUI>();
        buttonText.text = buttonName;
        buttonText.enableAutoSizing = true;
        buttonText.verticalAlignment = VerticalAlignmentOptions.Middle;
        buttonText.horizontalAlignment = HorizontalAlignmentOptions.Center;

        // Set text color to black
        buttonText.color = Color.black;

        return btn;
    }



    private void Update()
    {
        // If right mouse is pressed then try and select an object
        if(Input.GetMouseButtonDown(1))
        {
            var ray = _mainCamera.ScreenPointToRay(Input.mousePosition);
            if (Physics.Raycast(ray, out RaycastHit hit, 1000f, selectableLayers))
            {
                if (hit.collider != null)
                {
                    // if object is hit, select it and show the options
                    selected = hit.collider.gameObject;
                    ShowOptions(Input.mousePosition);
                }
            }
            else
            {
                HideOptions();
            }
        }
    }

    /// <summary>
    /// Show option menu at position
    /// </summary>
    /// <param name="pos">Screen position</param>
    private void ShowOptions(Vector2 pos)
    {
        GetComponent<RectTransform>().position = pos;
        optionsMenu.SetActive(true);
    }

    /// <summary>
    /// Hides the option menu
    /// </summary>
    private void HideOptions()
    {
        optionsMenu.SetActive(false);
    }

    /// <summary>
    /// Listener to delete the currently selected object
    /// </summary>
    private void DeleteObject()
    {
        if (selected == null) return;
        HideOptions();
        Destroy(selected);
    }
}

using System;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;

public class SnakeUIController : MonoBehaviour
{
    private Text gameOverText; // Game over text
    private Text scoreText; // Score text
    private Button upButton; // Button for moving up
    private Button downButton; // Button for moving down
    private Button leftButton; //  Button for moving left
    private Button rightButton; //  Button for moving right
    private Button startButton; // Button for starting game
    private Button resetButton; // Button for restarting game
    private KeyCode upKeyCode = KeyCode.UpArrow; // Key code for moving up
    private KeyCode downKeyCode = KeyCode.DownArrow; // Key code for moving down
    private KeyCode leftKeyCode = KeyCode.LeftArrow; // Key code for moving left
    private KeyCode rightKeyCode = KeyCode.RightArrow; // Key code for moving right
    private SnakePlayerController snakePlayerController; // snake player controller
    private SnakeEnvironmentController snakeEnvironmentController; // Endless runner environment controller
    
    private void Start() // Start is called before the first frame update
    {
        GenerateUI(); // Generate UI
