        }
        if (Input.GetKeyDown(KeyCode.R)) // If r key is pressed
        {
            ResetGame(); // Reset game
        }
        if (Input.GetKeyDown(upKeyCode)) // If up key is pressed
        {
            UpdateSnakeDirection(SnakePlayerController.eSnakeDirection.Up); // Rotate player up
        }
        if (Input.GetKeyDown(downKeyCode)) // If down key is pressed
        {
            UpdateSnakeDirection(SnakePlayerController.eSnakeDirection.Down); // Rotate player down
        }
        if (Input.GetKeyDown(leftKeyCode)) // If left key is pressed
        {
            UpdateSnakeDirection(SnakePlayerController.eSnakeDirection.Left); // Rotate player left
        }
        if (Input.GetKeyDown(rightKeyCode)) // If right key is pressed
        {
            UpdateSnakeDirection(SnakePlayerController.eSnakeDirection.Right); // Rotate player right
        }
    }

    void GenerateUI() // Generate UI
    {
        scoreText = GenerateText("ScoreText", Color.white, null, false); // Generate score text
        scoreText.text = "Score: 0"; // Set score text
        scoreText.transform.localPosition = new Vector3(0f, 300f, 0f); // Set score text local position
        gameOverText = GenerateText("GameOverText", Color.red, null, false); // Generate game over text
        gameOverText.text = "Game Over"; // Set game over text
        gameOverText.fontSize = 60; // Set game over text font size
        gameOverText.transform.localPosition = new Vector3(0f, 0f, 0f); // Set game over text local position
        gameOverText.gameObject.SetActive(false); // Set game over text to inactive
        
        upButton = GenerateButton("UpButton", "Up", Color.black, new Vector2(150f, 100f), new Vector3(475f,-150f,0f)); // Generate button for up movement
        downButton = GenerateButton("DownButton", "Down", Color.black, new Vector2(150f, 100f), new Vector3(475f,-400f,0f)); // Generate button for down movement
        leftButton = GenerateButton("LeftButton", "Left", Color.black, new Vector2(150f, 100f), new Vector3(350,-275,0f)); // Generate button for left movement
        rightButton = GenerateButton("RightButton", "Right", Color.black, new Vector2(150f, 100f), new Vector3(600,-275,0f)); // Generate button for right movement
        startButton = GenerateButton("StartButton", "Start", Color.green, new Vector2(200f, 100f), new Vector3(0f,-275,0f)); // Generate button for starting game
        resetButton = GenerateButton("ResetButton", "Reset", Color.red, new Vector2(200f, 100f), new Vector3(-475f,-275,0f)); // Generate button for restarting game
        
        resetButton.gameObject.SetActive(false); // Set reset button to inactive
        upButton.gameObject.SetActive(false); // Set up button to inactive
        downButton.gameObject.SetActive(false); // Set down button to inactive
        leftButton.gameObject.SetActive(false); // Set left button to inactive
        rightButton.gameObject.SetActive(false); // Set right button to inactive
        
    }

    void AddListeners()
    {
        upButton.onClick.AddListener(delegate { UpdateSnakeDirection(SnakePlayerController.eSnakeDirection.Up); }); // Add listener to up button
        downButton.onClick.AddListener(delegate { UpdateSnakeDirection(SnakePlayerController.eSnakeDirection.Down); }); // Add listener to down button
        leftButton.onClick.AddListener(delegate { UpdateSnakeDirection(SnakePlayerController.eSnakeDirection.Left); }); // Add listener to left button
        rightButton.onClick.AddListener(delegate { UpdateSnakeDirection(SnakePlayerController.eSnakeDirection.Right); }); // Add listener to right button
