        snakePlayerController = playerParent.AddComponent<SnakePlayerController>(); // Add SnakePlayerController component to player parent
        snakePlayerController.SetUIController(this); // Set UI controller
       
    }

    Button GenerateButton(string buttonName, string buttonText, Color buttonColor, Vector2 size, Vector3 localPosition) // Generate button
    {
        var buttonGameObject = new GameObject(buttonName); // Create button game object
        buttonGameObject.transform.SetParent(gameObject.transform); // Set button game object parent to this game object
        Button button = buttonGameObject.AddComponent<Button>(); // Add button component to button game object
        var rectTransform = buttonGameObject.AddComponent<RectTransform>(); // Add rect transform component to button game object
        rectTransform.pivot = new Vector2(0.5f, 0.5f); // Set rect transform pivot
        rectTransform.anchorMin = new Vector2(0.5f, 0.5f); // Set rect transform anchor min
        rectTransform.anchorMax = new Vector2(0.5f, 0.5f); // Set rect transform anchor max
        rectTransform.anchoredPosition = new Vector2(0.5f, 0.5f); // Set rect transform anchored position
        rectTransform.sizeDelta = size; // Set rect transform size delta
        button.transform.localPosition = localPosition; // Set button local position
        button.transform.localScale = new Vector3(1f, 1f, 1f); // Set button local scale
        button.targetGraphic = buttonGameObject.AddComponent<Image>(); // Add image component to button game object and set it as target graphic
        button.targetGraphic.color = buttonColor; // Set button color

        var buttonTextComponent = GenerateText("Button Text", Color.white, buttonGameObject.transform, true); // Generate button text
        buttonTextComponent.text = buttonText; // Set button text
        buttonTextComponent.fontSize = 40; // Set button text font size
        buttonTextComponent.font = Resources.GetBuiltinResource(typeof(Font), "Arial.ttf") as Font; // Set button text font
        buttonTextComponent.color = Color.white; // Set button text color
        buttonTextComponent.alignment = TextAnchor.MiddleCenter; // Set button text alignment
        return button; // Return button
    }

    Text GenerateText(string textName, Color color, Transform parent = null, bool stretch = false) // Generate text
    {
        var textGameObject = new GameObject(textName); // Create text game object
        if (parent) // If parent is not null
        { 
            textGameObject.transform.SetParent(parent); // Set text game object parent to parent
        }
        else // If parent is null
        {
            textGameObject.transform.SetParent(gameObject.transform); // Set text game object parent to this game object
        }

        Text text = textGameObject.AddComponent<Text>(); // Add text component to text game object
        var rectTransform = textGameObject.GetComponent<RectTransform>(); // Get rect transform component from text game object
        if (stretch) // If stretch is true
        {
            rectTransform.pivot = new Vector2(0.5f, 0.5f); // Set rect transform pivot
            rectTransform.anchorMin = new Vector2(0f, 0f); // Set rect transform anchor min
            rectTransform.anchorMax = new Vector2(1f, 1f); // Set rect transform anchor max
            rectTransform.anchoredPosition = new Vector2(0.5f, 0.5f); // Set rect transform anchored position
            rectTransform.sizeDelta = new Vector2(0, 0); // Set rect transform size delta
        }
        else // If stretch is false
        {
            rectTransform.pivot = new Vector2(0.5f, 0.5f); // Set rect transform pivot
            rectTransform.anchorMin = new Vector2(0.5f, 0.5f); // Set rect transform anchor min
            rectTransform.anchorMax = new Vector2(0.5f, 0.5f); // Set rect transform anchor max
            rectTransform.anchoredPosition = new Vector2(0.5f, 0.5f); // Set rect transform anchored position
            rectTransform.sizeDelta = new Vector2(400, 100); // Set rect transform size delta
        }

        text.fontSize = 40; // Set text font size
        text.font = Resources.GetBuiltinResource(typeof(Font), "Arial.ttf") as Font; // Set text font
        text.color = color; // Set text color
        text.alignment = TextAnchor.MiddleCenter; // Set text alignment
        text.supportRichText = false; // Set support rich text to false
        text.transform.localScale = new Vector3(1f, 1f, 1f); // Set text local scale
        return text; // Return text
    }

    private void UpdateSnakeDirection(SnakePlayerController.eSnakeDirection newDirection) // On directional button click
    {
        snakePlayerController.UpdateDirection(newDirection); // Move player
    }
    
    private void StartGame()
    {
        ToggleStates(eGameState.Start);
        snakePlayerController.StartGame(); // Start game
    }
    
    private void ResetGame()
    {
        ToggleStates(eGameState.Reset);
        scoreText.text = "Score: 0"; // Set score text
        snakePlayerController.ResetGame(); // Reset player
    }

    public void OnGameOver()
    {
        ToggleStates(eGameState.GameOver); // Toggle states
        snakePlayerController.OnGameOver(); // On game over
        
    }

    private void ToggleStates(eGameState gameState) // Toggle states of buttons
    {
        switch (gameState)
        {
            case eGameState.Start:
                gameOverText.gameObject.SetActive(false); // Set game over text to inactive
                startButton.gameObject.SetActive(false); // Set start button to inactive
                resetButton.gameObject.SetActive(true); // Set reset button to active
                leftButton.gameObject.SetActive(true); // Set left button to active
                rightButton.gameObject.SetActive(true); // Set right button to active
                upButton.gameObject.SetActive(true); // Set up button to active
                downButton.gameObject.SetActive(true); // Set down button to active
                break;
            case eGameState.Reset:
                gameOverText.gameObject.SetActive(false); // Set game over text to inactive
                startButton.gameObject.SetActive(true); // Set start button to active
                resetButton.gameObject.SetActive(false); // Set reset button to inactive
                leftButton.gameObject.SetActive(false); // Set left button to inactive
                rightButton.gameObject.SetActive(false); // Set right button to inactive
                upButton.gameObject.SetActive(false); // Set up button to inactive
                downButton.gameObject.SetActive(false); // Set down button to inactive
                break;
            case eGameState.GameOver:
                gameOverText.gameObject.SetActive(true); // Set game over text to active
                startButton.gameObject.SetActive(true); // Set start button to active
                resetButton.gameObject.SetActive(false); // Set reset button to inactive
                leftButton.gameObject.SetActive(false); // Set left button to inactive
                rightButton.gameObject.SetActive(false); // Set right button to inactive
                upButton.gameObject.SetActive(false); // Set up button to inactive
                downButton.gameObject.SetActive(false); // Set down button to inactive
                break;
            
        }
    }

    public void AddScore()
    {
        int currentScore = Int32.Parse(scoreText.text.Substring(7)); // Get current score
        scoreText.text = "Score: " + (currentScore + 1); // Set score text to current score + 1 
    }
    public enum eGameState // Game state
    {
        Idle,
        Start,
        Reset,
        GameOver
    }
}

using System;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using Random = UnityEngine.Random;

public class SnakeEnvironmentController : MonoBehaviour
{
    private GameObject boardBase; // Board Base
    private GameObject boardBorders; // Board Borders
    private GameObject dot; // Dot
    private SnakePlayerController playerController; // Player controller
    private float obstacleSpawnChance = 0.2f; // Obstacle spawn chance
    
    void Start() // Start is called before the first frame update
    {
        playerController = GameObject.FindObjectOfType<SnakePlayerController>(); // Get player controller
        boardBase = CreateBoardBase(new Vector3(0, 0, 0.5f)); // Create board base
        boardBorders = CreateBoardBorders(); // Create board borders
        SpawnDot(); // Spawn dot

    }
    
    
    GameObject CreateBoardBase(Vector3 pos) // Create Board Base
    {
        GameObject boardBaseObj = GameObject.CreatePrimitive(PrimitiveType.Plane); // Create ground
        boardBaseObj.transform.position = pos; // Set BoardBase position
        boardBaseObj.transform.localScale = new Vector3(2, 1, 1); // Set ground scale
        boardBaseObj.transform.rotation = Quaternion.Euler(90, 180, 0); // Set BoardBase rotation
        boardBaseObj.name = "BoardBase"; // Set BoardBase name
        var meshRenderer = boardBaseObj.GetComponent<MeshRenderer>(); // Get mesh renderer
        meshRenderer.material.color = Color.gray; // Set BoardBase color to gray
        meshRenderer.material.SetFloat("_Metallic", 0f); // Set metallic");
        meshRenderer.material.SetFloat("_Smoothness", 0f); // Set _Smoothness");
        var groundCollider = boardBaseObj.AddComponent<BoxCollider>(); // Add box collider component to ground
        groundCollider.isTrigger = false; // Set is trigger
        groundCollider.size = new Vector3(10, 0.1f, 10); // Set box collider size
        return boardBaseObj;
    }

    GameObject CreateBoardBorders()
    {
        GameObject boardBordersObj = new GameObject("BoardBorders"); // Create board borders
        boardBordersObj.transform.SetParent(boardBase.transform); // Set board borders parent to board base
        boardBordersObj.transform.localPosition = new Vector3(0, 0, 0); // Set board borders position
        boardBordersObj.transform.localScale = new Vector3(1, 1, 1); // Set board borders scale
        boardBordersObj.transform.localRotation = Quaternion.Euler(0, 0, 0); // Set board borders rotation
        GameObject leftBorder = CreateBoardBorder(new Vector3(-5, 0, 0), new Vector3(1, 1, 10), boardBordersObj.transform); // Create left border
        GameObject rightBorder = CreateBoardBorder(new Vector3(5, 0, 0), new Vector3(1, 1, 10), boardBordersObj.transform); // Create right border
        GameObject topBorder = CreateBoardBorder(new Vector3(0, 0, 5), new Vector3(10, 1, 1), boardBordersObj.transform); // Create top border
        GameObject bottomBorder = CreateBoardBorder(new Vector3(0, 0, -5), new Vector3(10, 1, 1), boardBordersObj.transform); // Create bottom border
        return boardBordersObj;
    }
    
    GameObject CreateBoardBorder(Vector3 pos, Vector3 scale, Transform parent) // Create Board Border
    {
        GameObject boardBorderObj = GameObject.CreatePrimitive(PrimitiveType.Cube); // Create ground
        boardBorderObj.transform.SetParent(parent); // Set board border parent to board borders
        boardBorderObj.transform.localPosition = pos; // Set board border position
        boardBorderObj.transform.localScale = scale; // Set board border scale
        boardBorderObj.transform.localRotation = Quaternion.Euler(0, 0, 0); // Set board border rotation
        boardBorderObj.name = "Border"; // Set board border name
        var meshRenderer = boardBorderObj.GetComponent<MeshRenderer>(); // Get mesh renderer
        meshRenderer.material.color = Color.black; // Set board border color to blue
        meshRenderer.material.SetFloat("_Metallic", 0f); // Set metallic");
        meshRenderer.material.SetFloat("_Smoothness", 0f); // Set _Smoothness");
        var groundCollider = boardBorderObj.GetComponent<BoxCollider>(); // Add box collider component to ground
        groundCollider.isTrigger = true; // Set is trigger
        groundCollider.size = new Vector3(1, 1f, 1); // Set box collider size
        return boardBorderObj;
    }
    
    
    GameObject CreateDot(Vector3 pos) // Create dot
    {
        var dotObj = GameObject.CreatePrimitive(PrimitiveType.Sphere); // Create dot
        dotObj.transform.SetParent(transform); // Set dot parent to this game object
        dotObj.name = "Dot"; // Set dot name
        dotObj.GetComponent<MeshRenderer>().material.color = Color.red; // Set dot color to red
        dotObj.transform.position = pos; // Set dot position
        dotObj.transform.localScale = new Vector3(0.5f, 0.5f, 0.5f); // Set dot scale
        var dotCollider = dotObj.GetComponent<SphereCollider>(); // Add sphere collider component to dot
        dotCollider.isTrigger = true; // Set is trigger
        dotCollider.radius = 0.5f; // Set sphere collider radius
        dotCollider.center = new Vector3(0, 0f, 0); // Set sphere collider center
        return dotObj; // Return dot
    }
    
    private void SpawnDot() // Spawn dot
    {
        var forbiddenPositions = playerController.GetPlayerPositions(); // Get forbidden positions
        var possibleDotPositions = new List<Vector3>(); // 100 possible dot positions
        for (int i = 0; i < 100; i++)
        {
            var x = Random.Range(-4, 4); // Get random x position
            var y = Random.Range(-4, 4); // Get random z position
            var pos = new Vector3(x, y, 0); // Create position
            if (!forbiddenPositions.Contains(pos)) // If forbidden positions does not contain position
            {
                possibleDotPositions.Add(pos); // Add position to ten possible dot positions
            }
        }
        var dotPos = possibleDotPositions[Random.Range(0, possibleDotPositions.Count)]; // Get random dot position
        dot = CreateDot(dotPos); // Create dot
    }
    
    public void OnDotCollected()
    {
        Destroy(dot); // Destroy dot
        SpawnDot(); // Spawn dot
    }
    
    
    
    
   
}
using System;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;

public class SnakePlayerController : MonoBehaviour
{
    private GameObject player; // Player object
    private Rigidbody playerRigidbody; // Player rigidbody
    private Queue<GameObject> snakeBody = new(); // Snake body
    private List<Vector3> positionsHistory = new List<Vector3>();
    private float moveSpeed = 5f; // Move speed
    private float bodySpeed = 5f; // Body speed
    private int gap = 10; // Gap between body parts
    private SnakeUIController uiController; // UI controller 
    private SnakeUIController.eGameState uiState; // UI state
    private eSnakeDirection snakeDirection = eSnakeDirection.Right; // Current direction
    
    void Start() // Start is called before the first frame update
    {
        uiState = SnakeUIController.eGameState.Idle; // Set UI state to idle
        CreatePlayer(out player, "Player"); // Create player
        player.AddComponent<SnakePlayerCollisionController>(); // Add SnakePlayerCollisionController script to player
        EditCameraProperties(); // Edit camera properties
    }
    public void SetUIController(SnakeUIController controller) // Set UI controller
    {
        uiController = controller; // Set UI controller
    }

    public List<Vector3> GetPlayerPositions() // Get player position
    {
        List<Vector3> positions = new List<Vector3>(); // Create positions list
        if (player) // If player exists
        {
            positions.Add(player.transform.position); // Add player position to positions list
        }
        else // If player does not exist
        {
            positions.Add(new Vector3(0, 0, 0)); // Add zero vector to positions list
        }
        foreach (var bodyPart in snakeBody) // For each body part
        {
            positions.Add(bodyPart.transform.position); // Add body part position to positions list
        }

        return positions; // Return player position
    }
    void CreatePlayer(out GameObject playerObj, string objName) // Create player
    {
        playerObj = GameObject.CreatePrimitive(PrimitiveType.Sphere); // Create player
        playerObj.transform.SetParent(transform); // Set player parent to this game object
        playerObj.name = objName; // Set object name
        playerObj.GetComponent<MeshRenderer>().material.color = Color.white; // Set player color to white
        playerObj.transform.position = new Vector3(0, 0, 0); // Set player position
        playerRigidbody = playerObj.AddComponent<Rigidbody>(); // Add rigidbody component to player
        playerRigidbody.constraints = RigidbodyConstraints.FreezeRotationX | RigidbodyConstraints.FreezeRotationZ; // Freeze rotation on x and z axis
        playerRigidbody.useGravity = false; // Use gravity
        playerRigidbody.mass = 1; // Set mass
        playerRigidbody.drag = 0; // Set drag
        playerRigidbody.angularDrag = 0.05f; // Set angular drag
        playerRigidbody.interpolation = RigidbodyInterpolation.None; // Set interpolation
        playerRigidbody.collisionDetectionMode = CollisionDetectionMode.Continuous; // Set collision detection mode
        playerRigidbody.isKinematic = true; // Set is kinematic
        
    }

    public void OnDotCollected() // On dot collected
    {
        uiController.AddScore(); // Add score
        GrowSnake(); // Grow snake
    }

    private void GrowSnake() // Grow snake
    {
        string snakeBodyName = "SnakeBody" + snakeBody.Count; // Create snake body name
        CreatePlayer(out GameObject newBodyPart, snakeBodyName); // Create snake body
        if (snakeBody.Count == 0) // If snake body count is zero
        {
            newBodyPart.transform.localPosition = GetNextPosition(player.transform.localPosition); // Set snake body position to player position + offset
        }
        else // If snake body count is not zero
        {
            newBodyPart.transform.localPosition = GetNextPosition(snakeBody.Peek().transform.localPosition); // Set snake body position to last snake body position + offset
        } 
        
        snakeBody.Enqueue(newBodyPart); // Add snake body to snake body queue
    }
    
    private Vector3 GetNextPosition(Vector3 startPosition) // Get next position
    {
        var nextPosition = startPosition; // Set next position to start position
        switch (snakeDirection) // Switch snake direction
        {
            case eSnakeDirection.Up: // If snake direction is up
                nextPosition.z -= 1; // Set next position z to start position z - 1
                break; // Break
            case eSnakeDirection.Down: // If snake direction is down
                nextPosition.z += 1; // Set next position z to start position z + 1
                break; // Break
            case eSnakeDirection.Left: // If snake direction is left
                nextPosition.x += 1; // Set next position x to start position x + 1
                break; // Break
            case eSnakeDirection.Right: // If snake direction is right
                nextPosition.x -= 1; // Set next position x to start position x - 1
                break; // Break
        }
        return nextPosition; // Return next position
    }
    

    void EditCameraProperties() // Add camera follow script
    { 
        Camera camera = Camera.main; // Get main camera
        camera.transform.position = new Vector3(0, 0, -10); // Set camera position
        camera.transform.rotation = Quaternion.Euler(0, 0, 0); // Set camera rotation

    }
    
    
    public void UpdateDirection(eSnakeDirection direction) // update direction
    {
        if (direction == snakeDirection) // If direction is the same as current direction
        {
            return; // Return
        }

        // Check if player moves the snake in the opposite direction of the current direction then return
        switch (snakeDirection) 
        {
            case eSnakeDirection.Up: 
                if(direction == eSnakeDirection.Down) 
                    return;
                break;
            case eSnakeDirection.Down:
                if(direction == eSnakeDirection.Up)
                    return;
                break;
            case eSnakeDirection.Left:
                if(direction == eSnakeDirection.Right)
                    return;
                break;
            case eSnakeDirection.Right:
                if(direction == eSnakeDirection.Left)
                    return;
                break;
            
        }
        //else update the direction
        snakeDirection = direction;
        // Set player rotation based on direction
        switch (snakeDirection)
        {
            case eSnakeDirection.Up:
                player.transform.localRotation = Quaternion.Euler(0, 0, 90); // Set player rotation
                break;
            case eSnakeDirection.Down:
                player.transform.localRotation = Quaternion.Euler(0, 0, -90); // Set player rotation
                break;
            case eSnakeDirection.Left:
                player.transform.localRotation = Quaternion.Euler(0, 0, 180); // Set player rotation
                break;
            case eSnakeDirection.Right:
                player.transform.localRotation = Quaternion.Euler(0, 0, 0); // Set player rotation
                break;
        }
        
    }
    
    public void StartGame() // Start game
    {
        uiState = SnakeUIController.eGameState.Start; // Set UI state to start
    }

    public void ResetGame() // Reset game
    {
        uiState = SnakeUIController.eGameState.Idle; // Set UI state to idle
        DestroySnakeBody(); // Destroy snake body
        player.transform.position = new Vector3(0, 0, 0); // Set player position
        playerRigidbody.velocity = Vector3.zero; // Set player velocity to zero
    }

    public void OnGameOver() // On game over
    {
        uiState = SnakeUIController.eGameState.GameOver; // Set UI state to game over
        DestroySnakeBody(); // Destroy snake body
        player.transform.position = new Vector3(0, 0, 0); // Set player position
    }

    private void DestroySnakeBody()
    {
        foreach (var body in snakeBody) // For each body part 
        {
            Destroy(body); // Destroy body part
        }
        snakeBody.Clear(); // Clear snake body queue
        positionsHistory.Clear(); // Clear positions history list
    }
    private void Update() // Update is called once per frame
    {
        if(uiState != SnakeUIController.eGameState.Start) // If UI state is not start
        {
            return; // Return
        }
        
        Vector3 rightDirection = player.transform.right; // Get the right direction of the player

        // Calculate the new position
        Vector3 newPosition = player.transform.position + rightDirection * moveSpeed * Time.deltaTime;

        // Update the object's position
        player.transform.position = newPosition;

        positionsHistory.Insert(0, player.transform.localPosition); // Insert player position to positions history list

        int index = 0; // Index
        foreach (var body in snakeBody) // For each body part
        {
            Vector3 point = positionsHistory[Mathf.Clamp(index * gap, 0, positionsHistory.Count - 1)]; // Get point along the snakes path

            // Move body towards the point along the snakes path 
            Vector3 moveDirection = point - body.transform.position; 
            body.transform.position += moveDirection * (bodySpeed * Time.deltaTime); // Move body towards the point along the snakes path

            // Rotate body towards the point along the snakes path
            body.transform.LookAt(point); 

            index++;
        }

    }
    
    
    public enum eSnakeDirection // Current direction
    {
        Up,
        Down,
        Left,
        Right
    }
}
