using UnityEngine;

public class CannonPlayerController : MonoBehaviour
{
    private GameObject player; // Player object
    private Vector3 rotationPoint; // Rotation point
    private float shootForce = 10f; // Shoot force
    
    void Start() // Start is called before the first frame update
    {
        CreatePlayer(out player, "Player"); // Create player
        rotationPoint = player.transform.position - player.transform.up; // Set rotation point to the bottom of the player
        EditCameraProperties(); // Edit camera properties
    }
    
    
    void CreatePlayer(out GameObject playerObj, string objName) // Create player
    {
        playerObj = GameObject.CreatePrimitive(PrimitiveType.Cylinder); // Create player
        playerObj.transform.SetParent(transform); // Set player parent to this game object
        playerObj.name = objName; // Set object name
        playerObj.GetComponent<MeshRenderer>().material.color = Color.blue; // Set player color to blue
        playerObj.transform.position = new Vector3(0, 0, 0); // Set player position
        var playerRigidbody = playerObj.AddComponent<Rigidbody>(); // Add rigidbody component to player
        playerRigidbody.useGravity = false; // Use gravity
        playerRigidbody.mass = 1; // Set mass
        playerRigidbody.drag = 0; // Set drag
        playerRigidbody.angularDrag = 0.05f; // Set angular drag
        playerRigidbody.interpolation = RigidbodyInterpolation.None; // Set interpolation
        playerRigidbody.collisionDetectionMode = CollisionDetectionMode.Continuous; // Set collision detection mode
        playerRigidbody.isKinematic = true; // Set is kinematic
        
    }
    
    void EditCameraProperties() // Add camera follow script
    { 
        Camera camera = Camera.main; // Get main camera
        camera.transform.position = new Vector3(0, 5, -10); // Set camera position
        camera.transform.rotation = Quaternion.Euler(30, 0, 0); // Set camera rotation

    }
    
    public void UpdateAngle(Vector3 rotationAngle) // Update angle
    {
        
        if (player.transform.rotation.eulerAngles.z + rotationAngle.z < 90 ||
            player.transform.rotation.eulerAngles.z + rotationAngle.z > 270) // If angle is between 90 and 270 
        {
            player.transform.RotateAround(rotationPoint, player.transform.forward, rotationAngle.z); // Rotate player around rotation point by rotation angle
        }
            
        
    }
    
    public void Shoot() // Shoot
    {
        GameObject ball = CreateBall(); // Create ball
        ball.transform.position = player.transform.position + player.transform.up * 1.5f; // Set ball position
        ball.AddComponent<CannonBallController>(); // Add cannon ball controller component to ball
        ball.GetComponent<Rigidbody>().AddForce(player.transform.up * shootForce, ForceMode.Impulse); // Add force
    }

    private GameObject CreateBall()
    {
        GameObject ball = GameObject.CreatePrimitive(PrimitiveType.Sphere); // Create ball
        ball.transform.SetParent(transform); // Set ball parent to this game object
        ball.name = "Ball"; // Set ball name
        ball.GetComponent<MeshRenderer>().material.color = Color.red; // Set ball color to white
        ball.transform.position = new Vector3(0, 0, 0); // Set ball position
        var ballRigidbody = ball.AddComponent<Rigidbody>(); // Add rigidbody component to ball
        ballRigidbody.useGravity = true; // Use gravity
        ballRigidbody.mass = 1; // Set mass
        ballRigidbody.drag = 0; // Set drag
        ballRigidbody.angularDrag = 0.05f; // Set angular drag
        ballRigidbody.interpolation = RigidbodyInterpolation.None; // Set interpolation
        ballRigidbody.collisionDetectionMode = CollisionDetectionMode.Continuous; // Set collision detection mode
        ballRigidbody.isKinematic = false; // Set is kinematic
        return ball;
    }
    
    
}
