        borderColorBallPlayerController.OnGameOver(); // On game over
        
    }

    private void ToggleStates(eGameState gameState) // Toggle states of buttons
    {
        switch (gameState)
        {
            case eGameState.Start:
                startButton.gameObject.SetActive(false); // Set start button to inactive
                resetButton.gameObject.SetActive(true); // Set reset button to active
                leftButton.gameObject.SetActive(true); // Set left button to active
                rightButton.gameObject.SetActive(true); // Set right button to active
                upButton.gameObject.SetActive(true); // Set up button to active
                downButton.gameObject.SetActive(true); // Set down button to active
                break;
            case eGameState.Reset:
                startButton.gameObject.SetActive(true); // Set start button to active
                resetButton.gameObject.SetActive(false); // Set reset button to inactive
                leftButton.gameObject.SetActive(false); // Set left button to inactive
                rightButton.gameObject.SetActive(false); // Set right button to inactive
                upButton.gameObject.SetActive(false); // Set up button to inactive
                downButton.gameObject.SetActive(false); // Set down button to inactive
                break;
            case eGameState.GameOver:
                startButton.gameObject.SetActive(true); // Set start button to active
                resetButton.gameObject.SetActive(false); // Set reset button to inactive
                leftButton.gameObject.SetActive(false); // Set left button to inactive
                rightButton.gameObject.SetActive(false); // Set right button to inactive
                upButton.gameObject.SetActive(false); // Set up button to inactive
                downButton.gameObject.SetActive(false); // Set down button to inactive
                break;
            
        }
    }
    
    public enum eGameState // Game state
    {
        Idle,
        Start,
        Reset,
        GameOver
    }
}

