using System;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using Random = UnityEngine.Random;

public class BorderColorBallPlayerController : MonoBehaviour
{
    private GameObject player; // Player object
    private Rigidbody playerRigidbody; // Player rigidbody
    private float moveSpeed = 5f; // Move speed
    private BorderColorBallUIController uiController; // UI controller 
    private BorderColorBallUIController.eGameState uiState; // UI state
    private eBallDirection ballDirection = eBallDirection.Right; // Current direction
    
    void Start() // Start is called before the first frame update
    {
        uiState = BorderColorBallUIController.eGameState.Idle; // Set UI state to idle
        CreatePlayer(out player, "Player"); // Create player
        player.AddComponent<BorderColorBallPlayerCollisionController>(); // Add BorderColorBallPlayerCollisionController script to player
        EditCameraProperties(); // Edit camera properties
    }
    public void SetUIController(BorderColorBallUIController controller) // Set UI controller
    {
        uiController = controller; // Set UI controller
    }
    
    void CreatePlayer(out GameObject playerObj, string objName) // Create player
    {
        playerObj = GameObject.CreatePrimitive(PrimitiveType.Sphere); // Create player
        playerObj.transform.SetParent(transform); // Set player parent to this game object
        playerObj.name = objName; // Set object name
        playerObj.GetComponent<MeshRenderer>().material.color = Color.white; // Set player color to white
        playerObj.transform.position = new Vector3(0, 0, 0); // Set player position
        playerRigidbody = playerObj.AddComponent<Rigidbody>(); // Add rigidbody component to player
        playerRigidbody.constraints = RigidbodyConstraints.FreezeRotationX | RigidbodyConstraints.FreezeRotationZ; // Freeze rotation on x and z axis
        playerRigidbody.useGravity = false; // Use gravity
        playerRigidbody.mass = 1; // Set mass
        playerRigidbody.drag = 0; // Set drag
        playerRigidbody.angularDrag = 0.05f; // Set angular drag
        playerRigidbody.interpolation = RigidbodyInterpolation.None; // Set interpolation
        playerRigidbody.collisionDetectionMode = CollisionDetectionMode.Continuous; // Set collision detection mode
        playerRigidbody.isKinematic = true; // Set is kinematic
        
    }
    

    void EditCameraProperties() // Add camera follow script
    { 
        // Get camera and set properties to match a top down view of the board
        Camera camera = Camera.main; // Get main camera
        camera.transform.position = new Vector3(0, 0, -10); // Set camera position
        camera.transform.rotation = Quaternion.Euler(0, 0, 0); // Set camera rotation

    }
    
    
    public void UpdateDirection(eBallDirection direction) // update direction
    {
        if (direction == ballDirection) // If direction is the same as current direction
        {
            return; // Return
        }
        //else update the direction
        ballDirection = direction;
        // Set player rotation based on direction
        switch (ballDirection)
        {
            case eBallDirection.Up:
                player.transform.localRotation = Quaternion.Euler(0, 0, 90); // Set player rotation
                break;
            case eBallDirection.Down:
                player.transform.localRotation = Quaternion.Euler(0, 0, -90); // Set player rotation
                break;
            case eBallDirection.Left:
                player.transform.localRotation = Quaternion.Euler(0, 0, 180); // Set player rotation
                break;
            case eBallDirection.Right:
                player.transform.localRotation = Quaternion.Euler(0, 0, 0); // Set player rotation
                break;
        }
        
    }

    private eBallDirection CalculateNewDirection()
    {
        var newDirection = ballDirection; // Set new direction to current direction
        switch (ballDirection) // Switch current direction
        {
            case eBallDirection.Up: // If current direction is up
                newDirection = eBallDirection.Down; // Set new direction to Down
                break;
            case eBallDirection.Down: // If current direction is down
                newDirection = eBallDirection.Up; // Set new direction to Up
                break;
            case eBallDirection.Left: // If current direction is left
                newDirection = eBallDirection.Right; // Set new direction to Right
                break;
            case eBallDirection.Right: // If current direction is right
                newDirection = eBallDirection.Left; // Set new direction to Left
                break;
        }

        return newDirection;
    }
    
    private void UpdateColor(Color color) // Update color
    {
        player.GetComponent<MeshRenderer>().material.color = color; // Set player color
    }
    private Color GenerateRandomColor()
    {
        Color color = Random.ColorHSV(); // Generate random color
        return color; // Return color
    }
    
    
    public void OnBorderTriggerEnter() // On border trigger enter
    {
        var newDir = CalculateNewDirection(); // Calculate new direction
        UpdateDirection(newDir); // Update direction
        var newColor = GenerateRandomColor(); // Generate random color
        UpdateColor(newColor); // Update color
        
    }
    
    public void StartGame() // Start game
    {
        uiState = BorderColorBallUIController.eGameState.Start; // Set UI state to start
    }

    public void ResetGame() // Reset game
    {
        uiState = BorderColorBallUIController.eGameState.Idle; // Set UI state to idle
        player.transform.position = new Vector3(0, 0, 0); // Set player position
        playerRigidbody.velocity = Vector3.zero; // Set player velocity to zero
        UpdateColor(Color.white); // Set player color to white
    }

    public void OnGameOver() // On game over
    {
        uiState = BorderColorBallUIController.eGameState.GameOver; // Set UI state to game over
        player.transform.position = new Vector3(0, 0, 0); // Set player position
        UpdateColor(Color.white); // Set player color to white
    }
    
    private void Update() // Update is called once per frame
    {
        if(uiState != BorderColorBallUIController.eGameState.Start) // If UI state is not start
        {
            return; // Return
        }
        
        Vector3 rightDirection = player.transform.right; // Get the right direction of the player

        // Calculate the new position
        Vector3 newPosition = player.transform.position + rightDirection * moveSpeed * Time.deltaTime;

        // Update the object's position
        player.transform.position = newPosition;

        

    }
    
    
    public enum eBallDirection // Current direction
    {
        Up,
        Down,
        Left,
        Right
    }
}
