public class VolumeSlider : MonoBehaviour
{
    [SerializeField] private bool generateUI = true;
    [SerializeField] private Slider slider;
    [SerializeField] private Text volumeText;
    private RectTransform sliderHandle;

    void Start()
    {
        if (generateUI)
        {
            //generate the UI
            GenerateUISlider();
            GenerateUIVolumeText();

        }     
        //Add a listener to the slider to detect when the value changes
        slider.onValueChanged.AddListener(delegate { OnSliderValueChanged(); });
    }

    private void GenerateUISlider()
    {
        // Create the slider background GameObject
        GameObject sliderBackground = new GameObject("SliderBackground");
        Image sliderBackgroundImage = sliderBackground.AddComponent<Image>();
        sliderBackgroundImage.sprite = CreateColoredSprite(Color.gray);
        sliderBackground.transform.SetParent(transform);
        var sliderBackgroundRectTransform = sliderBackground.GetComponent<RectTransform>();
        sliderBackgroundRectTransform.anchorMin = new Vector2(0f, 0.25f);
        sliderBackgroundRectTransform.anchorMax = new Vector2(1f, 0.75f);
        sliderBackgroundRectTransform.pivot = new Vector2(0.5f, 0.5f);
        
        
        
        //create the slider fill area GameObject
        GameObject sliderFillArea = new GameObject("SliderFillArea");
        sliderFillArea.transform.SetParent(transform);
        var sliderFillAreaRectTransform = sliderFillArea.AddComponent<RectTransform>();
        sliderFillAreaRectTransform.anchorMin = new Vector2(0f, 0.25f);
        sliderFillAreaRectTransform.anchorMax = new Vector2(1f, 0.75f);
        sliderFillAreaRectTransform.pivot = new Vector2(0.5f, 0.5f);
        sliderFillAreaRectTransform.sizeDelta = Vector2.zero;
        
        
        // Create the slider fill GameObject
        GameObject sliderFill = new GameObject("SliderFill");
        Image sliderFillImage = sliderFill.AddComponent<Image>();
        sliderFillImage.sprite = CreateColoredSprite(Color.green);
        sliderFill.transform.SetParent(transform);
        
        //create the handle slider area GameObject
        GameObject sliderHandleArea = new GameObject("SliderHandleArea");
        sliderHandleArea.transform.SetParent(transform);
        var sliderHandleAreaRectTransform = sliderHandleArea.AddComponent<RectTransform>();
        sliderHandleAreaRectTransform.anchorMin = new Vector2(0f, 0f);
        sliderHandleAreaRectTransform.anchorMax = new Vector2(1f, 1f);
        sliderHandleAreaRectTransform.pivot = new Vector2(0.5f, 0.5f);
        sliderHandleAreaRectTransform.sizeDelta = Vector2.zero;
        
        
        // Create the slider handle GameObject
        GameObject sliderHandleObject = new GameObject("SliderHandle");
        sliderHandle = sliderHandleObject.AddComponent<RectTransform>();
        Image sliderHandleImage = sliderHandleObject.AddComponent<Image>();
        sliderHandleImage.sprite = CreateColoredSprite(Color.blue);
        sliderHandle.transform.SetParent(transform);

        // Create the Slider component
        GameObject sliderObject = new GameObject("Slider");
        slider = sliderObject.AddComponent<Slider>();
        slider.transform.SetParent(transform);
        slider.targetGraphic = sliderBackgroundImage;
        slider.fillRect = sliderFill.GetComponent<RectTransform>();
        slider.handleRect = sliderHandle;
        var sliderRectTransform = slider.GetComponent<RectTransform>();
        sliderRectTransform.sizeDelta = new Vector2(160, 20);
        

        // Set slider properties
        slider.minValue = 0;
        slider.maxValue = 100;
        slider.value = 100;

        // Set handle size and anchor
        sliderHandle.sizeDelta = new Vector2(20f, 0f);
        sliderHandle.anchorMin = new Vector2(1f, 0f);
        sliderHandle.anchorMax = new Vector2(1f, 1f);
        
        //reset parents
        sliderBackground.transform.SetParent(slider.transform);
        sliderFillArea.transform.SetParent(slider.transform);
        sliderFill.transform.SetParent(sliderFillArea.transform);
        sliderHandleArea.transform.SetParent(slider.transform);
        sliderHandle.transform.SetParent(sliderHandleArea.transform);
        
        //reset sizes
        sliderBackgroundRectTransform.sizeDelta = Vector2.zero;
        sliderFillAreaRectTransform.sizeDelta = Vector2.zero;
        sliderHandleArea.GetComponent<RectTransform>().sizeDelta = Vector2.zero;
        sliderFill.GetComponent<RectTransform>().sizeDelta = Vector2.zero;

        //reset positions
        sliderRectTransform.localPosition = Vector3.zero;
    }

   
    private void GenerateUIVolumeText()
    {
        //create the volume text GameObject
        var volumeTextGameObject = new GameObject("VolumeText");
        //add the text component to the gameobject and set the properties of the text
        volumeText = volumeTextGameObject.AddComponent<Text>();
        volumeTextGameObject.transform.SetParent(transform);
        var rectTransform = volumeTextGameObject.GetComponent<RectTransform>();
        rectTransform.pivot = new Vector2(0.5f, 0.5f);
        rectTransform.anchorMin = new Vector2(0.5f, 0.5f);
        rectTransform.anchorMax = new Vector2(0.5f, 0.5f);
        rectTransform.anchoredPosition = new Vector2(0.5f, 0.5f);
        rectTransform.sizeDelta = new Vector2(160, 30);
        volumeText.fontSize = 16;
        volumeText.font = Resources.GetBuiltinResource(typeof(Font), "Arial.ttf") as Font;
        volumeText.color = Color.white;
        volumeText.alignment = TextAnchor.MiddleCenter;
        volumeText.transform.localPosition = new Vector3(0f, 15f, 0f);
        //set the text to 100
        volumeText.text = "Volume: 100";
    }

    private Sprite CreateColoredSprite(Color color)
    {
        //create a texture with the color
        Texture2D texture = new Texture2D(1, 1);
        texture.SetPixel(0, 0, color);
        texture.Apply();
        //create a sprite with the texture and return it
        return Sprite.Create(texture, new Rect(0, 0, 1, 1), new Vector2(0.5f, 0.5f));
    }
    
    void OnSliderValueChanged()
    {
        //change the volume of the audio listener
        AudioListener.volume = slider.value;
        volumeText.text = "Volume: " + slider.value;
    }
}

