using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;

public class BG_ColorButtons : MonoBehaviour
{
    [SerializeField] private bool generateUI = true;
    [SerializeField] private Image background;
    [SerializeField] private Button colorButton1;
    [SerializeField] private Button colorButton2;

    private void Start()
    {
        //if generate UI is checked, generate the UI
        if (generateUI)
        {
            //Generate the UI
            GenerateUI();
        }
        else
        {
            //Add listeners to the buttons
            colorButton1.onClick.AddListener(delegate { OnColorChange(Color.red); });
            colorButton2.onClick.AddListener(delegate { OnColorChange(Color.blue); });
        }
    }
    
    //Generate UI Elements
    void GenerateUI()
    {
        background = GenerateImage();
        var horizontalLayoutGroup = GenerateHorizontalLayoutGroup();

        float yPos = GetComponent<RectTransform>().rect.y;
        horizontalLayoutGroup.transform.localPosition = new Vector3(0f, yPos, 0f);
        colorButton1 = GenerateButton("Color Button 1", Color.red, horizontalLayoutGroup.transform);
        colorButton2 = GenerateButton("Color Button 2", Color.blue, horizontalLayoutGroup.transform);
        
    }
    
    //Generate Horizontal Layout Group with custom settings
    HorizontalLayoutGroup GenerateHorizontalLayoutGroup()
    {
        //Create the Horizontal Layout Group GameObject
        var horizontalLayoutGroupGameObject = new GameObject("Horizontal Layout Group");
        //Set the parent of the Horizontal Layout Group GameObject to the current GameObject
        horizontalLayoutGroupGameObject.transform.SetParent(gameObject.transform);
        //Add the Horizontal Layout Group component to the GameObject
        var rectTransform = horizontalLayoutGroupGameObject.AddComponent<RectTransform>();
        //Set the properties of the Horizontal Layout Group
        rectTransform.pivot = new Vector2(0.5f, 0.5f);
        rectTransform.anchorMin = new Vector2(0f, 0.5f);
        rectTransform.anchorMax = new Vector2(1f, 0.5f);
        rectTransform.anchoredPosition = new Vector2(0f, 0f);
        rectTransform.sizeDelta = new Vector2(0f, 100f);
        var horizontalLayoutGroup = horizontalLayoutGroupGameObject.AddComponent<HorizontalLayoutGroup>();
        horizontalLayoutGroup.spacing = 10;
        horizontalLayoutGroup.childControlWidth = true;
        horizontalLayoutGroup.childControlHeight = true;
        horizontalLayoutGroup.childForceExpandWidth = true;
        horizontalLayoutGroup.childForceExpandHeight = true;
        horizontalLayoutGroup.childAlignment = TextAnchor.MiddleCenter;
        //Return the Horizontal Layout Group
        return horizontalLayoutGroup;

    }
    
    //Generate Button 
    Button GenerateButton(string buttonName, Color color, Transform parent = null)
    {
        //Create the Button GameObject
        var buttonGameObject = new GameObject(buttonName);
        //Set the parent of the Button GameObject to the current GameObject or the parent transform if it is not null
        buttonGameObject.transform.SetParent(parent == null ? gameObject.transform : parent);
        //Add the Button component to the GameObject
        Button button = buttonGameObject.AddComponent<Button>();
        //Set the properties of the Button
        var rectTransform = buttonGameObject.AddComponent<RectTransform>();
        rectTransform.pivot = new Vector2(0.5f, 0.5f);
        rectTransform.anchorMin = new Vector2(0.5f, 0.5f);
        rectTransform.anchorMax = new Vector2(0.5f, 0.5f);
        rectTransform.anchoredPosition = new Vector2(0.5f, 0.5f);
        rectTransform.sizeDelta = new Vector2(200, 50);
        button.transform.localPosition = new Vector3(0f, -200f, 0f);
        button.targetGraphic = buttonGameObject.AddComponent<Image>();
        button.targetGraphic.color = color;
        button.transition = Selectable.Transition.ColorTint;
        button.colors = new ColorBlock()
        {
            normalColor = color,
            highlightedColor = Color.gray,
            pressedColor = Color.black,
            disabledColor = Color.gray,
            colorMultiplier = 1,
            fadeDuration = 0.1f
        };
        //Add listener to button 
        button.onClick.AddListener(delegate { OnColorChange(color);  });
        //Return the Button
        return button;        
    }

    //Generate Image
    Image GenerateImage()
    {
        //Create the Image GameObject
        var imageGameObject = new GameObject("Background Image");
        //Set the parent of the Image GameObject to the current GameObject
        imageGameObject.transform.SetParent(gameObject.transform);
        //Add the Image component to the GameObject
        Image image = imageGameObject.AddComponent<Image>();
        //Set the properties of the Image
        var rectTransform = imageGameObject.GetComponent<RectTransform>();
        rectTransform.pivot = new Vector2(0.5f, 0.5f);
        rectTransform.anchorMin = new Vector2(0f, 0f);
        rectTransform.anchorMax = new Vector2(1f, 1f);
        rectTransform.anchoredPosition = new Vector2(0.5f, 0.5f);
        rectTransform.sizeDelta = new Vector2(0f, 0f);
        image.color = Color.white;
        //Return the Image
        return image;
        
    }

    //Change Background Color on Button Click
    void OnColorChange(Color color)
    {
        background.color = color;
    }
    
    
}

