using System;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;

public class PopupWindow : MonoBehaviour
{
    [SerializeField] private bool generateUI = true;
    [SerializeField] private GameObject popupWindow;
    [SerializeField] private Text popupText;
    [SerializeField] private Button closePopupButton;
    [SerializeField] private Text hintText;
    
    private void Start()
    {
        // Generate UI if it is not already generated
        if (generateUI)
        {
            GenerateUI();
        }
        // Add listeners to the button
        closePopupButton.onClick.AddListener(OnClosePopup);
        
    }

    void GenerateUI()
    {
        // Generate the popup window
        popupWindow = GenerateImage("Popup Window").gameObject;
        // Generate the popup text
        popupText = GenerateText("Popup Text", Color.black, popupWindow.transform, true);
        // Generate the hint text
        hintText = GenerateText("Hint Text", Color.white,null, true);
        // Generate the close button
        hintText.text = "Click anywhere to trigger the event!";
        // Set the text of the popup
        popupText.text = "This is the popup text";
        // Generate the close button
        closePopupButton = GenerateCloseButton("Close Popup Button", "X", Color.red, popupWindow.transform);
        // Set the popup window to be inactive
        popupWindow.SetActive(false);
        
    }

    private void OnClosePopup()
    {
        // Set the popup window to be inactive
        popupWindow.SetActive(false);
        // Set the hint text to be active
        hintText.gameObject.SetActive(true);
    }
    
    private void OnEventOccured()
    {
        // Set the hint text to be inactive
        hintText.gameObject.SetActive(false);
        // Set the popup window to be active
        popupWindow.SetActive(true);
    }
    
    private void Update()
    {
        // Check if the mouse button is pressed
        if (Input.GetMouseButtonDown(0))
        {
            // Check if the popup window is active
            if (popupWindow.activeSelf == false)
            {
                // Call the event
                OnEventOccured();
            }
        }
    }

    Image GenerateImage(string imageName)
    {
        // Generate the image game object
        var imageGameObject = new GameObject(imageName);
        // Set the parent of the image to be the game object
        imageGameObject.transform.SetParent(gameObject.transform);
        // Add the image component to the image game object
        Image image = imageGameObject.AddComponent<Image>();
        // Get the rect transform of the image game object
        var rectTransform = imageGameObject.GetComponent<RectTransform>();
        // set properties of the rect transform
        rectTransform.pivot = new Vector2(0.5f, 0.5f);
        rectTransform.anchorMin = new Vector2(0.5f, 0.5f);
        rectTransform.anchorMax = new Vector2(0.5f, 0.5f);
        rectTransform.anchoredPosition = new Vector2(0.5f, 0.5f);
        rectTransform.sizeDelta = new Vector2(500f, 500f);
        image.color = Color.white;
        // return the image
        return image;
        
    }
    
    // Generate a text component with the given parameters and return it
    Text GenerateText(string textName, Color color, Transform parent = null, bool stretch = false)
    {
        // Generate the text game object
        var textGameObject = new GameObject(textName);
        // Set the parent of the text game object to be the parent parameter if it is not null, otherwise set it to be the game object
        if (parent)
        {
            textGameObject.transform.SetParent(parent);
        }
        else
        {
            textGameObject.transform.SetParent(gameObject.transform);
        }
        // Add the text component to the text game object
        Text text = textGameObject.AddComponent<Text>();
        // Get the rect transform of the text game object
        var rectTransform = textGameObject.GetComponent<RectTransform>();
        // Set the properties of the rect transform
        if (stretch)
        {
            rectTransform.pivot = new Vector2(0.5f, 0.5f);
            rectTransform.anchorMin = new Vector2(0f, 0f);
            rectTransform.anchorMax = new Vector2(1f, 1f);
            rectTransform.anchoredPosition = new Vector2(0.5f, 0.5f);
            rectTransform.sizeDelta = new Vector2(0, 0);
        }
        else
        {
            rectTransform.pivot = new Vector2(0.5f, 0.5f);
            rectTransform.anchorMin = new Vector2(0.5f, 0.5f);
            rectTransform.anchorMax = new Vector2(0.5f, 0.5f);
            rectTransform.anchoredPosition = new Vector2(0.5f, 0.5f);
            rectTransform.sizeDelta = new Vector2(400, 100);
        }
        // Set the properties of the text component
        text.fontSize = 40;
        text.font = Resources.GetBuiltinResource(typeof(Font), "Arial.ttf") as Font;
        text.color = color;
        text.alignment = TextAnchor.MiddleCenter;
        text.supportRichText = false;
        // return the text component
        return text;
    }
    
    // Generate a button with the given parameters and return it
    Button GenerateCloseButton(string buttonName, string buttonText, Color buttonColor, Transform parent = null)
    {
        // Generate the button game object
        var buttonGameObject = new GameObject(buttonName);
        // Set the parent of the button game object to be the parent parameter if it is not null, otherwise set it to be the game object\
        buttonGameObject.transform.SetParent(parent ? parent : gameObject.transform);
        // Add the button component to the button game object
        Button button = buttonGameObject.AddComponent<Button>();
        // Get the rect transform of the button game object
        var rectTransform = buttonGameObject.AddComponent<RectTransform>();
        // Set the properties of the rect transform
        rectTransform.pivot = new Vector2(1f, 1f);
        rectTransform.anchorMin = new Vector2(1f, 1f);
        rectTransform.anchorMax = new Vector2(1f, 1f);
        rectTransform.anchoredPosition = new Vector2(0.5f, 0.5f);
        rectTransform.sizeDelta = new Vector2(50, 50);
        button.targetGraphic = buttonGameObject.AddComponent<Image>();
        button.targetGraphic.color = buttonColor;

        // Generate the text component of the button
        var buttonTextComponent = GenerateText("Button Text", Color.white, buttonGameObject.transform, stretch: true);
        // Set the properties of the text component
        buttonTextComponent.text = buttonText;
        buttonTextComponent.fontSize = 40;
        buttonTextComponent.font = Resources.GetBuiltinResource(typeof(Font), "Arial.ttf") as Font;
        buttonTextComponent.color = Color.white;
        buttonTextComponent.alignment = TextAnchor.MiddleCenter;
        // return the button
        return button;
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;

public class CountdownTimer : MonoBehaviour
{
    [SerializeField] private bool generateUI = true;
    [SerializeField] private Text timeText;
    [SerializeField] private Button startTimerButton;
    [SerializeField] private Button resetTimerButton;
    [SerializeField] private float totalTime = 10f;
    private bool timerIsRunning = false;
    private float currentTime;
    private float timeRemaining;
    
    
    
    private void Start()
    {
        // Generate UI
        if (generateUI)
        {
            GenerateUI();
        }
        // Add Listeners
        startTimerButton.onClick.AddListener(OnTimerStart);
        resetTimerButton.onClick.AddListener(OnTimerReset);
        // Set initial time
        currentTime = totalTime;
        // Display time
        DisplayTime();
    }

    void GenerateUI()
    {
        // Generate Time Text
        timeText = GenerateText("Time Text", Color.white, transform, false);
        timeText.text = "Time: " + timeRemaining;
        timeText.fontSize = 60;
        // Generate Buttons
        startTimerButton = GenerateButton("Start Timer Button", "Start Timer", Color.green);
        resetTimerButton = GenerateButton("Reset Timer Button", "Reset Timer", Color.red);
        // Set Button Positions
        startTimerButton.transform.localPosition = new Vector3(-200f, -200f, 0f);
        resetTimerButton.transform.localPosition = new Vector3(200f, -200f, 0f);
        
    }

    private void OnTimerStart()
    {
        // set timerIsRunning flag to true
        timerIsRunning = true;
    }
    private void OnTimerReset()
    {
        // set current time to total time and display time
        currentTime = totalTime;
        DisplayTime();
        // set timerIsRunning flag to false
        timerIsRunning = false;
    }
    
    private void Update()
    {
        // if timerIsRunning is true
        if (timerIsRunning)
        {
            // if current time is greater or equal to 0
            if (currentTime >= 0)
            {
                // decrement current time by deltaTime
                currentTime -= Time.deltaTime;
                // set time remaining to current time
                timeRemaining = currentTime;
                // display time
                DisplayTime();
            }
            else
            {
                Debug.Log("Time has run out!");
                // set current time to 0
                currentTime = 0;
                // display time
                DisplayTime();
                // set timerIsRunning flag to false
                timerIsRunning = false;
            }
        }
    }
    
    private void DisplayTime()
    {
        // convert current time to minutes and seconds
        int minutes = Mathf.FloorToInt(currentTime / 60);
        int seconds = Mathf.FloorToInt(currentTime % 60);
        // display time
