using System;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;

public class TriangleDrawer : MonoBehaviour
{
    [SerializeField] private bool generateUI = true;
    [SerializeField] private Image image;

    private void Start()
    {
        // Generate UI if needed
        if (generateUI)
        {
            GenerateUI();
        }
        // Draw triangle with background
        DrawTriangleWithBackground();
    }

    void GenerateUI()
    { 
        // create and assign image
        image = GenerateImage();
    }
    
    
    Image GenerateImage()
    {
        // create image and set it as child of this gameobject
        var imageGameObject = new GameObject("Image");
        imageGameObject.transform.SetParent(gameObject.transform);
        // set image component
        Image imageComponent = imageGameObject.AddComponent<Image>();
        // set rectransform component properties
        var rectTransform = imageGameObject.GetComponent<RectTransform>();
        rectTransform.pivot = new Vector2(0.5f, 0.5f);
        rectTransform.anchorMin = new Vector2(0.5f, 0.5f);
        rectTransform.anchorMax = new Vector2(0.5f, 0.5f);
        rectTransform.anchoredPosition = new Vector2(0.5f, 0.5f);
        rectTransform.sizeDelta = new Vector2(250f, 250f);
        imageComponent.color = Color.white;
        return imageComponent;
        
    }
    private void DrawTriangleWithBackground()
    {
        // create texture and assign it to image component
        int imageSize = 256;
        Texture2D texture = new Texture2D(imageSize, imageSize);
        image.sprite = Sprite.Create(texture, new Rect(0, 0, imageSize, imageSize), Vector2.one * 0.5f);
        // draw triangle on texture and apply it
        Color[] pixels = new Color[imageSize * imageSize]; // create array of pixels for texture 
        for (int i = 0; i < imageSize; i++) // iterate through pixels row by row
        {
            for (int j = 0; j < imageSize; j++) // iterate through pixels column by column
            {
                Vector2 currentPixel = new Vector2(i, j); // get current pixel position in pixels array
                // define triangle vertices positions in pixels array
                Vector2 p0 = new Vector2(imageSize / 2, imageSize * 3 / 4);  
                Vector2 p1 = new Vector2(imageSize / 4, imageSize / 4);  
                Vector2 p2 = new Vector2(imageSize * 3 / 4, imageSize / 4);

                if (PointInTriangle(currentPixel, p0, p1, p2)) // check if current pixel is inside triangle
                {
                    pixels[i * imageSize + j] = Color.yellow; // set pixel color to yellow if it is inside triangle
                }
                else
                {
                    pixels[i * imageSize + j] = Color.white; // set pixel color to white if it is outside triangle
                }
            }
        }
        // apply pixels array to texture and apply texture to image component
        texture.SetPixels(pixels);
        texture.Apply();
    }
    
    // check if point is inside triangle
    bool PointInTriangle(Vector2 p, Vector2 p0, Vector2 p1, Vector2 p2)
    {
        // check if point is inside triangle using barycentric coordinates
        float s = (p0.y * p2.x - p0.x * p2.y + (p2.y - p0.y) * p.x + (p0.x - p2.x) * p.y);
        float t = (p0.x * p1.y - p0.y * p1.x + (p0.y - p1.y) * p.x + (p1.x - p0.x) * p.y);
        
        if ((s < 0) != (t < 0))
            return false;
        
        float A = -p1.y * p2.x + p0.y * (p2.x - p1.x) + p0.x * (p1.y - p2.y) + p1.x * p2.y; 
        return A < 0 ? (s <= 0 && s + t >= A) : (s >= 0 && s + t <= A); 
    }
    
    
    
    
}

