public class SemicircleDrawer : MonoBehaviour
{
    [SerializeField] private bool generateUI = true;
    [SerializeField] private Image image;
    public int width = 256;
    public int height = 256;
    public Color circleColor = Color.red;
    private Texture2D texture;

    private void Start()
    {
        // Generate UI if needed
        if (generateUI)
        {
            GenerateUI();
        }
        // Draw semicircle with background
        DrawSemicircleWithBackground();
    }

    void GenerateUI()
    {
        // create and assign image
        image = GenerateImage();
    }


    Image GenerateImage()
    {
        // create image and set it as child of this gameobject
        var imageGameObject = new GameObject("Image");
        imageGameObject.transform.SetParent(gameObject.transform);
        // set image component
        Image imageComponent = imageGameObject.AddComponent<Image>();
        // set rectransform component properties
        var rectTransform = imageGameObject.GetComponent<RectTransform>();
        rectTransform.pivot = new Vector2(0.5f, 0.5f);
        rectTransform.anchorMin = new Vector2(0.5f, 0.5f);
        rectTransform.anchorMax = new Vector2(0.5f, 0.5f);
        rectTransform.anchoredPosition = new Vector2(0.5f, 0.5f);
        rectTransform.sizeDelta = new Vector2(250f, 250f);
        imageComponent.color = Color.white;
        return imageComponent;
    }

    private void DrawSemicircleWithBackground()
    {
        // create texture and assign it to image component
        texture = new Texture2D(width, height);
        image.sprite = Sprite.Create(texture, new Rect(0, 0, width, height), Vector2.one * 0.5f);
        // fill texture with black pixels and apply it
        Color[] clearPixels = new Color[width * height]; // create array of pixels for texture
        for (int i = 0; i < clearPixels.Length; i++) // iterate through clear pixels
        {
            clearPixels[i] = Color.black; // set clear pixel to black
        }
        texture.SetPixels(clearPixels);
        // draw semicircle on texture and apply it
        DrawSemicircle(new Vector2Int(width / 2, height / 2), width / 4);
        // apply texture
        texture.Apply();
    }

    private void DrawSemicircle(Vector2Int center, int radius)
    {
        // draw semicircle on texture
        int x = radius; // set x equal to radius
        int y = 0; // set y to 0 
        int radiusError = 1 - x; // set radius error to 1 - x

        while (x >= y) // while x is greater than or equal to y 
        {
            for (int i = center.x - x; i <= center.x + x; i++) // iterate through pixels 
            {
                texture.SetPixel(i, center.y + y, circleColor); // set pixel color to circle color
            }

            y++; // increment y

            if (radiusError < 0) // if radius error is less than 0
            {
                radiusError += 2 * y + 1; // increment radius error by 2 * y + 1
            }
            else
            {
                if (x >= y) // if x is greater than or equal to y
                {
                    for (int i = center.x - y; i <= center.x + y; i++) // iterate through pixels
                    {
                        texture.SetPixel(i, center.y + x, circleColor); // set pixel color to circle color
                    }
                }

                x--; // decrement x
                radiusError += 2 * (y - x + 1); // increment radius error by 2 * (y - x + 1)
            }
        }
    }
}

