using UnityEngine;
using UnityEngine.UI;

public class ParallelogramDrawer : MonoBehaviour
{
    private int textureWidth = 256; 
    private int textureHeight = 256;
    private Color fillColor = Color.blue;
    private Color parallelogramColor = Color.magenta;
    private Vector2Int startPoint = new Vector2Int(75, 75);
    private Vector2 parallelogramSize = new Vector2(50, 25);
    public float parallelogramAngle = 30f;

    private Texture2D texture;

    void Start()
    {
        // Create the texture and assign to the Image
        texture = new Texture2D(textureWidth, textureHeight);
        Image image = GenerateImage();
        image.sprite = Sprite.Create(texture, new Rect(0, 0, textureWidth, textureHeight), Vector2.one * 0.5f);

        // Fill the texture with the fill color
        Color[] pixels = new Color[textureWidth * textureHeight];
        for (int i = 0; i < pixels.Length; i++)
        {
            pixels[i] = fillColor;
        }
        texture.SetPixels(pixels);

        // Calculate parallelogram points
        Vector2 p1 = startPoint;
        Vector2 p2 = p1 + (Vector2) (Quaternion.Euler(0, 0, parallelogramAngle) * Vector2.right * parallelogramSize.x);
        Vector2 p3 = p2 + parallelogramSize.y * Vector2.down;
        Vector2 p4 = p1 + parallelogramSize.y * Vector2.down;

        // Draw the parallelogram
        DrawLine((int)p1.x, (int)p1.y, (int)p2.x, (int)p2.y, parallelogramColor); // DrawLine is a Bresenham's line algorithm
        DrawLine((int)p2.x, (int)p2.y, (int)p3.x, (int)p3.y, parallelogramColor); 
        DrawLine((int)p3.x, (int)p3.y, (int)p4.x, (int)p4.y, parallelogramColor);
        DrawLine((int)p4.x, (int)p4.y, (int)p1.x, (int)p1.y, parallelogramColor);
        
        // Fill the parallelogram with the parallelogram color (scanline algorithm)
        FillParallelogram((int)p1.x, (int)p1.y, (int)p2.x, (int)p2.y, (int)p3.x, (int)p3.y, (int)p4.x, (int)p4.y, parallelogramColor);
        texture.Apply();
    }
    Image GenerateImage()
    {
        // Create the Image GameObject and assign it to the Canvas
        var imageGameObject = new GameObject("Image");
        imageGameObject.transform.SetParent(gameObject.transform);
        // Add the Image Component
        Image imageComponent = imageGameObject.AddComponent<Image>();
        // Set the RectTransform properties
        var rectTransform = imageGameObject.GetComponent<RectTransform>();
        rectTransform.pivot = new Vector2(0.5f, 0.5f);
        rectTransform.anchorMin = new Vector2(0.5f, 0.5f);
        rectTransform.anchorMax = new Vector2(0.5f, 0.5f);
        rectTransform.anchoredPosition = new Vector2(0.5f, 0.5f);
        rectTransform.sizeDelta = new Vector2(256f, 256f);
        imageComponent.color = Color.white;
        return imageComponent;
        
    }
    
    // Bresenham's line algorithm
    void DrawLine(int x0, int y0, int x1, int y1, Color color)
    {
        // Make sure the coordinates are inside the texture
        int dx = Mathf.Abs(x1 - x0); // delta x
        int dy = Mathf.Abs(y1 - y0); // delta y 
        int sx = (x0 < x1) ? 1 : -1; // step x
        int sy = (y0 < y1) ? 1 : -1; // step y
        int err = dx - dy; // error value e_xy

        while (true)
        {
            texture.SetPixel(x0, y0, color); // set pixel at (x,y) to color

            if (x0 == x1 && y0 == y1) // if (x,y) reached (x1,y1) exit loop
                break;

            int e2 = 2 * err; // error value e_xy
            if (e2 > -dy) // e_xy+e_x > 0
            {
                err -= dy; // e_xy+e_x < 0
                x0 += sx; // x0 = x0 + sx
            }
            if (e2 < dx) // e_xy+e_y < 0
            {
                err += dx; // e_xy+e_y > 0
                y0 += sy; // y0 = y0 + sy
            }
        }
    }
    
    // Scanline algorithm (https://en.wikipedia.org/wiki/Scanline_rendering)
    void FillParallelogram(int x0, int y0, int x1, int y1, int x2, int y2, int x3, int y3, Color color)
    {
        // make sure the coordinates are inside the texture
        int minY = Mathf.Max(Mathf.Min(y0, y1, y2, y3), 0);
        int maxY = Mathf.Min(Mathf.Max(y0, y1, y2, y3), textureHeight - 1); 

        for (int y = minY; y <= maxY; y++) // for each scanline with y between minY and maxY
        {
            // find the x coordinates where the scanline intersects the edges of the parallelogram
            int startX = Mathf.Max(GetXIntersect(y, x0, y0, x1, y1), GetXIntersect(y, x2, y2, x3, y3));
            int endX = Mathf.Min(GetXIntersect(y, x0, y0, x1, y1), GetXIntersect(y, x2, y2, x3, y3));

            DrawLine(startX, y, endX, y, color); // draw a line between the intersections
        }
    }

    int GetXIntersect(int y, int x0, int y0, int x1, int y1)
    {
        // find the x coordinate where the scanline intersects the edge of the parallelogram
        return Mathf.FloorToInt(x0 + (float)(y - y0) / (y1 - y0) * (x1 - x0));
    }
    
}

