            clearPixels[i] = Color.red;
        }

        texture.SetPixels(clearPixels);  // set pixels to texture and apply it
        DrawTrapezium(new Vector2(width / 4, height / 4), new Vector2(width * 3 / 4, height / 4), new Vector2(width / 2, height * 3 / 4), texture, Color.white); // draw trapezium with white color and apply it to texture
        texture.Apply();
    }

    // Draw trapezium with given color and apply it to texture
    private void DrawTrapezium(Vector2 topLeft, Vector2 topRight, Vector2 bottomLeft, Texture2D texture, Color parallelogramColor)
    {
        // Get min and max x and y values of trapezium points
        int xMin = Mathf.FloorToInt(Mathf.Min(topLeft.x, topRight.x, bottomLeft.x));
        int xMax = Mathf.FloorToInt(Mathf.Max(topLeft.x, topRight.x, bottomLeft.x));
        int yMin = Mathf.FloorToInt(Mathf.Min(topLeft.y, topRight.y, bottomLeft.y));
        int yMax = Mathf.FloorToInt(Mathf.Max(topLeft.y, topRight.y, bottomLeft.y));
        
        // Get edge vectors and their lengths
        Vector2 edge1 = topRight - topLeft;
        Vector2 edge2 = bottomLeft - topLeft;
        float edge1Length = edge1.magnitude;
        float edge2Length = edge2.magnitude;

        // Iterate through all pixels in texture and check if they are inside trapezium
        for (int y = yMin; y < yMax; y++)
        {
            for (int x = xMin; x < xMax; x++)
            {
                // Get point and vector to point from top left point
                Vector2 point = new Vector2(x, y);
                Vector2 toPoint = point - topLeft;
                
                // Get dot products of edge vectors and vector to point
                float dot1 = Vector2.Dot(toPoint, edge1);
                float dot2 = Vector2.Dot(toPoint, edge2);

                // Get u and v values
                float u = dot1 / (edge1Length * edge1Length);
                float v = dot2 / (edge2Length * edge2Length);

                // Check if point is inside trapezium and set it to given color
                if (u >= 0 && u <= 1 && v >= 0 && v <= 1)
                {
                    texture.SetPixel(x, y, parallelogramColor); // set pixel to given color
                }
            }
        }
    }
    
    
    
    
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Serialization;
using UnityEngine.UI;

public class NavigationScreens : MonoBehaviour
{
    [SerializeField] private bool generateUI = true;
    [SerializeField] private GameObject[] screens;
    [SerializeField] private Button nextButton;
    [SerializeField] private Button previousButton;
    
    private GameObject currentScreen;
    private int currentScreenIndex = 0;
    private void Start()
    {
        // Generate UI if needed
        if (generateUI)
        {
            GenerateUI();
        }
        
    }

    void GenerateUI()
    {
        GenerateScreens(5); // Generate 5 screens
        GenerateButtons(); // Generate buttons
        RefreshScreens(); // Refresh screens
    }

    // Generate screens
    void GenerateScreens(int numberOfScreens)
    {
        screens = new GameObject[numberOfScreens]; // Initialize screens array with the number of screens needed
        for (int i = 0; i < numberOfScreens; i++) // Loop through the screens array 
        {
            var screen = GenerateScreenWithText(i); // Generate screen with text
            screens[i] = screen; // Add screen to screens array
        }
        currentScreen = screens[0]; // Set current screen to the first screen
    }

    // Generate screen with text
    GameObject GenerateScreenWithText(int index)
    {
        GameObject screen = new GameObject("Screen " + (index + 1).ToString()); // Create screen game object with name "Screen 1" etc.
        screen.transform.SetParent(gameObject.transform); // Set screen parent to this game object (NavigationScreens)
        var rectTransform = screen.AddComponent<RectTransform>(); // Add rect transform component to screen game object and get reference to it
        rectTransform.pivot = new Vector2(0.5f, 0.5f); // Set pivot to center of screen
        rectTransform.anchorMin = new Vector2(0.5f, 0.5f); // Set anchor min to center of screen
        rectTransform.anchorMax = new Vector2(0.5f, 0.5f); // Set anchor max to center of screen 
        rectTransform.anchoredPosition = new Vector2(0.5f, 0.5f); // Set anchored position to center of screen
        rectTransform.sizeDelta = new Vector2(500f, 500f); // Set size delta to 500x500
        var screenText = GenerateText("Screen: " + (index + 1).ToString(), Color.white, screen.transform, false); // Generate text with screen number
        screenText.text = "Screen: " + (index + 1).ToString(); // Set text to screen number 
        return screen; // Return screen game object

    }

    // Generate buttons
    void GenerateButtons()
    {
        previousButton = GenerateButton("PreviousButton", "Previous", Color.red); // Generate previous button
        nextButton = GenerateButton("NextButton", "Next", Color.green); // Generate next button
        previousButton.onClick.AddListener(OnPreviousButtonClick); // Add listener to previous button
        nextButton.onClick.AddListener(OnNextButtonClick); // Add listener to next button
        previousButton.transform.localPosition = new Vector3(-200f, -350f, 0f); // Set previous button position
        nextButton.transform.localPosition = new Vector3(200f, -350f, 0f); // Set next button position 
    }

    // Generate text 
    Text GenerateText(string textName, Color color, Transform parent = null, bool stretch = false)
    {
        // Generate text game object and add text component to it 
        var textGameObject = new GameObject(textName);
        if (parent) // If parent is not null, set text game object parent to parent
        {
            textGameObject.transform.SetParent(parent);
        }
        else
        {
            textGameObject.transform.SetParent(gameObject.transform);
        }
        // Set text game object rect transform properties
        Text text = textGameObject.AddComponent<Text>();
        var rectTransform = textGameObject.GetComponent<RectTransform>();
        if (stretch) // If stretch is true, set rect transform properties to stretch
        {
            rectTransform.pivot = new Vector2(0.5f, 0.5f);
            rectTransform.anchorMin = new Vector2(0f, 0f);
            rectTransform.anchorMax = new Vector2(1f, 1f);
            rectTransform.anchoredPosition = new Vector2(0.5f, 0.5f);
            rectTransform.sizeDelta = new Vector2(0, 0);
        }
        else
        {
            rectTransform.pivot = new Vector2(0.5f, 0.5f);
            rectTransform.anchorMin = new Vector2(0.5f, 0.5f);
            rectTransform.anchorMax = new Vector2(0.5f, 0.5f);
            rectTransform.anchoredPosition = new Vector2(0.5f, 0.5f);
            rectTransform.sizeDelta = new Vector2(400, 100);
        }
        //  Set text component properties
        text.fontSize = 40;
        text.font = Resources.GetBuiltinResource(typeof(Font), "Arial.ttf") as Font;
        text.color = color;
        text.alignment = TextAnchor.MiddleCenter;
        text.supportRichText = false;
        return text;
    }
    
    // Generate button 
    Button GenerateButton(string buttonName, string buttonText, Color buttonColor)
    {
        // Generate button game object and add button component to it
        var buttonGameObject = new GameObject(buttonName);
        buttonGameObject.transform.SetParent(gameObject.transform);
        Button button = buttonGameObject.AddComponent<Button>();
        // Set button game object rect transform properties
        var rectTransform = buttonGameObject.AddComponent<RectTransform>();
        rectTransform.pivot = new Vector2(0.5f, 0.5f);
        rectTransform.anchorMin = new Vector2(0.5f, 0.5f);
        rectTransform.anchorMax = new Vector2(0.5f, 0.5f);
        rectTransform.anchoredPosition = new Vector2(0.5f, 0.5f);
        rectTransform.sizeDelta = new Vector2(250, 100);
        button.transform.localPosition = new Vector3(0f, -200f, 0f);
        button.targetGraphic = buttonGameObject.AddComponent<Image>();
        button.targetGraphic.color = buttonColor;
        // Set button text component properties
        var buttonTextComponent = GenerateText("Button Text", Color.white, buttonGameObject.transform, true);
        buttonTextComponent.text = buttonText;
        buttonTextComponent.fontSize = 40;
        buttonTextComponent.font = Resources.GetBuiltinResource(typeof(Font), "Arial.ttf") as Font;
        buttonTextComponent.color = Color.white;
        buttonTextComponent.alignment = TextAnchor.MiddleCenter;
        return button;
    }
    
    void OnNextButtonClick() // On next button click
    {
        if (currentScreenIndex < screens.Length - 1) // If current screen index is less than the number of screens
        {
            currentScreenIndex++; // Increment current screen index
            currentScreen = screens[currentScreenIndex]; // Set current screen to the next screen
        }

        RefreshScreens(); // Refresh screens
    }
    void OnPreviousButtonClick() // On previous button click
    {
        if (currentScreenIndex > 0) // If current screen index is greater than 0
        {
            currentScreenIndex--; // Decrement current screen index
            currentScreen = screens[currentScreenIndex]; // Set current screen to the previous screen
        }

        RefreshScreens(); // Refresh screens
    }

    void RefreshScreens() // Refresh screens
    {
        for (int i = 0; i < screens.Length; i++) // Loop through screens array
        {
            screens[i].SetActive(false); // Set screen to inactive 
        }
        currentScreen.SetActive(true); // Set current screen to active 
        if(currentScreenIndex == 0) // If current screen index is 0
        {
            previousButton.interactable = false; // Set previous button to inactive
        }
        else  // If current screen index is not 0
        {
            previousButton.interactable = true; // Set previous button to active
        }

        if (currentScreenIndex == screens.Length - 1) // If current screen index is equal to the number of screens
        {
            nextButton.interactable = false; // Set next button to inactive
        }
        else // If current screen index is not equal to the number of screens
        {
            nextButton.interactable = true; // Set next button to active
        }
    }
   
    
}

