    }
    
    IEnumerator Rotate(GameObject rotateObject, float rotateDuration, float rotateMagnitude) // rotate object coroutine 
    {
        float elapsed = 0.0f; // elapsed time 

        while (elapsed < rotateDuration) // while elapsed time is less than rotate duration
        {
            rotateObject.transform.Rotate(0f, 0f, rotateMagnitude); // rotate object
            elapsed += Time.deltaTime; // add elapsed time
            yield return null; // return null
        }
