        buttonTextComponent.alignment = TextAnchor.MiddleCenter; // Set alignment to center
        return button; // Return button component
    }

    Text GenerateText(string textName, Color color, Transform parent = null, bool stretch = false) // Generate text component with name, color, parent, and stretch specified in parameters and return text component
    {
        var textGameObject = new GameObject(textName); // Create new game object for text
        if (parent) // If parent is specified in parameters, set text game object's parent to parent parameter
        {
            textGameObject.transform.SetParent(parent); // Set text game object's parent to parent parameter
        }
        else // If parent is not specified in parameters, set text game object's parent to this game object
        {
            textGameObject.transform.SetParent(gameObject.transform); // Set text game object's parent to this game object
        }

        Text text = textGameObject.AddComponent<Text>(); // Add text component to text game object
        var rectTransform = textGameObject.GetComponent<RectTransform>(); // Get rect transform component from text game object
        if (stretch) // If stretch is true, set rect transform to stretch to fill parent
        {
            rectTransform.pivot = new Vector2(0.5f, 0.5f); // Set pivot to center of text
            rectTransform.anchorMin = new Vector2(0f, 0f); // Set anchor min to bottom left of text
            rectTransform.anchorMax = new Vector2(1f, 1f); // Set anchor max to top right of text
            rectTransform.anchoredPosition = new Vector2(0.5f, 0.5f); // Set anchored position to center of text
            rectTransform.sizeDelta = new Vector2(0, 0); // Set size delta to 0 x 0
        }
        else
        {
            rectTransform.pivot = new Vector2(0.5f, 0.5f); // Set pivot to center of text
            rectTransform.anchorMin = new Vector2(0.5f, 0.5f); // Set anchor min to center of text
            rectTransform.anchorMax = new Vector2(0.5f, 0.5f); // Set anchor max to center of text
            rectTransform.anchoredPosition = new Vector2(0.5f, 0.5f); // Set anchored position to center of text
            rectTransform.sizeDelta = new Vector2(400, 100); // Set size delta to 400 x 100
        }

        text.fontSize = 40; // Set font size to 40
        text.font = Resources.GetBuiltinResource(typeof(Font), "Arial.ttf") as Font; // Set font to Arial
        text.color = color; // Set font color to color parameter
        text.alignment = TextAnchor.MiddleCenter; // Set alignment to center
        text.supportRichText = false; // Disable rich text
        return text; // Return text component
    }

    void OnJumpingButtonClick() // Called when jumping button is clicked
    {
        StartCoroutine(Jump(jumpingButton.gameObject, jumpDuration, jumpAmount)); // Start jump animation
    }
    
    IEnumerator Jump(GameObject jumpObject, float jumpDuration, float jumpMagnitude) // Jump animation coroutine
    {
        float elapsed = 0.0f; // Elapsed time since jump animation started

        while (elapsed < jumpDuration) // While elapsed time is less than jump duration, animate jump
        {
            float yOffset = Mathf.Sin(Mathf.PI * elapsed / jumpDuration) * jumpMagnitude; // Calculate y offset for jump animation
            jumpObject.transform.position = new Vector3(jumpObject.transform.position.x, originalPosition.y + yOffset, jumpObject.transform.position.z); // Set jump object's position to original position plus y offset
            elapsed += Time.deltaTime; // Increment elapsed time
            yield return null; // Wait until next frame
        }

        jumpObject.transform.position = originalPosition; // Set jump object's position to original position
    }
    
}

