using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;

public class ShakingButtonClick : MonoBehaviour
{
    [SerializeField] private bool generateUI = true;
    [SerializeField] private Button shakingButton;
    [SerializeField] private float shakeAmount = 5f;
    [SerializeField] private float shakeDuration = 0.5f;
    private Vector3 originalPosition;

    private void Start()
    {
        // Generate UI if needed
        if (generateUI)
        {
            GenerateUI();
        }
        // Add listener to button
        shakingButton.onClick.AddListener(OnShakingButtonClick);
        // Save original position
        originalPosition = shakingButton.transform.position;
    }

    void GenerateUI()
    {
        // if no button is assigned, generate one
        shakingButton = GenerateButton("ShakingButton", "ClickMe!", Color.red);
    }

    Button GenerateButton(string buttonName, string buttonText, Color buttonColor)
    {
        // Generate button game object
        var buttonGameObject = new GameObject(buttonName);
        // Set parent
        buttonGameObject.transform.SetParent(gameObject.transform);
        // Add button component
        Button button = buttonGameObject.AddComponent<Button>();
        // Add rect transform
        var rectTransform = buttonGameObject.AddComponent<RectTransform>();
        // Set rect transform properties
        rectTransform.pivot = new Vector2(0.5f, 0.5f);
        rectTransform.anchorMin = new Vector2(0.5f, 0.5f);
        rectTransform.anchorMax = new Vector2(0.5f, 0.5f);
        rectTransform.anchoredPosition = new Vector2(0.5f, 0.5f);
        rectTransform.sizeDelta = new Vector2(250, 100);
        button.transform.localPosition = new Vector3(0f, -200f, 0f);
        button.targetGraphic = buttonGameObject.AddComponent<Image>();
        button.targetGraphic.color = buttonColor;
        // Generate text component
        var buttonTextComponent = GenerateText("Button Text", Color.white, buttonGameObject.transform, true);
        buttonTextComponent.text = buttonText;
        buttonTextComponent.fontSize = 40;
        buttonTextComponent.font = Resources.GetBuiltinResource(typeof(Font), "Arial.ttf") as Font;
        buttonTextComponent.color = Color.white;
        buttonTextComponent.alignment = TextAnchor.MiddleCenter;
        // Return button
        return button;
    }

    Text GenerateText(string textName, Color color, Transform parent = null, bool stretch = false)
    {
        // Generate text game object
        var textGameObject = new GameObject(textName);
        // Set parent if provided or set to this game object
        if (parent)
        {
            textGameObject.transform.SetParent(parent);
        }
        else
        {
            textGameObject.transform.SetParent(gameObject.transform);
        }
        // Add text component
        Text text = textGameObject.AddComponent<Text>();
        // Add rect transform
        var rectTransform = textGameObject.GetComponent<RectTransform>();
        // Set rect transform properties based on stretch bool
        if (stretch)
        {
            rectTransform.pivot = new Vector2(0.5f, 0.5f);
            rectTransform.anchorMin = new Vector2(0f, 0f);
            rectTransform.anchorMax = new Vector2(1f, 1f);
            rectTransform.anchoredPosition = new Vector2(0.5f, 0.5f);
            rectTransform.sizeDelta = new Vector2(0, 0);
        }
        else
        {
            rectTransform.pivot = new Vector2(0.5f, 0.5f);
            rectTransform.anchorMin = new Vector2(0.5f, 0.5f);
            rectTransform.anchorMax = new Vector2(0.5f, 0.5f);
            rectTransform.anchoredPosition = new Vector2(0.5f, 0.5f);
            rectTransform.sizeDelta = new Vector2(400, 100);
        }
        // Set text properties
        text.fontSize = 40;
        text.font = Resources.GetBuiltinResource(typeof(Font), "Arial.ttf") as Font;
        text.color = color;
        text.alignment = TextAnchor.MiddleCenter;
        text.supportRichText = false;
        // Return text
        return text;
    }

    void OnShakingButtonClick()
    {
        // Start shaking animation
        StartCoroutine(Shake(shakingButton.gameObject, shakeDuration, shakeAmount));
    }
    
    IEnumerator Shake(GameObject shakeObject, float shakeDuration, float shakeMagnitude)
    {
        // Shake object for shakeDuration amount of time with shakeMagnitude amount of shake
        float elapsed = 0.0f;

        while (elapsed < shakeDuration)
        {
            // Generate random x and y position based on original position and shakeMagnitude
            float x = originalPosition.x + Random.Range(-1f, 1f) * shakeMagnitude;
            float y = originalPosition.y + Random.Range(-1f, 1f) * shakeMagnitude;
            // Set new position
            shakeObject.transform.position = new Vector3(x, y, originalPosition.z);
            // Increase elapsed time
            elapsed += Time.deltaTime;
            // Wait for next frame
            yield return null;
        }
        // Reset position
        shakeObject.transform.position = originalPosition;
    }
    
}

