using System;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;

public class ImageDisappear : MonoBehaviour , IPointerEnterHandler, IPointerExitHandler
{
    [SerializeField] private bool generateUI = true;
    [SerializeField] private Image image;
    [SerializeField] private float fadeDuration = 250f;
    private Color originalColor;
    
    private void Start()
    {
        // generate UI 
        if (generateUI)
        {
            GenerateUI();
        }
        // set original color as the color of the image
        originalColor = image.color;
    }

    void GenerateUI()
    {
        // generate image in the same object
        image = GenerateImageInSameObject();
    }

    Image GenerateImageInSameObject()
    {
        // add image component
        Image image = gameObject.AddComponent<Image>();
        // get rect transform
        var rectTransform = gameObject.GetComponent<RectTransform>();
        // set rect transform properties
        rectTransform.pivot = new Vector2(0.5f, 0.5f);
        rectTransform.anchorMin = new Vector2(0.5f, 0.5f);
        rectTransform.anchorMax = new Vector2(0.5f, 0.5f);
        rectTransform.anchoredPosition = new Vector2(0.5f, 0.5f);
        rectTransform.sizeDelta = new Vector2(250f, 250f);
        // set image color to cyan
        image.color = Color.cyan;
        // return image
        return image;
    }
    
    // when mouse enters the image
    public void OnPointerEnter(PointerEventData eventData)
    {
        // get original color
        var color = originalColor;
        // create a new color with rgb of original color but set alpha to 0 to make it transparent
        FadeIntoColor(new Color(color.r,color.g,color.b,0f));
    }
    
    // when mouse exits the image
    public void OnPointerExit(PointerEventData eventData)
    {
        // fade back into original color
        FadeIntoColor(originalColor);
    }

    void FadeIntoColor(Color color)
    {
        // start fade into color coroutine
        StartCoroutine(FadeIntoColorCoroutine(color));
    }

    IEnumerator FadeIntoColorCoroutine(Color color)
    {
        // initialize time to 0
        float time = 0f;
        // while time is less than fade duration
        while (time < fadeDuration)
        {
            // lerp image color to the color passed in the parameter
            float t = Mathf.Clamp01(time / fadeDuration);
            image.color = Color.Lerp(image.color, color, t);
            time += Time.deltaTime;
            yield return null;
        }
    }

    
}

