    void ScrollToElement(int element)
    {
        // calculate scroll to point and normalized position then animate scroll view
        var contentRectTransform = scrollRect.content.GetComponent<RectTransform>();
        // calculate target ratio
        float targetRatio = 1 - (float)element / (float)buttons.Length;
        // calculate scroll to point
        float scrollToPoint = (contentRectTransform.rect.height - scrollRect.viewport.rect.height) * targetRatio;
        // calculate normalized position
        float normalizedPosition = scrollToPoint / (contentRectTransform.rect.height - scrollRect.viewport.rect.height);
        // clamp normalized position to 0-1
        normalizedPosition = Mathf.Clamp01(normalizedPosition);
        // animate scroll view
        StartCoroutine(AnimateScrollView(normalizedPosition));
    }

    IEnumerator AnimateScrollView(float targetNormalizedPosition)
    {
        // animate scroll view to target normalized position
        while (!Mathf.Approximately(scrollRect.verticalNormalizedPosition, targetNormalizedPosition))
        {
            // animate scroll view to target normalized position using lerp
            scrollRect.verticalNormalizedPosition = Mathf.Lerp(scrollRect.verticalNormalizedPosition,
                targetNormalizedPosition, Time.deltaTime * scrollSpeed);
