public class Tooltip : MonoBehaviour, IPointerEnterHandler, IPointerExitHandler
{
    [SerializeField] private bool generateUI = true;
    [SerializeField] private GameObject tooltip;


    private void Start()
    {
        // Generate UI if it is not set 
        if (generateUI)
        {
            GenerateUI();
        }
        // Disable tooltip on start 
        tooltip.gameObject.SetActive(false);
    }

    void GenerateUI()
    {
        // generate variables for tooltip
        var image = GenerateImage("Image").gameObject;
        var tooltipGameObject = GenerateImageTooltip("ToolTip").gameObject;
        var tooltipText = GenerateText("Tooltip Text", Color.white, tooltipGameObject.transform, true);
        tooltipText.text = "Tooltip Text";
        tooltip = tooltipGameObject;
    }


    // On mouse enter show tooltip
    public void OnPointerEnter(PointerEventData eventData)
    {
        // Set tooltip active and set position to mouse position and offset it a bit
        tooltip.SetActive(true);
        tooltip.transform.position = Input.mousePosition + new Vector3(0f, -5f, 0f);
    }

    // On mouse exit hide tooltip
    public void OnPointerExit(PointerEventData eventData)
    {
        // Set tooltip inactive
        tooltip.SetActive(false);
    }

    Image GenerateImageTooltip(string imageName)
    {
        // Generate image for tooltip 
        var imageGameObject = new GameObject(imageName);
        // Set parent to this gameobject
        imageGameObject.transform.SetParent(gameObject.transform);
        // Add image component
        Image image = imageGameObject.AddComponent<Image>();
