using System.Collections;
using System.Collections.Generic;
using UnityEngine;

public class PlayerMoveForwardController : MonoBehaviour
{
    private GameObject player; // player object
    private Rigidbody playerRigidbody; // player rigidbody

    private GameObject ground; // ground object
    private float moveSpeed = 5f; // move speed of player
    
    
    void Start() // Start is called before the first frame update
    { 
        CreateGround(); // create ground
        CreatePlayer(); // create player
        AddCameraFollowScript(); // add camera follow script to camera
    }
    
    void CreatePlayer() // create player
    {
        player = GameObject.CreatePrimitive(PrimitiveType.Capsule); // create capsule
        player.transform.SetParent(transform); // set parent to this object
        player.name = "Player"; // set name
        player.transform.position = new Vector3(0, 0, 0); // set position
        playerRigidbody = player.AddComponent<Rigidbody>(); // add rigidbody
        playerRigidbody.constraints = RigidbodyConstraints.FreezeRotationX | RigidbodyConstraints.FreezeRotationZ; // freeze rotation
        playerRigidbody.useGravity = true; // use gravity
        playerRigidbody.mass = 1; // set mass
        playerRigidbody.drag = 0; // set drag
        playerRigidbody.angularDrag = 0.05f; // set angular drag
        playerRigidbody.interpolation = RigidbodyInterpolation.None; // set interpolation
        playerRigidbody.collisionDetectionMode = CollisionDetectionMode.Continuous; // set collision detection mode
        playerRigidbody.isKinematic = false; // set is kinematic
        var playerCollider = player.AddComponent<CapsuleCollider>(); // add capsule collider
        playerCollider.isTrigger = false; // set is trigger
        playerCollider.radius = 0.5f; // set radius
        playerCollider.height = 2; // set height
        playerCollider.center = new Vector3(0, 0.5f, 0); // set center
        
    }
    
    void CreateGround()
    {
        ground = GameObject.CreatePrimitive(PrimitiveType.Plane); // create plane primitive
        ground.transform.position = new Vector3(0, -1, 0); // set position of ground
        ground.transform.localScale = new Vector3(10, 1, 10); // set scale of ground
        ground.name = "Ground"; // set name of ground
        ground.GetComponent<MeshRenderer>().material.color = Color.blue; // set color of ground
        var groundCollider = ground.AddComponent<BoxCollider>(); // add box collider to ground
        groundCollider.isTrigger = false; // set is trigger
        groundCollider.size = new Vector3(10, 0.1f, 10); // set size of ground collider

    }
    
    void AddCameraFollowScript()
    {
        Camera camera = Camera.main; // get main camera
        camera.transform.position = new Vector3(0, 0, -10); // set position of camera
        camera.transform.rotation = Quaternion.Euler(0, 0, 0); // set rotation of camera
        var cameraFollow = camera.gameObject.AddComponent<CameraFollow>(); // add camera follow script to camera
        cameraFollow.SetVariables(player, 1f, 10f); // set variables of camera follow script

    }

    public void MoveForward() // move player forward
    {
        playerRigidbody.AddForce(transform.forward * moveSpeed, ForceMode.VelocityChange); // add force to player rigidbody
    }
    
    

    
}
