    private Button rightButton; //  Button for moving right
    private Button jumpButton; // Button for jumping
    private Button startButton; // Button for starting game
    private Button resetButton; // Button for restarting game
    private KeyCode leftKeyCode = KeyCode.LeftArrow; // Key code for moving left
    private KeyCode rightKeyCode = KeyCode.RightArrow; // Key code for moving right
    private KeyCode jumpKeyCode = KeyCode.Space; // Key code for jumping
    private EndlessRunnerPlayerController endlessRunnerPlayerController; // Endless runner player controller
    private EndlessRunnerEnvironmentController endlessRunnerEnvironmentController; // Endless runner environment controller
    
    private void Start() // Start is called before the first frame update
    {
        GenerateUI(); // Generate UI
        AddListeners(); // Add listeners
        CreateEnvironmentControllerObject(); // Create environment controller object
        CreatePlayerParent();  // Create parent for player
    }

    private void Update()
    {
        if (Input.GetKeyDown(KeyCode.Return)) // If enter key is pressed
        {
            StartGame(); // Start game
        }
        if (Input.GetKeyDown(KeyCode.R)) // If r key is pressed
        {
            ResetGame(); // Reset game
        }
        if (Input.GetKeyDown(leftKeyCode)) // If left key is pressed
        {
            OnDirectionalButtonClick(Vector3.left); // Move player left
        }
        if (Input.GetKeyDown(rightKeyCode)) // If right key is pressed
        {
            OnDirectionalButtonClick(Vector3.right); // Move player right
        }
        if (Input.GetKeyDown(jumpKeyCode)) 
        {
            OnJumpButtonClick(); // Jump
        }
    }

