    public void OnGameOver()
    {
        ToggleStates(eGameState.GameOver); // Toggle states
        endlessRunnerPlayerController.OnGameOver(); // On game over
        
    }

    private void ToggleStates(eGameState gameState) // Toggle states of buttons
    {
        switch (gameState)
        {
            case eGameState.Start:
                gameOverText.gameObject.SetActive(false); // Set game over text to inactive
                startButton.gameObject.SetActive(false); // Set start button to inactive
                resetButton.gameObject.SetActive(true); // Set reset button to active
                jumpButton.gameObject.SetActive(true); // Set jump button to active
                leftButton.gameObject.SetActive(true); // Set left button to active
                rightButton.gameObject.SetActive(true); // Set right button to active
                break;
            case eGameState.Reset:
                gameOverText.gameObject.SetActive(false); // Set game over text to inactive
                startButton.gameObject.SetActive(true); // Set start button to active
                resetButton.gameObject.SetActive(false); // Set reset button to inactive
                jumpButton.gameObject.SetActive(false); // Set jump button to inactive
                leftButton.gameObject.SetActive(false); // Set left button to inactive
                rightButton.gameObject.SetActive(false); // Set right button to inactive
                break;
            case eGameState.GameOver:
                gameOverText.gameObject.SetActive(true); // Set game over text to active
                startButton.gameObject.SetActive(true); // Set start button to active
                resetButton.gameObject.SetActive(false); // Set reset button to inactive
                jumpButton.gameObject.SetActive(false); // Set jump button to inactive
                leftButton.gameObject.SetActive(false); // Set left button to inactive
                rightButton.gameObject.SetActive(false); // Set right button to inactive
                break;
            
        }
    }
    
    public void UpdateScore(int score) // Update score
    {
        scoreText.text = "Score: " + score; // Set score text
    }
    
    public enum eGameState // Game state
    {
        Idle,
        Start,
        Reset,
        GameOver
    }
}

using System;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;
using Random = UnityEngine.Random;

public class EndlessRunnerEnvironmentController : MonoBehaviour
{
    private GameObject groundSegment; // Ground segment
    private float segmentLength = 10f; // Segment length
    private float spawnOffset = 50f; // Spawn offset
    private EndlessRunnerPlayerController playerController; // Player controller
    private Queue<GameObject> groundSegments = new(); // Ground segments
    private Queue <GameObject> obstacles = new(); // Obstacles
    private float obstacleSpawnChance = 0.2f; // Obstacle spawn chance
    private GameObject groundSegmentPrefab; // Ground segment prefab
    private GameObject obstaclePrefab; // Obstacle prefab
    
    void Start() // Start is called before the first frame update
    {
        playerController = GameObject.FindObjectOfType<EndlessRunnerPlayerController>(); // Get player controller
        groundSegmentPrefab = CreateGround(new Vector3(0, -1, 0)); // Create ground segment prefab
        obstaclePrefab = CreateObstaclePrefab(new Vector3(1000, 102, 0)); // Create obstacle prefab
        SpawnInitialSegments(); // Spawn initial segments
        
    }
    
    
    GameObject CreateGround(Vector3 pos) // Create ground
    {
        var ground = GameObject.CreatePrimitive(PrimitiveType.Plane); // Create ground
        ground.transform.position = pos; // Set ground position
        ground.transform.localScale = new Vector3(10, 1, 10); // Set ground scale
        ground.name = "Ground"; // Set ground name
        ground.GetComponent<MeshRenderer>().material.color = Color.blue; // Set ground color to blue
        var groundCollider = ground.AddComponent<BoxCollider>(); // Add box collider component to ground
        groundCollider.isTrigger = false; // Set is trigger
        groundCollider.size = new Vector3(10, 0.1f, 10); // Set box collider size
        return ground;
    }

    GameObject CreateObstaclePrefab(Vector3 pos) // Create obstacle
    {
        var obstacle = GameObject.CreatePrimitive(PrimitiveType.Cube); // Create ground
        obstacle.transform.position = pos; // Set ground position
        obstacle.transform.localScale = new Vector3(2, 2, 2); // Set ground scale
        obstacle.name = "ObstaclePrefab"; // Set ground name
        obstacle.GetComponent<MeshRenderer>().material.color = Color.red; // Set ground color to blue
        var boxCollider = obstacle.AddComponent<BoxCollider>(); // Add box collider component to ground
        boxCollider.isTrigger = false; // Set is trigger
        boxCollider.size = new Vector3(1, 1f, 1); // Set box collider size
        return obstacle; // Return obstacle
    }
    
     private void Update() // Update is called once per frame
    {
        // Check if the player has moved beyond the spawnOffset, then spawn a new segment.
        if (playerController.GetPlayerPosition().z > transform.position.z - spawnOffset)
        {
            SpawnGroundSegment(); // Spawn ground segment
            DestroyOldestSegment(); // Destroy oldest segment
            DestroyOldestObject(); // Destroy oldest object
        }
    }

    private void SpawnInitialSegments()
    {
        // Spawn initial ground segments to fill the scene.
        int initialSegmentCount = Mathf.CeilToInt(spawnOffset / segmentLength); // Get initial segment count
        for (int i = 0; i < initialSegmentCount; i++) // Loop through initial segment count
        {
            SpawnGroundSegment();
        }
    }

    private void SpawnGroundSegment() // Spawn ground segment
    {
        // Spawn a new ground segment.
        Vector3 spawnPosition = new Vector3(0, -1, transform.position.z + segmentLength); // Set spawn position
        GameObject newSegment = Instantiate(groundSegmentPrefab, spawnPosition, Quaternion.identity); // Create new segment

        // Add the new segment to the queue.
        groundSegments.Enqueue(newSegment); // Add new segment to queue

        // Move the GroundManager forward.
        transform.position += Vector3.forward * segmentLength; // Move ground manager forward

        // Randomly spawn obstacles on this segment.
        if (Random.value < obstacleSpawnChance) // if random value is less than obstacle spawn chance
        {
            var randomX = Random.Range(-5f, 5f); // Get random x position
            var obstacleSpawnPosition = new Vector3(randomX, 0, newSegment.transform.position.z); // Set obstacle spawn position
            CreateObstacle(obstacleSpawnPosition); // Create obstacle
        }
    }

    private void DestroyOldestSegment() // Destroy oldest segment
    {
        // Check if there are more segments than needed to cover the spawnOffset.
        int maxSegments = Mathf.CeilToInt(spawnOffset / segmentLength) + 1; // max segments
        if (groundSegments.Count > maxSegments) // if there are more segments than needed
        {
            GameObject oldestSegment = groundSegments.Dequeue(); // get oldest segment
            Destroy(oldestSegment); // destroy oldest segment
        }
    }
    
    private void DestroyOldestObject()
    {
        // Check if there are more objects than needed.
        int maxObjects = 15; // max objects 
        if (obstacles.Count > maxObjects) // if there are more objects than needed
        {
            GameObject obstacle = obstacles.Dequeue(); // get oldest object
            Destroy(obstacle); // destroy oldest object
        }
    }
    public void CreateObstacle(Vector3 pos)
    {
        // Create and position an obstacle at the specified position.
        var obstacle = Instantiate(obstaclePrefab, pos, Quaternion.identity); // Create obstacle
        obstacle.name = "Obstacle"; // Set obstacle name
        obstacles.Enqueue(obstacle); // Add obstacle to queue
    }

    public void Reset() // Reset
    {
        // Destroy all existing ground segments, obstacles, and clear the queue.
        foreach (var segment in groundSegments) // Loop through ground segments
        {
            Destroy(segment); // Destroy ground segment
        }
        groundSegments.Clear(); // Clear ground segments queue

        // Reset the GroundManager's position to the starting point.
        transform.position = new Vector3(0, -1, 0); // Reset position

        // Spawn initial ground segments again.
        SpawnInitialSegments(); // Spawn initial segments
    }
    
    
   
}
using System;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;

public class EndlessRunnerPlayerController : MonoBehaviour
{
    private GameObject player; // Player object
    private Rigidbody playerRigidbody; // Player rigidbody
    private float moveSpeed = 5f; // Move speed
    private EndlessRunnerUIController uiController; // UI controller
    private EndlessRunnerUIController.eGameState uiState; // UI state
    
    void Start() // Start is called before the first frame update
    {
        uiState = EndlessRunnerUIController.eGameState.Idle;
        CreatePlayer(); // Create player
        AddCameraFollowScript(); // Add camera follow script
    }
    public void SetUIController(EndlessRunnerUIController controller) // Set UI controller
    {
        uiController = controller; // Set UI controller
    }

    public Vector3 GetPlayerPosition() // Get player position
    {
        return player.transform.position; // Return player position
    }
    void CreatePlayer() // Create player
    {
        player = GameObject.CreatePrimitive(PrimitiveType.Capsule); // Create player
        player.transform.SetParent(transform); // Set player parent to this game object
        player.name = "Player"; // Set player name
        player.GetComponent<MeshRenderer>().material.color = Color.yellow; // Set player color to yellow
        player.transform.position = new Vector3(0, 0, 0); // Set player position
        playerRigidbody = player.AddComponent<Rigidbody>(); // Add rigidbody component to player
        playerRigidbody.constraints = RigidbodyConstraints.FreezeRotationX | RigidbodyConstraints.FreezeRotationZ; // Freeze rotation on x and z axis
        playerRigidbody.useGravity = true; // Use gravity
        playerRigidbody.mass = 1; // Set mass
        playerRigidbody.drag = 0; // Set drag
        playerRigidbody.angularDrag = 0.05f; // Set angular drag
        playerRigidbody.interpolation = RigidbodyInterpolation.None; // Set interpolation
        playerRigidbody.collisionDetectionMode = CollisionDetectionMode.Continuous; // Set collision detection mode
        playerRigidbody.isKinematic = false; // Set is kinematic
        var playerCollider = player.AddComponent<CapsuleCollider>(); // Add capsule collider component to player
        playerCollider.isTrigger = false; // Set is trigger
        playerCollider.radius = 0.5f; // Set capsule collider radius
        playerCollider.height = 2; // Set capsule collider height
        playerCollider.center = new Vector3(0, 0.5f, 0); // Set capsule collider center
        var playerCollisionController = player.AddComponent<EndlessRunnerPlayerCollisionController>(); // Add player collision controller script to player
        
    }
    

    void AddCameraFollowScript() // Add camera follow script
    { 
        Camera camera = Camera.main; // Get main camera
        camera.transform.position = new Vector3(0, 3, -10); // Set camera position
        camera.transform.rotation = Quaternion.Euler(20, 0, 0); // Set camera rotation
        var cameraFollow = camera.gameObject.AddComponent<CameraFollow>(); // Add camera follow script to camera
        cameraFollow.SetVariables(player, 50f, 10f); // Set camera follow variables

    }
    
    
    public void Move(Vector3 direction) // Move player
    {
        if (playerRigidbody.velocity.x > 10f || playerRigidbody.velocity.x < -10f) // If player velocity is greater than 10 or less than -10
        {
            playerRigidbody.velocity = new Vector3(playerRigidbody.velocity.x, playerRigidbody.velocity.y, 0f); // Set player velocity to 0 on z axis
        }
        playerRigidbody.AddForce(direction * moveSpeed, ForceMode.Impulse); // Add forward force to player rigidbody
    }
    
    public void Jump() // Jump
    {
        if(Mathf.Abs(playerRigidbody.velocity.y) > 0.5f) // If player velocity is greater than 0.5
        {
            return; // Return
        }
        playerRigidbody.AddForce(Vector3.up * 10f, ForceMode.Impulse); // Add jump force to player rigidbody
    }


    public void StartGame() // Start game
    {
        uiState = EndlessRunnerUIController.eGameState.Start; // Set UI state to start
    }

    public void ResetGame() // Reset game
    {
        uiState = EndlessRunnerUIController.eGameState.Idle; // Set UI state to idle
        player.transform.position = new Vector3(0, 0, 0); // Set player position
        playerRigidbody.velocity = Vector3.zero; // Set player velocity to zero
    }

    public void OnGameOver() // On game over
    {
        uiState = EndlessRunnerUIController.eGameState.GameOver; // Set UI state to game over
        player.transform.position = new Vector3(0, 0, 0); // Set player position
    }
    
    private void Update() // Update is called once per frame
    {
        if(uiState != EndlessRunnerUIController.eGameState.Start) // If UI state is not start
        {
            return; // Return
        }
        int score = (int) (player.transform.position.z * 10); // Get score
        uiController.UpdateScore(score); // Update score
        
        //if player is falling
        if (player.transform.position.y < -10) // If player position is less than -10
        {
            uiController.OnGameOver(); // On game over
        }
    }

    private void FixedUpdate() // Fixed update is called once per physics update
    {
        if(uiState != EndlessRunnerUIController.eGameState.Start) // If UI state is not start
        {
            return; // Return
        }
        if (player) // If player exists
        {
            var currentVelocity = playerRigidbody.velocity; // Get current velocity
            if(playerRigidbody.velocity.magnitude > 100f) // If player velocity is greater than 100
            {
                playerRigidbody.velocity = currentVelocity; // Set player velocity to current velocity
            }
            else
            {
                playerRigidbody.AddForce(Vector3.forward * (moveSpeed * 2f),
                    ForceMode.Acceleration); // Add force to player rigidbody
            }
        }
    }
}
